/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200120-6","meetingId":"r02-cm01","date":"2020年1月20日","dateIso":"2020-01-20","committee":"区民委員会","time":"午後 １時００分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"「しながわ地域貢献活動展」の開催","agenda":"「しながわ地域貢献活動展」の開催","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"ここの参加団体、６０団体とありますけれども、どのような形で募集をしたのか、どういう形でこの中で選ばれたのか説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"団体につきましては、先ほどの資料の２枚目に今回、パンフレットをつけさせていただいておりまして、その裏面に参加団体があります。９月の段階で広報しながわで２月にこのようなイベントを出しますので、こちらで募集いたしますということで応募いただいた団体となっております。","id":"exchange-001"}]},{"id":"topic-02","title":"「第３０回伝統の技と味／しながわ展」の開催","agenda":"「第３０回伝統の技と味／しながわ展」の開催","exchanges":[{"speaker":"こんの副委員長","kind":"意見","question":"２点。参考までにまず１点ですけれども、その辺が１点と、中学校とかにはお知らせとかはどうされていますかということですとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"基本的にそういう手法なのですけれども、定番の方々にちょっとなっているという傾向がうかがえるかです。これは教育委員会と連携をしながら、そうした中で、教育委員会を通じてご周知をさせていただいているところです。","id":"exchange-002"},{"speaker":"こんの副委員長","kind":"確認","question":"その中でも同じところというところはいろいろな皆さん思いがあってのことだと思うので、よくわかりました。中学校、いわゆる学校のお手紙配布物の中の１つとしてそういうのが入っているかどうかというところを最後、確認させてください。","respondent":"山崎商業・ものづくり課長","answer":"イベントの周知に関しましては、おっしゃいましたとおり、全ての学校にご周知を申し上げているところです。","id":"exchange-003"}]},{"id":"topic-03","title":"「ウーマンズビジネスグランプリ２０２０」の開催","agenda":"「ウーマンズビジネスグランプリ２０２０」の開催","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"一番上の３行のところの２行目から優れたアイデアを持つ女性の区内での創業を促進し、これは具体的には一体どういうことなのでしょうか。「区内での創業を促進」ということは具体的にどういうことかということです。","respondent":"山崎商業・ものづくり課長","answer":"その中では３０％の方が区内創業に結びついているという状況です。区民の方の比率としますと、３５％ぐらいがファイナリストにいるのですけれども、区内で必ずしも創業に結びついているというわけでもないです。","id":"exchange-004"}]},{"id":"topic-04","title":"「ＳＨＩＮＡＧＡＷＡイノベーションフォーラム２０２０ｉｎ五反田バレー」の開催","agenda":"「ＳＨＩＮＡＧＡＷＡイノベーションフォーラム２０２０ｉｎ五反田バレー」の開催","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"そこら辺を課長としてはどうお考えでしょう。重点の置き方をどうお考えかとちょっと思いましたとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"今年、本委員会でも中小ベンチャー企業支援について取り上げていただいて。少し行政としてこういった機会を設けて、いろいろなことが大きく花開くまでの間はしばらくはこうした事業も必要かとは所管課としては思うところです。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"私も全く否定するつもりはないのですけれども、重点の置き方の問題ですよね。廃業せざるを得なかったという商店のお声も最近伺ったりしましたので、ちょっとお伺いしてみました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"木村委員","kind":"意見","question":"委員から大変重要なお金の使い方ということでしょうけれども、それは別に置いておいて、この４Ｇと５Ｇとの違いを我々は全然わからないのですよ。４Ｇがどうであって、そして５Ｇになればどのようになるのかというのを何か簡単に説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"防犯のための防犯カメラが設置されていて、要はテレビが４Ｋ時代になって、そんなところに入っているところです。ちょっとうまく説明ができなくて申しわけないです。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"おくの委員の意見と全く今回は真逆で質問をさせていただきたいと思っています。この時期によくこの講演をやっていただけましたという私は思いで質問しようと思うのですけれども、まず５ＧのＧは何の英語の略か尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"世代をあらわすジェネレーションのＧです。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"３０代のときはユーチューブというのもなかったわけですけれども、そこの速度等が上がるわけですから、大分変わっていくと私は思っております。５Ｇになった時代にどうなっていくかを、税金をかけてやるわけですから、その辺についてはいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"もう既に２２２名の応募があるということで、おそらく昨年もそうであったのですけれども、キャパの４００名は集まっていただけるものと考えています。それのベースになるのが…","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問・要望","question":"そうすると、なぜ今からこの５Ｇの、まず講演をやるわけですからというと、私の個人的意見でいうと、この行政のいわゆるサービス。ですからせっかくこういう講演を７００万、もうぜひ１人でも多くの方にこれを聞いてもらって、こういう時代が来るのだよと。","respondent":"山崎商業・ものづくり課長","answer":"いろいろ語る議論の場は、先ほどと重複しますけれども品川の大きな一つの産業の特徴であります情報通信業の集積などの活性化とあわせまして、しっかり対応してまいりたいと考えるところです。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"５Ｇを進めることによって、少子高齢化問題、経済的格差の是正などの社会問題を解決できるというお話がネットにも書いてあるのです。逆に言うと５Ｇを使うとどういった形で少子化問題がぐっと解決できるのか、そういうのはまだ全然わかり得る話ではないのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"さまざまな情報が、５Ｇの通信のインフラが整理されることによって、今まで以上にそれが容易に可能になる時代になってくると。今、おっしゃったような少子化に対応するとか、さまざまな問題解決の要はインフラができるのですよということになっていくということだと思います。","id":"exchange-011"},{"speaker":"湯澤委員","kind":"意見","question":"それとあと、どういうふうにアピールしているかというのはとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"以前３年前まで品川区の職員が派遣で行ったりとかと、品川区の事例を他で波及するような、２カ月に１回ほどそうした連携の会議を内部で持っています。そうしたことが３月の下旬に品川区内中小向けに来年度の説明会を行うときも来ていただいて。","id":"exchange-012"},{"speaker":"湯澤委員","kind":"質問・要望","question":"前のときに、１１月がどのぐらい来ていたのか気にもなっていたのですけれども、もし数字が出れば、１１月のときのものを教えてもらえると。これからも進めていってもらいたいということで、これは要望にします。","respondent":"山崎商業・ものづくり課長","answer":"それから２回目が区民委員会でも以前ご報告をさせていただきました目黒のアマゾンでやったものです。こちらも企業７０社で１１７名の参加ということで、盛況なうちに過去２回とも終了させていただいている状況です。","id":"exchange-013"}]},{"id":"topic-05","title":"公益財団法人十四世六平太記念財団との連携に関する協定","agenda":"公益財団法人十四世六平太記念財団との連携に関する協定","exchanges":[{"speaker":"湯澤委員","kind":"質問","question":"質問なのですけれども、この協定に関しましては、品川区における伝統文化を守る協定だと思いますので、賛成をしております。ただ、もう少し詳しく、どうすると心豊かで生き生きと暮らせるまちづくりを推進という形になっていくのかというのをお答えいただけますか。","respondent":"古巻文化観光課長","answer":"さらに今までにあまり能楽というものが、無形の文化財ともいえる能楽が区民に親しみをもって接していただけるようになることで、心豊かになる。品川区自体のアピールといいましょうか、ブランディングに対して非常にメリットがあるのではないかと考えているところです。","id":"exchange-014"},{"speaker":"湯澤委員","kind":"意見","question":"もう１つ、小中学生は体験してどういった反応というか感想を持たれていたのかがわかれば、お聞かせほしいと求めました。","respondent":"古巻文化観光課長","answer":"能楽堂でやらない場合も多いと思いますけれども、それは能楽だけに限らず、日本の伝統芸能全般についてもそういうことが言えるかと思っています。ちょっと感想という意味では答弁になっていないのですけれども、そのように考えているところです。","id":"exchange-015"},{"speaker":"湯澤委員","kind":"質問","question":"所管が違うのに失礼しました。最後に能楽堂なのですけれども、喜多能楽堂以外に区内には能楽堂はどのぐらいあるのか尋ねました。","respondent":"古巻文化観光課長","answer":"ここだけです。都内でも珍しい施設です。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"そもそも論でお伺いしたいのですけれども、そんなに思ってなかったというのか、感覚的に全くないのです。品川区は能が伝統文化なのだと言っている方もいらっしゃるかもしれないのですが、なぜという思いがあるので、その辺を説明していただけませんか。","respondent":"古巻文化観光課長","answer":"たしか昭和３０年ぐらいだと聞いているのですけれども、委員からお話があったとおり、芸能だということもまた否定し得ない事実だと考えています。ですから、区としても支援をしていきかつ今後の能楽堂の存続でありますとかいったことの周知であったりとか、連携を深めていく。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、よく理解しましたので、その辺のことをしっかり押さえておかなければいけないではないですか。せっかく今できたわけですから、あえてこういう質問をさせていただきましたけれども、それはいいではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"こんの副委員長","kind":"質問","question":"協定によって、これまでよりも、よりこういう能楽を皆さんに見ていただく機会が増えていくと理解していいのでしょうか。品川区でこういうのが見れるのだというので、結構人気と私は理解しているのですが、その点はどうなのか尋ねました。","respondent":"古巻文化観光課長","answer":"当然協定を結ぶことによって関係性が深まり、かつ区からいろいろお願いをしたりする部分が増えて、やりやすくなる面は多々あると思います。ですから、増やしていかなければいけないと考えているところです。","id":"exchange-019"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"お外でされるので、屋外なので、そこをどうするか。これから詳しいことをされていくと思いますが、その点も考慮していただきながら、機会を増やしていただければと要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"下神明神社で雅楽に神社がすごく力を入れていまして、雅楽というのが、日本古来の音楽ですごく私は個人的にいいという思いがあるのです。そういうのも協定を結んだ際に、地域と関連づけてやれるような機会があるととてもうれしいと思うのですが、そういった観点はどうか尋ねました。","respondent":"古巻文化観光課長","answer":"東京２０２０大会に向けた文化プログラムの助成制度をつくっておりますが、こういった伝統芸能全般にはやはり区としてもしっかりと支援をしていきたいと考えておりますので、しっかりとバックアップをしていきたいと考えております。","id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"老朽化と維持管理とありましたけれども、その辺はどう捉えていくのか、もしある程度の方向が出ているのだったら説明を求めました。","respondent":"古巻文化観光課長","answer":"そのあたりはよく先方と協議をしながら、どういった形で支援ができるかを、今後協定を土台に考えていきたいと考えています。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひ、うまく連携をとっていただきたいということを要望にして終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]},{"id":"topic-06","title":"大森貝塚解説アプリ","agenda":"大森貝塚解説アプリ","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますが、１回、特別、予特か決特でお伺いしたのですけれども、大井町から大森駅に向かう電車に乗っておりました。大森貝塚かと思った石碑が立っていたのですけれども、あれは大田区に入っていたと思うのですが、あれは何なのか尋ねました。","respondent":"古巻文化観光課長","answer":"そちら大田区側に建てられたもので、あくまでも貝塚自体は遺跡庭園のところが遺跡の国の指定地になっています。あちらになりますけれども、関連する近隣のといったことで、大田区に建てたものと認識しております。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"今日はそのことをお伺いするのではなくて、あのとき聞いたのは私はどちらが本家か元祖かみたいに伺って、貝墟ですよね。そこだけはきちんとしていただきたいと思うし、課長が１回見ていただいて、大田区側の見解をきちんと聞いておいていただきたいと思っているのです。","respondent":"古巻文化観光課長","answer":"紛れもない事実だと認識しておりますので、しっかりその担当する管理職として、整理をしておく必要があると思います。三者で連携をいたしまして、しっかり戦略を立てて、品川区の中の大森貝塚をアピールしていきたいと考えております。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"私はこういう立場でいろいろ伺えるからわかるのですけれども、一般の方が見たときにわからないのです。大森貝塚と大田区に入っているわけですから、そこはしっかりと押さえておいてほしいと求めましたので、答弁いただけませんか。","respondent":"古巻文化観光課長","answer":"前は何度か通っていると認識しておりますが、大きな看板という意味でいうとちょっと目に入っていなかったのかもしれません。どういった由来でそこにそういうものがあるのかをしっかり調べておきたいと思います。","id":"exchange-026"},{"speaker":"松澤委員","kind":"質問","question":"それが途中で放置された状態で、あれは何も発掘もせずにそのまま建て替えられてしまうのかと。全然違う質問なのですけれども、素朴な疑問でありまして。","respondent":"古巻文化観光課長","answer":"歴史館の中で紹介している部分もありますけれども、発掘云々になりますと文化財係の所管になりますので、そのあたりはそちらでどのような形になっているのか把握を今しておりませんので、そのような形ですみません。","id":"exchange-027"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですけれども、その機能というか、再現ＣＧとかＡＲ機能とかいったものを楽しむことはできない。何か貸し出しとかがあったり、もしくは今後する予定があるとかいうのがあれば教えてほしいと求めました。","respondent":"古巻文化観光課長","answer":"どちらかというと、いただいたご意見については参考にはしますけれども、現時点では特にそういったことの予定はございません。あくまでも、スマホ対応ということでご検討いただければと思います。","id":"exchange-028"},{"speaker":"湯澤委員","kind":"質問","question":"ただ、大森貝塚の見学者は近年減っていったりしているから、よりこういうものをしようと思ったりしているのでしょうか。それとも別にそういうのは関係なく、今回さらに新しい技術を取り入れたりして、より多くの方に知っていただこうという試みなのか尋ねました。","respondent":"古巻文化観光課長","answer":"増減については、これは増えても減ってもいないと聞いています。付近に品川歴史館がありますし、大森貝塚をご覧になって、品川歴史館に行った後にまた近くに大森貝塚があるということを改めてご認識していただいて。","id":"exchange-029"}]},{"id":"topic-07","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"１件確認なのですけれども、これは主催がしながわ観光協会だから、今回そこの課でやられるわけですよね。商店街が絡んでいるので、こちらの商業・ものづくり課だと思っていたのですけれども、確認です。","respondent":"古巻文化観光課長","answer":"しながわ観光協会の企画ですので、所管としては文化観光課です。商店街も観光資源の一つとして位置づけておりますので、こういった形で商店街を観光資源として使わせていただいているです。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"期間が短く、やはりプールというか湿気というか、そういうところはやはり湿気等の関係で天井は壊れやすいというか落ちやすくなっているのでしょうか。見解があったら所管は文教委員会で、施設という意味ではあれなのですが、もしその辺についての役所の中での見解があったら教えていただけますか。","respondent":"中元スポーツ推進課長","answer":"平成２６年ですか、すぐにご連絡を申し上げて、事前に対応するように今後も適切な管理を努めてまいりたいと考えているところです。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"天井の落下によって負傷者が出たら大変ですから、日ごろから目を配ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2856#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":33814,"voices":130}},{"id":"r02-20200120-7","meetingId":"r02-cm01","date":"2020年1月20日","dateIso":"2020-01-20","committee":"厚生委員会","time":"午後 １時００分～午後 ４時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"令和元年陳情第６４号 障害児者総合支援施設の施設長を設置するよう区長に求める陳情","agenda":"令和元年陳情第６４号 障害児者総合支援施設の施設長を設置するよう区長に求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その委託会社や委託内容についても教えてほしいと求めました。そこら辺の消防計画との関係の仕組みについても教えてほしいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"それから委託している内容ですけれども、設備の管理をする会社が入っておりまして、そこで１人から２人、職員が配置されております。指定管理者につきましても、各指定管理者、運営事業者につきまして、防火管理責任者を配置しています。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今のお話ですと、委託の会社というのは、設備と受付と清掃と、それぞれに３つの事業所が入っているということで考えていいのでしょうか。大きな災害が起こったときの指揮というところでは、指揮系統がどのようになるのかということについてもお聞かせほしいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"訓練は、昨年１１月に全体での訓練を実施させていただきました。消防計画に基づき、災害の際に適切な対応ができるようにしていくため、日ごろの訓練を定期的に実施していくという考えです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"施設長がいなくても、区が統括の管理をしているわけですから、区が責任を持って指揮できるという体制になっているということで考えていいでしょうか。それと全体の消防計画というのは、区がつくったということでいいのかという点だけ確認をお願いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"例えば、災害対策のことも計画に位置づけております。災害、また、復旧までの計画や大雨、強風等の対策や備蓄品のこと等も計画に盛り込んでいるという状況です。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"備蓄物資などもそれにきちんと明示されているということで考えていいでしょうか。利用者や利用者の家族などへの防災マニュアルを含めた消防計画の公開という点について、実際はどうなっているのかについても説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"施設を利用するに当たりましては、重要事項説明書等で、事前に必要なことについては説明をさせていただいているところです。その中で、必要な情報等についてはご説明をさせていただいて、施設の利用につなげているところです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、安心しておいでいただいて大丈夫ですよという説明をされているということなのでしょうか。そういう点で言うと、備蓄が３日分では少ないのではないかなという思いがするのですけれども、その点についてもお願いします。","respondent":"築山障害者施策推進担当課長","answer":"今のところ、計画書そのものを公開するということはしていないのですけれども、必要なことについてはご説明の中でしていきたいと考えています。それから備蓄品につきましては、３日分というのが一般的なところかと認識しております。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"防災マニュアルを含めた消防計画についての公開なのですけれども、これは公開できない理由が何かあるのでしょうか。その点についてはいかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"計画等の公開につきましては、防犯上の理由で、例えば、不特定多数の方へ公開することによって、防犯上の点から注意が必要かと思っているところです。ただ、先ほども言いましたとおり、必要なことについては、説明等をしてご安心いただけるように整えていきたいと思っています。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"多分、陳情された方も、そのようにさまざま質問されて、なおかつ、こういう陳情を出されたのかなと思うのです。さまざまな事件もあったりしたので難しい部分があるのかもしれないですが、そこら辺の考え方だけ、最後にお願いします。","respondent":"築山障害者施策推進担当課長","answer":"利用する方につきましては、重要事項説明書等での説明を行っておりますので、その際に必要なことについてはご説明したいと考えています。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"障害児者総合支援施設全体の管理は区がされているということなのですけれども、今、常駐の職員は何人いらっしゃるのでしょうか。どういう立場でいらっしゃるのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"常駐では、係長級の職員が１名おります。立場としましては、複数の委託事業者が入っておりますので、建物の管理上の調整等を図るという役割で配置されております。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうしたこともきちんとチェックして、求められるレベルに持っていくというのも、全体を見る方がいらっしゃるとスムーズにいくのかなと感じるのです。その点は、今後、どのような感じでやっていかれるのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"区で改善できる部分については改善をしていくというところで考えてあります。総合支援施設として何らかの発信をしていく際も、区と指定管理者との協力体制のもと、情報発信等々をしていければと考えております。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひそのように進めていただきたいのですけれども、それを進めていく際、区との協力体制といったときに、一体、区の誰とやるのか。区としてわかりやすい、あるいは施設としての発信者であり、ちゃんと連携をしていく立場の人がわかるように存在させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"渡部委員","kind":"確認","question":"今の説明とやりとりで、問題ないことの確認がとれました。災害が起こったときにも問題ないということなので、今回、この内容自体は不採択にします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"西村委員","kind":"意見","question":"私も、本日結論を出すで、不採択でお願いいたします。私は説明のとおり理解いたしましたので、今回、不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"今の体制の中で、安全・安心が一定確認されたということが、１つ大きくあります。とりあえず、３年後をしっかり目指して、安全な体制を敷いていただきたいなということを要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３法人、まだ改善すべき点はさまざまあるとは思うのですが、そういう体制の中でとれるのではないかと思います。そういう点でも、安全に通える、また、いざというときにも頼りになるというところで、機能を果たしていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"あべ委員","kind":"質問・要望","question":"それは、区の考え方や各事業所の考え方次第だと思います。機能の面で足りないことがないようにしていただきたいという思いを込めて、施設長という名前にはこだわらないという意味では不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"}]},{"id":"topic-02","title":"令和元年陳情第６５号 特定相談・障害児相談支援事業所を増やすよう区長に求める陳情","agenda":"令和元年陳情第６５号 特定相談・障害児相談支援事業所を増やすよう区長に求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"確認","question":"今の合わせて１８人というのは、計画相談の方がこれだけいるということで考えていい人数なのかという確認をお願いしたいと思います。それから、平成３０年度の実計画相談件数がわかったら教えていただけないか尋ねました。","respondent":"松山障害者福祉課長","answer":"２点目の平成３０年度の実計画相談件数です。平成３０年度の直近の実績は、２,９２７件ということで、平成３０年度の実績については報告します。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"必要な延べ件数が年間幾らぐらいになるのかというところが出てくると、１か月の計画を立てなければならない件数も出てくるのかなと思うのです。そこら辺が何となくごちゃごちゃしていてわかりにくいという状況になっているので、少しご説明いただけないか尋ねました。","respondent":"松山障害者福祉課長","answer":"今後、次年度につきましては、新たな計画を立てる、特に、今、ニーズ調査も行っておりますので、そちらを踏まえて計画相談件数を見込む。国の標準担当件数を目安にして、必要数を見込んでいきたいと考えています。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、２,９２７件で見込み数が１,８５２件だったわけですから、１,１００件もないくらいがモニタリングと考えていいということ。もっと頻度を加えてやるとなると、延べ２,９２７件というのがもっとどんと上がるという見込みが出てくるのではないかという考え方なのか尋ねました。","respondent":"松山障害者福祉課長","answer":"たいむについては、さらに地域活動支援センターも兼務しているという実態があります。機能的に計画相談支援事業所と委託相談という機能が一緒になってしまっているので、計画相談支援事業所を増やす必要があると考えております。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"例えば、これだともう終わりぐらいと考えていますよとか、６割ぐらいまではいったのではないかとか、そういうおおよその目安というのですか。まだまだ、こんなに増やしていくという考えなのですよというあたりは、どう考えられているのかについても、少しお聞かせいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"今年度、６事業所増やしましたけれども、来年度につきましても、同数以上は増やしたいと考えています。ただ、何割というのは、やはりニーズ調査を行っておりますので、そのニーズ調査も踏まえて、分析しながら見込んでいきたいと考えております。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に計画相談事業所が極端に少なくて、実際にいろいろと話を伺ったところでは、１人１００件くらい計画を組んでいるというお話を伺ってきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"渡部委員","kind":"質問・要望","question":"陳情の理由の下から５行目あたりでしょうか。不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。想定される相談件数を分析していただきながら、引き続きお願いしたいと思いますので、本日は不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２,９２７件というのが、これは年間件数ですから、本当に驚くような数字になっているというのが実態だと思います。ぜひ増やして充実させていくということで、取り組みを進めていただきたいという要望も込めて、採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"あべ委員","kind":"意見","question":"利用者の方々、ご家族の方々は、不満やご苦労をすごく重ねていたことと思います。たとえ６事業所増えたとはいえ、数が増えていってもきちんとやっていただくということで、ここはむしろ応援したいなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]},{"id":"topic-03","title":"令和元年陳情第６７号 地域自立支援協議会の議事録における反対意見の掲載見送りに関する陳情","agenda":"令和元年陳情第６７号 地域自立支援協議会の議事録における反対意見の掲載見送りに関する陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だからこそ、正確な情報公開が求められていると思うのです。そのことについて伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"なお、陳情者の方へも、既に同様の説明をしています。特に明確な基準は設けてはございませんが、それぞれの委員の方々に確認をして、できるだけ趣旨が変わらないということで再確認しているです。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最終的には、発言者に確認ということになるわけなのですけれども、傍聴者の方々も実際に傍聴をしているわけですから。諮られたという記憶はないのですけれども、どこで検討されて、このような議事録に変えられたのかという点についてもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"第２回目の地域自立支援協議会において、地域自立支援協議会の場において、会長からも伝えております。地域自立支援協議会は、円滑な運営を図るために、このような議事録にさせていただいたという経過です。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"議事録のつくり方は名前を出さない、「どうですか」と言うよりは、「そのようにします」というご報告があったということなのですか。それとも、区からこのようにしたいのだけれどもどうかということで会長に言われたのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが公開という形になっているわけですから、私は、逆に区から公開という姿勢にしていただきたいなと思っているのです。〔「個人攻撃されたのを誰が守るんだ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このような陳情が出るくらい、区に都合のいいような形で要旨がつくられるのではないかと言われる部分にもなってくるのではないかと思うのです。情報公開という時代ですから、公開されていることを公にするというのは当然だし、私は全文議事録にしていただきたいということで要望もしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"今の質疑を伺いながら、公的な記録を残すということと、発言者を守るということと、両方を行っていくのはなかなか難しいことだなと感じました。どなたがというのは、どのような機関でつくっていらっしゃるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"障害者福祉課が事務局となっておりますので、職員が記録をとりまして、それから要旨については、伝わりやすい形で作成しているです。ご意見としてコンパクトにまとめた形で掲載しておりますので、会長のおっしゃられる趣旨は、要旨の中に載っているという認識です。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問","question":"少し細かいことですけれども、これは、例えばレコーダーに録音して、それを職員の方が課内でテープを起こして、それを読みながら要約をつくっているという手順なのか尋ねました。","respondent":"松山障害者福祉課長","answer":"これについては、おっしゃられたとおりです。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問・要望","question":"いつも気になっていて、これだけ忙しい障害者福祉課の中で、外注できるところは外注したほうがいいのではないでしょうか。いろいろと受けとめ方も多様になってくるかと思うので、そのつくり方は、ぜひご一考ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"あべ委員","kind":"質問","question":"それは、議事録をやんわりする以外に、区としてやっていることがあるのでしょうか。通常、会議の中での発言については、直接発言者ではなくて、まずお問い合わせは事務局という形で、何か工夫されていることがあれば。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、障害者福祉課の事務局といたしましては、個別にお問い合わせをいただかないように返答をしていくです。","id":"exchange-033"},{"speaker":"渡部委員","kind":"提案","question":"提案と言ったらおかしいけれども、僕は長期基本計画の策定委員をやっていて、同じ出し方をするのです。長くなりましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。不採択でお願いしたいのですが、情報の公開のあり方はこれからも大切に、丁寧に取り扱っていきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"若林委員","kind":"意見","question":"結論を出すで、不採択で結構です。区の説明の中で、しっかりとその趣旨も含めながら要旨として区民に公開しているということが十分理解できますので、そのような結論ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"しかも、私はできる限り実際に近い、「てにをは」を直す程度のところで出していくべきではないかと考えています。そのようなところで、情報公開もご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"あべ委員","kind":"確認","question":"先ほども申し上げましたけれども、委員の確認を得ているということで、手続的に瑕疵があるわけではありません。この議論について理解していただくという目的がありますので、そこのところは、今後もやり方は十分吟味してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"あくまでも行政が決めることではなくて、独立した委員会ですから、委員長が決めることであります。申しわけございませんでした。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"}]},{"id":"topic-04","title":"令和元年陳情第６８号 「計画」で需要増を見込み、担い手の確保をうたっている移動支援の従業者養成研修の実施についての陳情","agenda":"令和元年陳情第６８号 「計画」で需要増を見込み、担い手の確保をうたっている移動支援の従業者養成研修の実施についての陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは、区が品川総合福祉センターに委託する事業と考えていいのでしょうか。区が委託するということであれば、その委託費用は幾らぐらいなのかというところも教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"実際に実施するのは法人の独自事業として実施したい旨、ご連絡がありましたので、特に委託をしているということではございません。法人として、自分たちで実施したいという意思が確認できましたので、そのように行っていただく予定です。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"利用料もなくなって受けやすいということで、すごく歓迎すべきことだと思うのですけれども、どうしてそのようになったのかということ。その点についても説明を求めました。","respondent":"松山障害者福祉課長","answer":"第１回目は法人独自で実施してみて、今後も続けたいという旨の意向はいただいております。それ以降、実際に移動支援の従事者として実施できる方をどうやって確保したらいいかということも一緒に協議しながら進めていきたいと考えています。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"区の方針として、区から助成金を出してさらに進めていくというようなことはないのでしょうかという確認をお願いしたいと思います。どういう形で周知の工夫ができるのかというあたりも、方針などがありましたら教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"今後、実施するに当たって、研修を実施する２か月ぐらい前には、必ず東京都に申請を出して承認を得る必要があります。確かに委員のおっしゃられたとおり、さまざまな手段を使いながら、できるだけ多くの参加者を確保できるように頑張っていきたいと思います。","id":"exchange-042"},{"speaker":"あべ委員","kind":"質問","question":"品川総合福祉センターが東京都から指定を受けたのはいつだったのか尋ねました。","respondent":"松山障害者福祉課長","answer":"品川総合福祉センターが指定を受けたのは、１２月２７日です。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問","question":"それこそ１,５００円になって、みらいだとどうしても経費がかかるということで、みらいはこの研修についてどうしていくのか。区としては、みらいについてどうされるおつもりか尋ねました。","respondent":"松山障害者福祉課長","answer":"実際に、これまで行っていただいたＮＰＯ法人みらいのほうにも情報提供をして、一緒の場で協議を進めております。区内全体で多くの事業所の力を借りながら、今後もみらいや品川総合福祉センターと協議を進めながら、どうしていくかは詰めていきたいと考えています。","id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今回、品川総合福祉センターということで、先ほど、鈴木ひろ子委員から、今後、区として助成金を出して進めていくという考えはないかとありました。少し区の支援があったらなという事業所が出てきた場合は、区に相談して、そのようなことは可能なのかを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"東京都の指定をとるというのが、法人にしても、定款変更を求められたり、書類の整理、また、こちらは通学課程というものになります。ただ、実際にやっていきたいという事業者については、ご相談を受け付けておりますので、区としても努力してまいりたいと考えています。","id":"exchange-045"},{"speaker":"西村委員","kind":"意見","question":"都の指定を受けまして、品川総合福祉センターが研修を実施できるようになって、本当によかったと思っています。Ｆａｃｅｂｏｏｋ、Ｔｗｉｔｔｅｒなども活性化されていると思いますので、ぜひ引き続きご検討をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"若林委員","kind":"確認","question":"品川区も積極的にかかわりながら、都の指定の事業所も誕生した。前に進んでいるということが確認されたので、その結論で結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回延長されて、３月にされるということになって、本当によかったと思います。この思いが、区としても実施されるということで、さらに今後に向けても充実を求めていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"あべ委員","kind":"意見","question":"本年度も実施するのであれば、理屈の面から言っても、これは採択しないと、今年実施する事業に反対することになってしまうのかなと思われます。今年３月、今年度中に実施されるということに異論はありませんので、採択させてくださいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"}]},{"id":"topic-05","title":"令和元年陳情第６９号 障害児相談支援事業所について民間事業所経由で配布された課長名義の文書についての陳情","agenda":"令和元年陳情第６９号 障害児相談支援事業所について民間事業所経由で配布された課長名義の文書についての陳情","exchanges":[{"speaker":"渡部委員","kind":"意見","question":"端的に「はい」か「いいえ」でいいのですけれども、要は、アプリ児童デイサービスが相談事業を始めるから、今まで区で受けていたものをそちらに変えられますよというのを、アプリ児童デイサービスを利用している人に送っただけなのですよねとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"委員のご発言のとおりです。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、もう少しわかりやすい形での表記が必要ではなかったかなと思いますけれども、その点はどうでしょうか。そのような形の出し方になっているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"表記でご不明な点につきましては、陳情者にもきちんと趣旨が伝わるよう、選択できますということはご説明申し上げております。未就学児から徐々に開始したい、あるいは学齢期から開始したい、ご自分たちでいらっしゃる方々の中からご希望があればということです。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは、障害者福祉課から相談支援事業所アプリ北品川に変更されるかどうかについて確認させてくださいという中身になっているので。そこを改めていただきたいということなのではないかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"あべ委員","kind":"意見","question":"陳情というのが妥当かどうかは別として、間違っていませんと言うよりは、今度はもう少し変えてみようという感じで活かしていただければなと思います。これは少し誤解が出るかもしれないと思うようなことが時々ありますので、何かあれば…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"渡部委員","kind":"確認","question":"一番最初に確認したとおりでございまして、事業所がそういう相談事業を始めるから移りますか、移りませんか。そういうことでしっかりやっているわけだから、いいことですし、これからまた相談が増えるということですので、この内容自体は不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。先ほどの課長のご説明で一定の理解を示しましたので、不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"区民の方により丁寧にきめ細かくご案内をするということで、そういう取り組みを確認させていただきました。そういうお問い合わせには、引き続きしっかり丁寧に対応していただきたいということで、不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、ぜひ今後とも注意をしながらやっていただきたい。誤解を与えないというところでは、いろいろ工夫もしていただきながら取り組んでいただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"あべ委員","kind":"意見","question":"この文章自体は、不正確とまでは言えないかなと思います。わかりやすさは上がっていくと思いますので、こうしたことを一つ一つ活かして、よりわかりやすい文書をつくるようにご対応ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"}]},{"id":"topic-06","title":"品川区肺がん検診の契約違反と区の対応","agenda":"品川区肺がん検診の契約違反と区の対応","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１枚しか撮影していなかったということがわかるような仕組みはないのでしょうかということが１つです。このようなことが二度と起こらないようなチェック体制については、どのような体制がとられるのかについてもお聞かせほしいと求めました。","respondent":"高山健康課長","answer":"これを毎年実施することによって、医療機関の質、検診の質を一定に保っていきたいといったことを考えております。これが昨年１１月に開かれておりますので、今後も必ず年に１回、この精度管理を徹底してまいりたいと考えております。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この第三者委員会の目的や、どのようなメンバーでどんなことをしていくのかというところについてもお聞かせほしいと求めました。その点についてもお聞かせいただけたらと思います。","respondent":"高山健康課長","answer":"それから、２点目の十分な専門性を有する医師の考え方です。そういった経験の長さ、臨床の分野において妥当性があれば、私どもとしては検査医として妥当だとみなしています。","id":"exchange-060"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"このＴｈｉｎｋ Ｐａｒｋ消化器クリニックに対しては、どのような対応をされたのでしょうか。何か処分など、区がどこまでなのかわからないですけれども、クリニックに対しての対応を伺いたいと思います。","respondent":"高山健康課長","answer":"この当該クリニックへの対応という点です。そのほかに、医師会内部として何らかの処分を検討されているといったお話を伺っております。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3554#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":50813,"voices":164}},{"id":"r02-20200120-8","meetingId":"r02-cm01","date":"2020年1月20日","dateIso":"2020-01-20","committee":"建設委員会","time":"午後 １時００分～午後 ４時１３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"コミュニティバス導入に向けた検討状況","agenda":"コミュニティバス導入に向けた検討状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"間違いないのでしょうかということと、すべきではないかと思うのですけれども、まず１点目の質問です。３つ書かれていますけれども、コミュニティバスの運行や導入に際しての国や東京都からの補助金の有無は、現状どうなっているのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今ご提案いただいたように、もう少しわかりやすい表現は、まだ骨子案の段階ですので、書き方について検討させていただきたいと思います。補助金のお話ですが、基本的には都の補助がございまして、車両購入費や運行経費の補助金は、都の補助金としています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"ですから、積極的にそういうものは活用していただいて、進めていくことが必要だと思います。品川区コミュニティバス導入計画（骨子案）の１ページの、３回目の検討会には、示されるということなのかを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今、運輸局や、警察などと協議を開始しているところです。予定は書いていくのですが、そのとおりにいくかというところもあって、今現在は黒丸にさせていただいているところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ふだんからコミュニティバスの運行要望をかなり伺う地域が上大崎なのですけれども、今回の指標結果では、３０点台ということで。やはり意見交換会を各地で開いて、計画に反映させるべきだと私は思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"説明会なのですが、第１回検討会の終了後もそうですが、第２回検討会の内容をご説明しています。説明会は考えてございませんが、しっかり地域に説明をして、理解しています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"候補ルート（案）も、高評価の地域が中心になっていきますけれども、さまざまな候補ルート（案）も出てくるでしょう。いろいろ要望なども上がってくると思うのですけれども、そういった要望を、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"１２月１３日の検討会を傍聴できませんでしたので、どういう話の流れのときに、その辺のことを伺いたいと思います。その辺について、今、時点のお考えなどを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"第１回検討会後に１３地域を回り、第２回検討会後の説明に回っているところですが、そうしたお声が多かったです。検討を進める中で、生かせるところは、生かしていきたいです。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"地域のご意見を伺うのは、基本的には町会長の皆さんという感じなのでしょうか。その辺は、もう少し地域の方に広げて意見を聞くような場を設定する、おつもりはないのかを伺います。","respondent":"鈴木都市計画課長","answer":"当然ながら、本格導入後、本格導入した状況がどうかということは、地域交通検討会で、いろいろご議論いただきながら進める。こういう形で進めさせていただいて、この基本方針も、そういう形で考えているところです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺、柔軟に考えていただいて、より多くの人に利便性の高いコミュニティバスにしていってほしいと求めました。これは、意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"松本委員","kind":"提案","question":"別紙２の８ページに事業者提案に対する条件の項目例がお示しいただいています。こういう動きもお願いできればと思うのですが、現状、そのあたりの検討状況はどうか尋ねました。","respondent":"鈴木都市計画課長","answer":"多言語への対応ですとか、料金を徴収するシステムですとか、いろいろ多岐にわたると思います。当然ながら、誰にでも乗っていただけるようにということですから、そうした点も大事にしながら、提案項目はしっかり検討していきたいと考えています。","id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問","question":"運行事業者の選定方法として、３つの方式が示されています。全くノープランで、この３つの中から委員のご意見を聞いて、決めるのかを説明を求めました。","respondent":"鈴木都市計画課長","answer":"第３回検討会でお示しするルートについては、今のところ、複数案を考えてあります。第３回検討会では、区ではこう考えますがというところはお示しして、ご議論をいただくと考えています。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問","question":"２点目の地域をまたがるという話です。すべては無理があるわけですから、一応そこはお願いしたいと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"先ほどの視点の中に入っておりませんでしたが、当然ながらそうした視点も入れながら、検討していきたいと考えています。","id":"exchange-010"}]},{"id":"topic-02","title":"（仮称）品川区水辺利活用ビジョン（素案）","agenda":"（仮称）品川区水辺利活用ビジョン（素案）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"目黒川で、水辺活用というならば、この改善は必要な点なのではないかと思うのですけれども、その記述がない理由は、なぜなのかを伺いたいと思います。区として、現状の目黒川の水質改善に向けた大きな方向性について、現在どのような考えをお持ちなのかを伺いたいと思います。","respondent":"鈴木都市計画課長、松本河川下水道課長","answer":"ビジョンに対する区民の方のご意見をいただいて、取りまとめに反映をしていきたいと考えていますので、全体で説明会をする予定はございません。細かいところは、河川下水道課長よりご説明いたします。 品川区といたしましても、年間１度ですが、河川のしゅんせつを行っているところです。引き続き、上流区の世田谷区、目黒区とも連携して、水質改善に向けて、いろいろな取り組みをしていきたいと考えています。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"水に親しむということであれば、もう少し改善が必要なのではないかという率直な区民感情があると思いますので、伺いました。区として、どこまで、こうした水辺の利活用に関して、財政投入をしていこうという考えなのかについて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"方針ですとか、考え方を共有していく上で、策定させていただいてあります。積極的に水辺をしっかり活用していく取り組みを進めていきたいというところは言えると思うのですが、協力しながら、進めていきたいというものです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"水質改善というと、東京都や品川区に求めてしまうのですが、実は、水質改善には、地域に暮らす人たちの生活が直結しているのです。どういうという、各自、取り組みをしようという発信のお考えがあれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"そうしたところを、いろいろな場面で、地域の方に見ていただいて、取り組み、あるいは意識を持っていただく。そうしたところを、今後しっかり考えていきたいというところの第一歩として、書かせていただいているところです。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"私は、決算特別委員会や予算特別委員会の質問の中でも、こういう合流改善への具体的な取り組みを求めております。これから目指すということですから、優先順位というか、政策的な順位をもう少し上げていっていただけたらと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"意見","question":"もう１点は、天王洲エリアは構わないのだけれども、もう少し品川浦に触れてほしい。品川浦と天王洲は少し違うから、同じ一括りになっているのだけれども、水辺を語るときに、それも１つお願いしたいとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"モノレールの柱脚についても、以前から、いろいろなご意見をいただいてあります。パブリックコメントとあわせて、反映できるところは、しっかり水面の活用も含めて検討し、充実して、最後に取りまとめていきたいと考えています。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"高度経済成長のときに形づけられた川の形状でしょうか。観光と相なじまない形状になっているのではないかと思うのですけれども、そこのところは、どういうふうに捉えていらっしゃいますか。","respondent":"鈴木都市計画課長","answer":"先ほどの目黒川の河川の護岸の寂しさについても、どう魅力あるものにしていけるかというところは、しっかり考えていきたい。あるいは、東京都にも伝えていきたいです。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"目黒川は、両方とも囲まれていて、とても生きている川とは、私は思わない。１つの川に吹き込むということは、この問題に取り組んでいただきたいと思うのですけれども、ご感想を説明を求めました。","respondent":"鈴木都市計画課長","answer":"そうした中で、どこまで、今の河川の形状を変えてというところを書けるか、どうかということは検討していきます。ただ、ご提案いただいたように、夢が現実的になっていくように、大きい視点でも書かせていただきたいです。","id":"exchange-017"}]},{"id":"topic-03","title":"住宅補修緊急支援事業の実施","agenda":"住宅補修緊急支援事業の実施","exchanges":[{"speaker":"たけうち委員","kind":"確認","question":"確認なのですけれども、東京都の１５万円も、この２分の１という条件がついているのかどうかということです。その辺をお伺いします。","respondent":"森住宅課長","answer":"都の補助金については、都が１５万円を出して、品川区が半分の１５万円を出すという制度設計をしているところです。向こうからの何かしらのアクションがなければ、ご提案のあったようなことも考えながら、しっかりと周知をしていきたいと思っています。","id":"exchange-018"},{"speaker":"たけうち委員","kind":"質問","question":"１０万円かかった場合、２分の１なので、５万円になると思います。都でも、この２分の１という条件はついているのか尋ねました。","respondent":"森住宅課長","answer":"東京都のほうも、２分の１までと、あるいは、１５万円以内のどちらか低いほうという形になってあります。要するに、今、言われた１０万円ということになれば、５万円が補助金になりまして、２万５,０００円ずつ、都と区が出すという形になります。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"そういった方は、資料にある一部損壊認定の８３件には含まれていないのでしょうか。伺います。","respondent":"森住宅課長","answer":"８３件といいますのは、１２月末現在で、り災証明の申請を受けて、発行を受けられた方となります。り災証明の発行が必要になってまいりますので、その後、この制度の手続に入っていただくという形になります。","id":"exchange-020"}]},{"id":"topic-04","title":"武蔵小山駅周辺地域のまちづくり","agenda":"武蔵小山駅周辺地域のまちづくり","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"その観点から、お伺いしたいことは、３番目の小山三丁目第１地区のところの面積要件です。３分の２以上をとらないと、そこの面積要件という点では、どのようになっているのかということをお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"マンションの権利者一人ひとりに対しての区の考え方なのですけれども、基本的に１００％を目指して、話しています。丁寧な説明をやりながら、そういう考えのもと、進めております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"７７.０７％と８３.４９％ということですが、相談などでも、いかがなものかという立場からの声なども伺います。説明会はなかったのですかということで、まだ、そういう段階ではないということなのか尋ねました。","respondent":"小林環境課長","answer":"恐らく、委員がお話しになっているような説明会というところにつきましては、環境影響評価書（案）の段階か次の段階だと考えています。その段階では、改めて説明会の開催が行われると考えているところです。","id":"exchange-022"}]},{"id":"topic-05","title":"環境表彰式・環境講演会","agenda":"環境表彰式・環境講演会","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"毎年、大体、何人ぐらい、当日は参加があるものなのかということと、参加すればいいのですけれども、環境保全活動顕彰の２部門、６件について、どのような活動だったのかということを知りたいので、主なものでいいですけれども、ご紹介してほしいと求めました。","respondent":"小林環境課長","answer":"継続的に行っているというところとあわせて、さまざまな取り組みをしているというところが、表彰された大きな要因と言われているところです。ご提案をされているというところが、今回、評価の対象だです。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"今のご質問の続きのような感じになるのですけれども、こういった賞をそれぞれ選ぶ基準は、どのようなところで審査されているのか。新しい環境課題が生まれてきたときに、選定の際、そういう視点を入れられているのか、その辺について伺いたいと思います。","respondent":"小林環境課長","answer":"この環境保全活動顕彰ですが、これは実施要項に基づきまして、取り組んでいるところです。非常に広い範囲での環境課題に対する取り組みについても、もちろん、今回の顕彰の対象になると認識しています。","id":"exchange-024"}]},{"id":"topic-06","title":"武蔵小山駅放置禁止区域の変更","agenda":"武蔵小山駅放置禁止区域の変更","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"再開発に伴う７５１台（店舗用２５１台を含む）とは、どういう意味なのか。店舗用は、別にきちんとあって、残りは何なのかを説明を求めました。","respondent":"古郡交通安全担当課長","answer":"これについては、７５１台のうち、店舗用として２５１台、そのほかに５００台が、公共的に用意されたものでございまして、定期利用と当日利用となっております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、ある意味、今までは、暗黙の了解的に、ここが商店街の駐輪場みたいな感じの位置づけになっているのではないかという印象がありました。お買い物に来ている方々の自転車は、どこにとめればいいのかについて、区はどういう考えをお持ちなのかをお伺いします。","respondent":"稲田都市開発課長、古郡交通安全担当課長","answer":"その７５１台は、朝の５時から２５時という表現ですけれども、その間は使うことができる。一般の一時利用は、９０分までは無料で、以降、２時間で１００円ずつかかるという状況です。 駅前に利用できる駐輪場が用意されていますので、そこにとめて、買い物に行っていただくということです。１時間半、無料になっておりますので、こちらを、しっかりと利用していただいて…","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"ですから、４月１日ということで、まだ先ではありますが、合意形成が大丈夫かという心配があるのですけれども、拙速なのではという印象もあります。結論を出すべきだと思いますが、これからの進め方などについて、お考えはいかがか尋ねました。","respondent":"古郡交通安全担当課長","answer":"ですので、地元の了解と商店街の了解を得ていると認識をしています。それについては、商店街等も含めて、広報で啓発していくという形になっております。","id":"exchange-027"}]},{"id":"topic-07","title":"品川区無電柱化推進計画（素案）","agenda":"品川区無電柱化推進計画（素案）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"無電柱化の現状ですけれども、無電柱化の課題はあるのですが、無電柱化そのものは、何かデメリットみたいなものはあるのでしょうか。そちらについてお伺いしたいと思います。","respondent":"多並道路課長","answer":"説明会の開催についてですけれども、広く区民の方にお示しして、ご意見をお伺いしたいと考えています。その内容を説明するのですけれども、内容を説明してみると、もう少し後のほうがいいのではないか。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"こちらも、地中化の要望なども伺ったことがあるのですけれども、こちらは、技術的に無電柱化は可能でしょうか。可能であれば、候補に入れていくことも必要なのではないかと思いますけれども、いかがか尋ねました。","respondent":"多並道路課長","answer":"この６路線を中心としながら、改めて計画を見直す際には、考えていきたい。そのように考えているところです。","id":"exchange-029"},{"speaker":"たけうち委員","kind":"意見","question":"4)番の旗の台駅から昭和大学病院のところですけれども、商店街にあたると思います。もちろん4)も区のほうの計画になるので、1)から3)と4)は少し違うのかなという部分もあるのですが、その辺はどのように考えていますかとの意見を述べました。","respondent":"多並道路課長","answer":"約１７０メーターと、総合的にいろいろ見ながら、検討をしなければいけないと思っています。いろいろな部署と連携を図りながら、地元も含めて、検討していきたいと思っているところです。","id":"exchange-030"},{"speaker":"たけうち委員","kind":"質問","question":"一緒に聞けば、よかったのですけど、図を見ると、踏切を越えてはいないけれども、やはり、考えとしては、踏切を越えてということは考えなかったのか。もし、その辺の理由がわかれば説明を求めました。","respondent":"多並道路課長","answer":"もともと、駅の改札から病院までの間のバリアフリー化の計画がベースとなっていますので、実際に災害があった際の駅と緊急拠点病院との間ということで、踏切よりも中原街道側、要するに、踏切は入らない計画としています。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう１点は、例えば北品川の旧東海道は、やはり、店舗があるので、夜間工事をした。こういう期間で済みますという２つの案を出すなど、そういうことも含めて、地域と話すのかというところだけお聞かせ願いたいと思います。","respondent":"多並道路課長","answer":"商店街の担当部署とよく連携を図りながら、もちろん、なるべく地元にご迷惑をおかけしないスキームは探っていきたいと考えています。新しい方法が出てきていますので、そういうものも一緒に考えながら、よりよい形は考えていきたいと考えています。","id":"exchange-032"}]},{"id":"topic-08","title":"オリンピック・パラリンピック施設周辺道路 遮熱性舗装工事","agenda":"オリンピック・パラリンピック施設周辺道路 遮熱性舗装工事","exchanges":[{"speaker":"松本委員","kind":"意見","question":"遮熱性舗装ですけれども、たしか、路面の温度は下げるけれども、周辺の気温は上がるという報道があったかと思います。こういう報道が出たのが、去年の秋ごろで、その後、何か対策というか、検証がなされたのかというところをお願いいたしますとの意見を述べました。","respondent":"多並道路課長","answer":"品川区でも、平成１７年に同じような調査を実はやっておりまして、高さの部分でも、確認をして、そういう温度上昇がないということは把握しています。そういう実態は把握して、低減効果は大きくあるということで、確認しています。","id":"exchange-033"}]},{"id":"topic-09","title":"防犯カメラ設置工事","agenda":"防犯カメラ設置工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"そもそも、全ての公園への防犯カメラ設置へ踏み切った理由は何なのかを伺います。それだけの要望が、区民から上がっていたということなのかを伺いたいと思います。","respondent":"溝口公園課長","answer":"防犯カメラを設置することで、地域がより安心・安全になるといったご要望を、これまでもずっと受けてきたところです。人的対応だけでは、全ての公園に、防犯カメラを設置していくとしたものです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"犯罪抑止効果という期待の一方で、監視社会なのではないか、個人情報の流出の心配ですとか、そういうものがあるわけですけれども、この映像の情報がどのように管理されて、その運用や提供のルールなどは、誰が、どう定めて、実際のルールの内容はどうなっているのかという概要を伺いたいと思います。","respondent":"溝口公園課長","answer":"映像の利用につきましては、基本的には公園の管理といったものに使うため防犯カメラを設置しております。そのほかの目的外の利用としては、犯罪捜査といったことで要請があった場合については、提供できるという形にはなっているものです。","id":"exchange-035"},{"speaker":"安藤委員","kind":"意見","question":"くれぐれも目的を逸脱した情報の提供などが行われることがないように、ないと思いますけれども、お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"それが認識されないと、防犯という意味では、少し弱いのではないかと思います。ぜひ、防犯カメラが作動しているということが書かれているほうがいいのではないかと思うのですが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"ただ、公園の中は、禁止事項が多いと言われているところです。引き続き、管理状況等を見ながら、考えていきたいと考えているところです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"これを防犯カメラということで広げていくということであれば、ぜひ、本当に抑止のほうに律するような方向で検討してほしいと求めました。これは、意見にとどめます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"}]},{"id":"topic-10","title":"廃棄すべき備蓄物資（紙おむつ等）の転売事案","agenda":"廃棄すべき備蓄物資（紙おむつ等）の転売事案","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"報道の後、区民からのお問い合わせもありましたので、防災課長に話を伺いました。どれくらいの間、こういうことが行われていたのかを把握していらしたら、教えていただきたい。","respondent":"中島防災課長","answer":"どのぐらいの件数でありますとか、いつからというところについては、私のほうでは把握しておりません。基本的には物品供給契約の中で、備蓄物資の購入等を行ってきたです。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"総括質疑を行ったものですから、どうなのかということで、契約書を求めました。荏原薬業協同組合の問題もありますけれども、区としての責任は免れないのではないかと思いますが、その辺についていかがか尋ねました。","respondent":"中島防災課長","answer":"基本的には廃棄をしないことを第１としていきますが、書面等で確認をして、しっかりと契約が履行されたことを確認していくようなことを努めていきたいと考えています。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"報告はなかったと思わざるを得ないのですが、その辺について、改めてご報告を伺いたいと思います。現実的に報告がどうだったのかということと、その辺の見直しについて見解を伺いたいと思います。","respondent":"中島防災課長","answer":"書類をしっかり提出を求めるということで、そういう形で、しっかりとチェックができるようになると思います。そこについては、徹底してまいりたいと考えています。","id":"exchange-041"}]},{"id":"topic-11","title":"令和元年度品川区地域防災計画の修正","agenda":"令和元年度品川区地域防災計画の修正","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回、この点では、どのようなルールが定められるのかを伺いたいということが、１点目です。今回、修正項目の(1)のイのところに書いていますので、そこら辺は、今回の修正では、どうなったのかを伺います。","respondent":"中島防災課長","answer":"あくまで、区の職員が開設、運営するというところの記載で、運用につきましては、適宜、区のほうで、また対応してまいりたいと考えております。本会議等の答弁に沿った形でのものになるといいますか、今のところ、特に地域防災計画の中で、そこについて記載する予定はございませ…","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"昨年７月の豪雨災害を受けた避難所の生活環境等についてという通知を出していまして、その辺、かなり具体的に改善を求めています。具体的に、どういった場面で、どのように反映されていくのかということも伺います。","respondent":"中島防災課長、曽田災害対策担当部長","answer":"避難所の環境の改善につきましては、これまでも取り組んでまいりましたが、これからも取り組んでまいりたいと思います。記述してまいりたいとは思っておりますが、今後、検討課題という形になるかと考えています。 具体的にどうするのかということにつきましては、来年度予算など、そういうところで、今、検討しています。こういったことを検討をして、今回の地域防災計画には反映できませんけれども…","id":"exchange-043"}]},{"id":"topic-12","title":"品川区国民保護計画の変更","agenda":"品川区国民保護計画の変更","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"安保法制の問題は、今回の変更にどういうふうにかかわってきているのか。それとも、関連性が余りないのかについて伺いたいと思います。","respondent":"大森災害対策担当課長","answer":"区の国民保護計画の作成もしくは変更の流れですが、国民保護法に基づきまして、まず、国が基本指針を作成しております。この国の基本指針は、おおむね２年に１回ぐらい、細かな修正がかけられておりまして、その状況を見まして、東京都の計画が変更されております。","id":"exchange-044"}]},{"id":"topic-13","title":"行政視察報告書","agenda":"行政視察報告書","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"確認後にすいません。字句の修正は、個別に申し上げればよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4282#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":60073,"voices":159}},{"id":"r02-20200120-9","meetingId":"r02-cm01","date":"2020年1月20日","dateIso":"2020-01-20","committee":"文教委員会","time":"午後 １時００分～午後 ４時５３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件整理しています。","topics":[{"id":"topic-01","title":"令和２年度新入学の学校選択希望申請理由調査結果","agenda":"令和２年度新入学の学校選択希望申請理由調査結果","exchanges":[{"speaker":"横山委員","kind":"質問","question":"２点目は、令和２年度の新入学の学校選択、お願いいたします。昨年、この１年で学校運営の改善というところにはどのようにつながっていて、その辺りの状況を説明を求めました。","respondent":"篠田学務課長","answer":"任意ですので、希望選択が結びつくものではないと説明をさせていただいているので、出していただける方からはいただいているという状態です。ですので、なかなか具体的な話にならないものですから、その結果をどう受けとめていくかというのは…","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"実際、その学校でどのように改善をしたというものがありましたら、教えてほしいと求めました。どういった対応になっていくのか、教室の関係ですとか、そういった点を伺いたいと思います。","respondent":"篠田学務課長","answer":"１クラス３５名が大前提ではあるのですけれども、例えば、そういった４０名のクラスを設定していただくということも過去にはございました。原則は１クラス４０名、この場合は３クラスですと１２０名までとれるということになりますので、対応ができるものと考えているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"確認","question":"どう活かされているかというのは教育委員会ではつかまれていないということになるのか、改めて確認になってしまいますが、伺いたいと思います。格差というか、生まれてしまうといったことがいいのかという危惧があるわけなのですけれども、いかがか尋ねました。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"そちらを重点的にそれぞれの学校が振り返って、自分の学校に足りないところがあれば、それに対応していくです。教育委員会としまして、フォローはしていないというものですけれども… 特に学校によって格差はないと考えておりますが、それから今後在校していただく就学予定の、努力しているところです。そういったことをどれだけ学校だよりで、あるいは授業公開でアピールできるかが各校の腕の見せどころだと考えて…","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"抽選校が増えることで、入れるかどうかというのがそこでもわからなくて、より抽選校が増えてしまっているのかなという危惧もあります。やはり学校選択制というのはやめていくという方向で検討もしていくことが必要なのではないかということを一言申し上げて、終わりにしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"塚本委員","kind":"確認","question":"どこかで教室を新たに用意しなければいけないという見通しみたいなものが、ありそうなのかどうかというのをお伺いしたいと思います。そういうものとして見ればいいのかというのを確認の上で、浜川中学校だけは「戻り３０名考慮」となっていて、もう一度ご説明いただけますか尋ねました。","respondent":"篠田学務課長","answer":"春休み中にいろいろな対応をとって、これからもそういう事態があれば、そういう対応をとっていくというものです。それぞれの抽選対象の１位のところに、その辺りは来年度以降、資料のつくりも考えたいと思っているところです。","id":"exchange-005"},{"speaker":"塚本委員","kind":"質問・要望","question":"３クラスでいえば１０５人まで、抽選枠の中での１クラス３５人という考え方における柔軟な対応というのは、どのようにされるのか。３クラスであれば１０５人までは、そうではないのかというところですけれども、その部分をお話しほしいと求めました。","respondent":"篠田学務課長","answer":"今後あと２か月ぐらいの状況を見ると、何とか対応できるかなということがあれば、兄弟枠の方は入れましょうと。希望された方をお受けするような対応はこれまでもとってありますので、今年度に関してもそういったことで進めてまいりたいと考えているところです。","id":"exchange-006"},{"speaker":"塚本委員","kind":"意見","question":"１クラス３５人と考えたら、転入とかがなければ、かなり余裕がある場合があるわけです。３５人まで受け入れられるのであれば、待機している人は１０５人になるまで受け入れましょうという考え方というのは、そこをとの意見を述べました。","respondent":"篠田学務課長","answer":"残り２月・３月の期間というのが、この時点で１０５人まで目いっぱい入れるというのは、なかなか難しいかなと思います。学校の設備等に制約がある中では、待機の期間のうちに１０５人まで全部埋めてしまうというのは困難であると考えているところです。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"一方で、実は４月の段階で、３５人でいけばもうちょっととれたなという事態も発生し得るわけです。対応をできる限りしてほしいと求めましたので、そこは要望として、終わりにしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"もちろん、それはオープンにしたほうがいいとか、そういう議論ではなく、教育委員会のそういう認識があるのか。もしやっていないとすると、なぜやらないのかということをお伺いします。","respondent":"篠田学務課長","answer":"それぞれ考え方がありますので、取り組みをされているかどうか、この調査結果を踏まえた対応をとっているものと考えているところです。","id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問","question":"その点についてはいかがでしょうか。学校ごとにそういうのをやったほうがいいと思うのですけれども、その点はどうか尋ねました。","respondent":"大関教育総合支援センター長","answer":"働いている教員からも、アンケートの形でとったものとクロスさせながら、各校で分析をするという形をとっているのがこれまでの状況です。教育総合支援センターともに、有効な内容については、また検討を進めたいと思います。","id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"確認","question":"この質問はこれで最後にしますけれども、具体的な中身が先生方にも認識されて、やりがいにつながるような形になればいいなと思います。許す限りのところでやっていく状況をお願いしたいというのは同じ意見なのですが、改めてもう一度、その辺りについてもう一回確認したいです。","respondent":"篠田学務課長","answer":"せっかくさまざま検討して学校を選んでいただいていますので、できるだけその希望を叶えたいという思いでいるのは間違いないところです。これは実際に受入れる校長の考え方等もありますので…","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問","question":"小学校のほうでは四百数名のうち三百幾つ、４分の３の方が待機で、８０人がご兄弟と。小学校は４分の３が待機しているわけですから、希望が叶わないという方が多いという点については、どうお考えか尋ねました。","respondent":"篠田学務課長","answer":"ここの筋を変えてしまいますと、根本的なところで考え方が変わってしまうということがあるので、なかなかその部分は難しいのかなと。どれだけ学校選択したお子さんも対応できるかということで、正直、その制度のよさを活かせるような形で対応できたらいいなと考えているところで…","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"提案","question":"なかなか提案できないので、今のお話にあったような形で課題もあるわけですから、提案していければいいと思います。これを何らかの形で改善できるような方法を、今後、考えていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問","question":"１点だけお伺いしたいのですが。そういった方は、例えば転居とか、そういった理由が多いのか尋ねました。","respondent":"篠田学務課長","answer":"兄弟の枠に該当はするのですけれども、今のところ兄弟枠に入っても、この時点で入れない方がいらっしゃるというものです。当然、ご兄弟の下のお子さんが入学される時点では学区外となってしまいますので、これも兄弟枠という形での対応になってくるというものです。","id":"exchange-014"},{"speaker":"せお委員","kind":"質問","question":"例えば上のお子さんが第一日野小学校の特別支援学級に通っていて、下のお子さんは第一日野小学校の学区ではないということもあると思うのですけれども、そういったことは今までどういう対応になっていたのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"その後、最終的には地域で兄弟一緒に、というケースなども途中から出てきたりもします。特別支援学級を選択されるお子さんの部分だけで対応していますので、指定校変更等の相談が叶うかどうか、全体の状況を見ながらとなります。","id":"exchange-015"},{"speaker":"せお委員","kind":"確認","question":"状況を確認したく、質問させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"確認","question":"先ほど言い忘れてしまったのですけれども。一つ確認で、それも必ずしもそこの学区ではなく、そこは相談の中で十分対応していただけるということでしょうかという確認です。","respondent":"大関教育総合支援センター長","answer":"特別支援学級の原則としてホームページでお示ししているのは、あくまで原則という形です。個別に就学相談を進めながら、例えば、浅間台小学校のほうを選びたいというような相談を受けるケースには柔軟に対応しています。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、柔軟にというお話を伺ったので、ぜひ個別に保護者の方と十分に話し合って、進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]},{"id":"topic-02","title":"児童相談体制の強化","agenda":"児童相談体制の強化","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"警察と情報共有していくということで、具体的にはどういった運用といいますか、実際の形がイメージできるようにご説明いただけたらと思います。それがいいのか悪いのかについてもあると思うのですが、そこのところと、そういった奥まった場所になった経緯などを伺えればと思います。","respondent":"崎村児童相談担当課長","answer":"警察に１１０番で児童虐待が疑われるような事案が来た場合には、これまでも照会があったところで、それについて回答をしています。昨年４月に一時的に移転をした後、どこかへ移転をしなければならないということで、経理課等と検討してきたところです。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、この協定を結んだ意義というのはどういったことになるのか、伺いたいと思います。きちんとわかりやすいようにしてほしいと求めましたし、児童相談所移管担当の職員の方が何人いて、それを伺いたいと思います。","respondent":"崎村児童相談担当課長","answer":"今後の職員の増員の見込みなのですけれども、今後どの程度増えていくかというところは、まだまだ見込めないところです。ただ、確実に増えていくところなので、今回、移転をして執務を行っていくです。","id":"exchange-020"},{"speaker":"のだて委員","kind":"確認","question":"そうすると、今後増えていくところで、分室は、スペース的には十分確保できるということでよろしいのですよね。確認を。","respondent":"崎村児童相談担当課長","answer":"今回、約４４０m2の物件に移転するというところで、事務室も相当確保しておりますので、今後、職員が複数名増えても対応できると考えております。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"４４０m2の中で事務室も確保していただくということなのですが、できる限り余裕をもってご対応いただけたらいいのではないかなと思っていました。そういった引き継ぎ等、今後、発生することを含めて、現在の移転先のスペースに関して、今、どのように考えていらっしゃるのか説明を求めました。","respondent":"崎村児童相談担当課長","answer":"月１回行われる児童虐待防止会議ですとか、虐待ケースの進行管理会議に活用する予定なのですけれども、そういった見通しはもって移転するものです。委員ご指摘のとおり、余裕をもって仕事ができるような環境というのは、心がけていきたいと考えております。","id":"exchange-022"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですが、建物は築何年というか、もともと何年前からあったものだったのでしょうか。２点お伺いします。","respondent":"崎村児童相談担当課長","answer":"こちらは昨年の８月までマンションギャラリーとして使われていたものになっておりまして、そのときに使われていたリース物件になっております。このリースが１年ちょっと使われていたと聞いておりますので、それをそのまま我々のほうでお借りいたしまして、今回…","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"ということは、マンションギャラリーで使われていた建物を、基本的にそのまま居抜きみたいな形で使うというイメージでよろしいのでしょうか。一部手直しとかもされる予定なのか尋ねました。","respondent":"崎村児童相談担当課長","answer":"は２階部分については、住宅仕様が２部屋ありましたので、この用途として使用するといったものです。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"この分室は、基本的には児童相談所ができるまでは、これを使っていくということでよろしいのか尋ねました。","respondent":"崎村児童相談担当課長","answer":"別に分けて考えておりますので、児童相談所ができたから、ここの建物がなくなるといったことはございません。新庁舎の検討も行われておりますので、今後、引き続き検討していきたいと思います。","id":"exchange-025"},{"speaker":"塚本委員","kind":"質問","question":"今までもやってきたことについて、データというのは、基本的には電子データで保管しているということでよろしいのでしょうか。紙とか電子データとか、もしかしたら違う形があるのか、それをお伺いしたい。","respondent":"崎村児童相談担当課長","answer":"かなり機密性が高い情報になりますので、やりとりは暗号化して送信するなり、そういった処置をとってからのやりとりになろうかなと思います。現在、口頭ベースでのやりとりで、それぞれの機関が記録をして保管するといったところでの共有を考えているところです。","id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"職員は全員触れられてしまうのですか。それとも、きちんとした管理のもと、担当者と上司のみとか、そういう情報へのアクセスの制限みたいなものというのは、どんな感じになっていますか。","respondent":"崎村児童相談担当課長","answer":"現在、我々が運用している児童家庭相談のシステムについては、児童相談担当の職員であれば、全員が閲覧することはできますけれども、ほかの職員は一切触れることはできないといったものです。","id":"exchange-027"},{"speaker":"塚本委員","kind":"意見","question":"ある意味、非常に避けられないというか、リスクがどうしても高まってくる。体制というか、つくっていっていただいて、しっかりとした情報管理ということで運用していただくようにお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]},{"id":"topic-03","title":"（仮称）品川区立児童相談所の開設時期","agenda":"（仮称）品川区立児童相談所の開設時期","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この間の検討の中で、問題になったところというのが何かあったのか、そこのところを具体的に伺えたらと思います。どういった形で進めていき、児童相談所としては何人の人材を確保していくのかというところが決まったのかどうかも、人数もお聞きしたいと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"その場合に、例えば、必ず３月までに設計をすべて終わらせなければいけないかというと、そこまでこだわる必要はないのではないかと。それから、今の時点で具体的に何人という計画が決まったわけではありませんけれども、可能な限り優秀な人材を確保してまいりたいと考えておりま…","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"さまざまな観点でしっかりと吟味していただいて、子どもたちにとっていいように、ぜひ進めていってほしいと求めました。児童相談所の開設が２年延びたことも含めて、しっかりと進めていくことができないのかなと思うのですが、その点はいかがか尋ねました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"昨年６月に新しく成立しました改正児童福祉法におきましては、法律の条文を見る限りでは、なかなか楽な道ではないということもあります。もう１点は、というわけにはまいりませんので、なかなか全体を通して数をお示しできていないという状況です。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"わかったような、令和６年度までということになりましたので、人材確保と育成に向けてしっかりと取り組んでいってほしいと求めました。そういった検討も行っていくということで、民間委託の方針をもっているというのはやめるべきではないかと思うのですが、最後に伺いたいと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"まずはそれぞれの業務に求められる専門性とか、区の関わり方などの観点から、委託の可否を慎重に検討してまいりたいと考えております。委託ありきではございません。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"それがどうしてかというと、しっかりとした対応を行っていくためには、やはり民間委託ではできないという判断だということだと思うのです。ぜひそういった面も考慮していただいて、しっかりと職員を採用できるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"品川区にとってどういった形がいいのかということで、ぜひ丁寧に進めていただきたいと思うのですが、その辺りのご見解をお聞かせください。どういったことを始めていくと有効であるかとか、そうでない部分と、現時点での考え方を説明を求めました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"これで本当にいいのかなと思う部分もありますけれども、今まで見聞きしたことを信じて、最後はとり得る最善の手段を講じていきたいと考えております。大体信号１個分ぐらいの距離にはあるのですけれども、その辺りにつきましては、東京都とも調整していきたいと考えております。","id":"exchange-033"},{"speaker":"横山委員","kind":"意見","question":"東京都との調整を含めて、また国の動きも、これからいろいろな状況によって変化もあるかもしれませんので、そういったところはアンテナを張っていただきながら、ぜひ慎重に、そして丁寧に、しっかりと進めていっていただけたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"}]},{"id":"topic-04","title":"三ツ木保育園の運営業務委託","agenda":"三ツ木保育園の運営業務委託","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回応募されたのが７社あるということで、ほかの６社はどういったところだったのか、伺いたいと思います。ライクアカデミー株式会社がなぜ選ばれたのかということが、より透明性が増すということになると思うのですが、この点を伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"本事業の実施方針や区の理念と一致しているか、保育内容に対する考え方が区の考え方と一致しているか、それぞれ評価しています。質疑応答では確認いたしまして、最も優れた提案と実現性が見込まれた事業者を選定会議に諮りまして、最終的に決定した次第です。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"このライクアカデミー株式会社が一番点数が高かったところというのは、評価項目での一番よかったところといいますか、そこがどこだったのか、もう少し詳しく伺えればと思います。","respondent":"吉田保育施設調整担当課長","answer":"第２次審査におきましても、当該事業者は説明がわかりやすかったものと認識しております。それから、保育事業者としても３０年以上の実績があるというところで、委員全員の賛同によって、この事業者を選定した次第です。","id":"exchange-036"}]},{"id":"topic-05","title":"ベビーシッター利用者支援の制度変更","agenda":"ベビーシッター利用者支援の制度変更","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところが実際のところ、どう変わるのか、そこをもう一度確認させてほしいと求めました。今回、この変更をするに至った経緯を伺えればと思います。","respondent":"大澤保育支援課長","answer":"例えば２,５００円を支払っている場合は、１,９１０円のキャッシュバックでございましたので、利用者にとってはメリットがあると思われます。変更の理由ですが、令和２年４月から廃止になるということから、新制度への移行に至ったものです。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、ベビーシッターの利用料というのは、平均でいくと１時間当たり２,５００円ぐらいと考えてよいのですか。その事業者の一覧ですとか、そういった資料というのは事前にわかるということになるのか、伺いたいと思います。","respondent":"大澤保育支援課長","answer":"仮に今まで、例えば２,０００円以下で利用していた方がいらっしゃった場合は、大体２,０００円プラス消費税というのが一般的だと聞いてあります。都の契約した事業者は、現在のところ１３事業者ありますので、それについては利用を希望される方には周知をしてまいります。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"これまで年間大体どれぐらいの人数の方、世帯というのですか、ご利用されているのか、実績を教えていただけますか。","respondent":"大澤保育支援課長","answer":"平成３０年度の利用実績が６名、令和元年度９月まで、前期の利用者数は２名です。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"一応、いわゆる一般の保育施設といったものを利用されずに、仕方なくという感じなのでしょうか。それとも、あえてという感じなのか尋ねました。","respondent":"大澤保育支援課長","answer":"これまでのところ、不承諾の要件なく、あえてベビーシッターを利用したいというお声は、区には届いてございません。あくまでも自宅での保育になりますので、その部分がハードルが高いようで、なかなか利用実績としては、それほど伸びはないというのが現状です。","id":"exchange-040"}]},{"id":"topic-06","title":"認可保育園の新規開設等","agenda":"認可保育園の新規開設等","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"今回初めて品川区で実施する事業者というのはあるのかということの確認と、裏面の認定こども園の移行というのが、移行するに至った背景や経緯を伺いたいと思います。","respondent":"大澤保育支援課長","answer":"１番の株式会社クオリスは、隣りの大田区にも３園ありますので、地域的には一定のご理解はいただいているものと考えています。こちらは当初からこども園に移行したいと考えておりましたが、少し慣れてから移行するということで、今回の移行に至ったものです。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"今回、代替遊戯場を設定せずに、施設内に園庭があるということで、そういったことができた理由を伺いたいと思います。子どもですとか保護者への影響が、あるのかないのかも含めて、どういったことがあるのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"もちろん、株式会社クオリスが園庭の重要性を認識して、努力していただいているものと考えています。認定こども園ですが、こちらは２・３号認定の人数に変更がございませんので、大きな影響はないと考えています。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういった園庭のある保育園が増えるように、今後も区としても働きかけを含め、支援をしていってほしいと求めました。認定こども園は、認定こども園に移行することによってのメリットといったところは、区としてはどのようにお考えか尋ねました。","respondent":"大澤保育支援課長","answer":"地域子育ての支援事業をすることが義務づけられてきますので、区にとっても、区民にとってもメリットがあると考えております。絵本の読み聞かせとか、さまざま展開してくださっておりますので、引き続きその部分に力を入れてやっていただければと考えています。","id":"exchange-043"}]},{"id":"topic-07","title":"上大崎三丁目教育・保育施設の事業者公募","agenda":"上大崎三丁目教育・保育施設の事業者公募","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"認定こども園で公募するということで、認定こども園ということにしたという理由を少し説明していただきたい。はぐはぐキッズ中延が１年前に認可保育園で開設して、１年後に認定こども園化ということで、なぜ認定こども園にしたのかの説明をお願いします。","respondent":"大澤保育支援課長","answer":"保育の必要なお子様だけでなく、教育部門として広く地域のお子様をより多く受け入れる施設ということで、認定こども園ということを想定しています。あわせて、地域の子育てに貢献する事業が必須になってきますので、その辺りも重視をしております。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"今、そういう意味では、認可保育園の中で認定こども園化を考えているところというのは、結構あるのでしょうか。現状だけ、最後にお伺いします。","respondent":"大澤保育支援課長","answer":"今、保育室の面積に対して定員ぎりぎりに設定している園が多いので、なかなか今の状況では認定こども園への移行というのは難しいと思います。今後、少し入園児が落ちついてきますと、保育の要件がない方も受け入れるという意味で…","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"応募の条件というのは、施設種別と付帯機能以外に何かあるのかということと、施設をつくっていくにあたって、住民の方からしっかりと声を聞いていただいて、説明会などを開いて周知もしていただくという進め方でお願いしたいと思うのですけれども、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"細かいことでいろいろありますが、基本的には認可保育園等をきちんと運営できる事業者であれば、どなたでも応募はできるということになっております。既に説明会等でいろいろなご意見が出ているところですので、事業者が決まった後にも説明会を開いて…","id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"質問","question":"認定こども園についてのお考えを伺ったのですが、なかなかそういった事情があるので、余裕がないというように受け取りました。そういった機能は不可欠だというお考えだと思うのですが、公立の認可保育園の認定こども園への移行については、どのようにお考えなのか尋ねました。","respondent":"佐藤保育課長","answer":"昨年度、今年度も、特別区は２３区全体で協議しているところです。今後も引き続き検討してまいります。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"意見","question":"今、お話にあったような課題が解決しなければならず、なかなか難しい点だと思いますが、必要性というか重要性は認識されていると思いますので、ぜひ前向きに、他区などとも協議しながら、協力しながら進めていけたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"}]},{"id":"topic-08","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"フリースペースとかエールしながわは総合的なものなのかなというイメージをもっているのですけれども、その辺りの違いを教えてください。マイスクールに通われているお子さんが、重なって利用されている方はいらっしゃるのか、その辺りの状況を説明を求めました。","respondent":"大関教育総合支援センター長、廣田子ども育成課長","answer":"学校に戻ることを応援する施設として、さまざまな内容がありますけれども、学習をメインとした取組となっております。この後、所管から説明があろうかと思いますが… カウンセラーとの情報交換をしているところもあったりするので、本人が選んで来たいところということで、来た者は拒まずに受け入れているところです。一緒に支援をしていますので、どこでなければいけないというところではなく…","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"その中で、中学校・義務教育学校後期課程では３.７１％ということになっておりますけれども、理由の分析があれば伺いたいと思います。ほかの自治体で高いところがあるということだと思うのですけれども、どこが高いとかがわかりましたら、伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"あるいは家庭に係る環境のさまざまな背景なども対応していきますと、本人を支える支援のさまざまなリソースが、一つの鍵だと我々も分析しております。あるいはさまざまな理由から…","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"教育をする場所ですから、そういう学業不振の方への支援というのも、しっかりと教育施設としてやっていってほしいと求めました。そこのところで今後、何かやられていくというものがありましたら、伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"いろいろなお子さんもいる中で、どう支援していくかという部分を教育委員会が考えている内容が、これまでの適応指導教室の拡充という形であります。先ほどご説明したｅライブラリなども活用しながら、マイスクール五反田やマイスクール浜川では、最近活用してきているところです。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"そこを伺いたいのと、マイスクールについては、３か所どこも定員がいっぱいになっているという状況なのでしょうか。今の指導内容・方法についての問題点といいますか、区の認識を伺えればと思います。","respondent":"大関教育総合支援センター長","answer":"例えばマイスクール五反田やマイスクール浜川の午後の対応できるコースをもう少し工夫するなど、今、そういったことを考えて検討している最中です。個別の実態に応じてしっかりと対応できるよう、特別支援の内容だけでなく、学校と同じようにアレルギー対応であったり。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"エールしながわでひきこもり学習会とか家族懇談会をやられるということなのですが、不登校のほうの家族懇談会とか、そういったものはないのかどうか。どういった対応をしていいのかということが家庭ですぐわからないというところで、やはり自治体としての責任を果たしていく、いかがか尋ねました。","respondent":"廣田子ども育成課長、大関教育総合支援センター長","answer":"「この人、ひきこもっていますか」といって見つけることができないので、「相談できるところがありますよ」という間口を開いているところです。支援しますという態度ではたどり着かないということなので… そのほか、教育総合支援センターとしては、ＨＥＡＲＴＳあるいは教育相談室でさまざまな対応を個別にさせていただいていますので。実態に応じながら、場合によってはさまざまな機関をご紹介させていただいたりとか…","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり人それぞれなので、きめ細かく対応していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問","question":"不登校のほう、資料２ページ目の成果で、９年生がそれぞれマイスクール八潮、五反田、浜川で２３人、高校進学の人数と全く同じになっていますが、これは９年生が全員、それぞれ３か所のマイスクールにいらっしゃっていた方が進学できたのだという捉え方でよろしいか尋ねました。","respondent":"大関教育総合支援センター長","answer":"９年生につきましては希望者全員が高等学校に、多くは都立高校、私立高校などに進んでいるような実態であります。そのためにスタッフも、面接練習などもしっかりとやったりして、学校と連携しながら進めているところです。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問","question":"大変すばらしいと思います。ほとんど“どこかに進路が決まっています”と毎年お話を聞いているのですけれども、大体進路というのは決まるものと捉えてよろしいのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"ただ、進路希望という場合には、マイスクールに来ていなくても、学校で進路担当が必ず進路相談を行います。昨今は先ほど言いましたサポート校のような形などもありますので、何らかの進路を、ということで対応しております。","id":"exchange-056"},{"speaker":"塚本委員","kind":"質問","question":"そういうやり方もありだという考え方というのが、多分その背景にはあるのだと思うのです、そういうサポートをされているというのは。ほぼ高校に進学するのでしょうから、そういう部分は、進学できているということになるということでよろしいか尋ねました。","respondent":"大関教育総合支援センター長","answer":"９年生の国語とか数学とかの評価の点数だけではなくて、さまざまな本人なりの進路を目指した意欲だけで、面接で頑張れば入れる学校もあったりします。大学に入ったとか、自己実現に向けて何をしたいのか…","id":"exchange-057"},{"speaker":"塚本委員","kind":"質問","question":"今、定員はいっぱいな感じで、もっとたくさんの人がマイスクール八潮等に通うということも考えていくべきなのかもしれないですけれども。３つのマイスクール八潮、今後の一つの流れなのかなと思いますけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"自宅でパソコン、そちらに通うための通学証明書を出してほしいなどという個別のケースなどには、学校は柔軟に対応するようになってきております。さまざまな選択肢の中で柔軟に進めつつも、区としては、やはりマイスクールのような核となる部分は…","id":"exchange-058"},{"speaker":"塚本委員","kind":"質問","question":"小学生から４０歳くらいまでが対象で、これだけの幅の人たちがここに集っているという状況は、それによる一つの課題みたいなのはないのですか。小学生と３０歳を超えている人が一緒にいて、いづらくなるということが逆にあったりしないのかなと思ったりするのですけれども、いかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"５０代も、少しですが来ていたりとかするので、火曜日・木曜日に、別途１８歳以上を対象に、社会に出るための支援みたいなことで時間を設けました。そういう意味で、出口をどうしたらいいかというのに取り組んでも、成果がなかなか出ないので、別の方法を探している…","id":"exchange-059"},{"speaker":"塚本委員","kind":"質問","question":"未来に対して何かしら目的なり、こうなりたいというのをもっているというところに対して、支援というのは比較的できると思うのですけれども。利用している人へのある種の対応の違いというか、そういうことも考える必要があるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"準備を頑張り過ぎて当日来られなかったり、準備には来られなくて当日だけ来られたとか、そういうことがあります。自分たちで考えてというようにできればいいのですけれども、満足だったり、当事者たちにあたっているという本当に手探りの状態です。","id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"登録者約２００人ということで、利用できる人というのは、１,５００人いる中では本当に一部なのです。もちろん１,５００人全員を相手にすれば、そういうわけにもなかなかいかないでしょうから、そういった検討もしていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"高橋（し）委員","kind":"確認","question":"その後どうしているとか、元気だとかというフォローというのでしょうか、そういった体制はどのような形でとられているのでしょうか。その後、安心して学校で生活していけると思うので、その点についてお伺いします。","respondent":"大関教育総合支援センター長","answer":"個別の対応ということで、徐々にやっているところです。本来は特別支援教室のほうを、学校と教育委員会も対応しているところですけれども、これまでもございました。","id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"意見","question":"ぜひ指導員の方が接触というか、関わって、その後もできるだけ支援していただけるとありがたいと思うのです。最後にその点をとの意見を述べました。","respondent":"大関教育総合支援センター長","answer":"そういった工夫はできるように、携わるスタッフはそういった資料なども手元に置いた形で、相談業務に日々あたっております。教育総合支援センターとしては、そういったところを受け皿に、必要なところに支援をつなげるという形は今後もやってまいります。","id":"exchange-063"},{"speaker":"横山委員","kind":"質問","question":"２点、お伺いいたします。教育相談室の１８歳までのところと、こちらのひきこもりの支援というところと、現在どのような形で連携をされているのか尋ねました。","respondent":"大関教育総合支援センター長、廣田子ども育成課長","answer":"卒業後のそれぞれの方のデータベースのような形は、東京都も含めて、あるような状況ではありません。ただ、ご相談があった場合にはご紹介するというのが現実です。 子どもたちが寄ってきたりしたというところで、それなら貢献できるということで始めたものを、おそらく委員がご覧になったのだと思います。卓球は１人ではできないので、ちょっと緩い感じではあるのですけれども…","id":"exchange-064"},{"speaker":"横山委員","kind":"質問・要望","question":"信州大学医学部の本田秀夫先生の講演をお聞きしたのですけれども、好きなこと、まず取り入れたりするような手法があるということをお聞きしました。やり方というのを、ぜひこれからも研究していっていただきたいと思うのですが、品川区の考え方をお知らせいただけたらと思います。","respondent":"廣田子ども育成課長","answer":"我々が遊んでいるように見えるものでも、専門家やいろいろな方のご意見を聞きながら、導入していくというか、なおかつ自分たちで決めていくようにもっていくという形で、委員ご指摘のとおりで、取り組んでいきたいと考えています。","id":"exchange-065"},{"speaker":"横山委員","kind":"質問・要望","question":"状況を確認させていただきまして、ありがとうございました。それともお子さんへのアプローチなのかとか、いろいろなやり方があると思いますので、ぜひ研究してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"横山委員","kind":"質問","question":"すみません、１点だけ。湿気による重みの可能性があるということをお聞きしたのですけれども、区内全体の施設については、どういった状況になっているのか尋ねました。","respondent":"有馬庶務課長","answer":"今回は日野学園のプールということですけれども、ほかの温水プールについても至急調査をかけるということにしております。図面上で見ているのと、実際にどういうものかというところもあわせて、今、緊急の点検をしています。","id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=4990#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":65275,"voices":190}},{"id":"r02-20200120-5","meetingId":"r02-cm01","date":"2020年1月20日","dateIso":"2020-01-20","committee":"総務委員会","time":"午後 １時００分～午後 ３時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"令和元年陳情第６６号 情報公開請求に必要な研修の実施を求める陳情","agenda":"令和元年陳情第６６号 情報公開請求に必要な研修の実施を求める陳情","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"年３回の研修会を行っているということですが、それとも不適切な対応だと思うのか、その点を伺いたいと思います。具体的には大きく２点、１４日過ぎても決定通知が届かないことが何度もあったという陳情ですけれども、伺いたいと思います。","respondent":"木村広報広聴課長","answer":"設計図のみ存在していたということで、その件名としてお答えしたものでございまして、適切に対応したものと考えているところです。それから１４日以内ということで、こちらも１４日以内に決定しておるところでございまして、適切に区のほうで対応を進めてきたところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ部分公開決定とし、するべきではなかったのかと思うのですけれども、伺いたいと思います。これは私も、区の認識としては１４日過ぎても相手に決定通知が届かないという実態はないということなのか、その点も伺いたいと思います。","respondent":"木村広報広聴課長","answer":"１点目につきましては、この担当者のお答えどおりの状況でございまして、区は存在するもの全部を公開したです。その点についてはご本人にもお伝えしています。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"何を公開してほしいのか、決定前の調整というのでしょうか、ご本人とのやりとりというのはあってしかるべきだと思うのです。窓口での対応や期間の取り扱いについて、年３回の研修の場で改めて強調といいますか、位置づけをするべきだと思うのですけれども、いかがか尋ねました。","respondent":"木村広報広聴課長","answer":"ただいまのご指摘の点ですが、引き続き研修あるいは庁内周知等の場をもちまして、周知徹底に努めてまいりたいと考えています。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"むしろどこの窓口でも情報公開の手続きのプロセス、資料として、置いてあってもいいのではないかと思ったものでした。どこも統一ですかということと、陳情の中では３点挙げられているのですけれど、これで正しいのかという部分をご説明ください。","respondent":"木村広報広聴課長","answer":"先ほどの１４日間の話ですとか、窓口でのやりとりですとか、そういう具体的なポイントもあわせて説明させていただいているところです。それから研修の対象者に関しましては、この陳情のとおりです。","id":"exchange-004"},{"speaker":"田中委員","kind":"意見","question":"今お話があったチラシの配布に関しては、正式に行ってくださったところは、私が今まで請求したところで１カ所しかありませんでした。なので、研修が十分だとはちょっと思えないのですが、そのことに関してお答えほしいと求めました。","respondent":"木村広報広聴課長","answer":"説明が十分だったか、手順について統一されていたかどうか、そこら辺の研修はどうかということでございました。今のようなお話も伺いましたので、引き続き各職場での周知、徹底を努めてまいりたいと考えています。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"「設計図書一式」というのは、普通に使われている用語なのでしょうか。そこをまとめていただくとか、それこそそういうのが情報共有だと思うのですが、いかがか尋ねました。","respondent":"小林施設整備課長、木村広報広聴課長","answer":"「設計図書一式」というところでお答えします。当然図面もつけまして、そういうところで設計図書をつくっていくというところが、一式というところです。 大変貴重なご指摘です。実際に事例をもとにこういうところで話をする、いわゆる研修の中身として、考えてまいりたいと考えています。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"どういう取り決めになっているのでしょうか。情報共有とはどういうことが共有なのかということを、説明の仕方というのは工夫してほしいと求めましたが、いかがか尋ねました。","respondent":"木村広報広聴課長","answer":"今のご指摘です。実際にこういう事例があったということで、いわゆる個別にならないような形で、説明をしてまいりたいと考えています。","id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"それはいかがなのでしょうか。そこだけ確認したいと思います。","respondent":"木村広報広聴課長","answer":"調べますと、言葉そのものは「設計図書」という形でございまして、ただ定義といいますか、解釈がいろいろあるところです。委員おっしゃるように、この請求者の方がどういうことで、そういう形で書かれてきたか、なかなかあずかり知れないところです。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"こちらの思っていることと、相手の請求していることがずれる可能性があるので、そこは必ず確認してほしいと求めました。この陳情の前半でおっしゃっていることは、そこの部分だと思いますので、ぜひ心がけてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"１４日云々ありますけれど、やはりいろいろな事情が出てくるではないですか。１４日でやりますよ、では中途半端な資料でいいのですかという話になると困るし、そういう丁寧な説明はされているのですよね。","respondent":"木村広報広聴課長","answer":"２点ございました。それから１４日以内の話ですが、先ほどの委員への説明と矛盾するところはあるかもしれませんけれど、各窓口ではご説明をして、対応しています。","id":"exchange-010"},{"speaker":"中塚委員","kind":"確認","question":"先ほど設計図書の説明の中で、設計図のほかに特記事項というものがあるというご説明がありましたけれども、今回の陳情者が請求をした事案については、その特記事項というのはないということなのか、そこを確認させてください。","respondent":"小林施設整備課長","answer":"先ほど、設計図書一式の中に図面、特記仕様関係があるというお話をしましたけれども、通常、図面と同等の大きさで特記仕様もその中に記入しますので、基本的には図面と一緒についてくるものですから、お渡ししていると考えております。","id":"exchange-011"},{"speaker":"中塚委員","kind":"確認","question":"ということは、今回、設計図として公表した、お渡しした中に、特記事項も含まれているということでよいのか、もう一度確認させてください。そういう環境整備というものも、今後ますます必要になってくるかと思うのですけれども、その点についてもあわせて伺いたいと思います。","respondent":"小林施設整備課長、木村広報広聴課長","answer":"設計図書の中には特記仕様が含まれているのかというご質問ですけれども、含んでいると考えております。 いわゆる「うちではないからありません」とかではなく、実際に中で調整をしてお出しするというような運用の徹底を図ってまいりたいと考えています。まず窓口での聞き取り、あるいは内部調整…","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"公表されるものとしての文書を日常的に取り扱っているという意識が働けば、公文書としての管理も徹底されていくと思うのです。今後重大な課題だと思いますので、ぜひ検討を進めていただきたいと、関連して要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"しっかり聞き取りの徹底をして、請求するほうにも求められるのではないかというところで、ぜひそういうふうに対応していってほしいと求めました。さまざまな事例も含めて、しっかり研修をされているということなので、不採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"小芝委員","kind":"意見","question":"ですので、それを職員研修のレベルにまで引き上げていくというのは、はなはだ疑問が残ります。よって、この陳情に関しては不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"つる副委員長","kind":"質問・要望","question":"求められている職員の研修は既に実施されているということと、伝わった、伝わるというのは意味が違うのですね。伝わるということを常に意識していくことを強化するような研修内容というのでしょうか、本陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"実態として１４日を超えて決定通知書が届けられている、これはやはり不適切な対応だと思いますので、必要な研修をしっかり行うべきだと思います。あわせて、行政資料のホームページ上における積極的な情報提供を求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は本日結論を出すということと、不採択でお願いしたいと思います。請求者は区民の方ですが、なかなか理解していただけない方もいらっしゃると思うので、今後も丁寧な対応を心がけてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"きちんと窓口で請求者が何を求めているかという聞き取りが必要で、こういった表現だったら出すことはできますよという対応がされるべきだったのです。求められる側にそういう知識がなかったということで、やはり研修が重要だということなので、私は採択を主張します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、確認作業は必要かと思っています。「こういうものが必要なのでしょうか」という一言を担当の方が心がけていただければ、済むのではないかと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"}]},{"id":"topic-02","title":"品川区長期基本計画の策定状況","agenda":"品川区長期基本計画の策定状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"書き方の体系上、何か工夫ができないかと思うのですけれども、その点を伺いたいと思います。そういう品川区、また行政であっていただきたいと思うのですけれども、この点についても伺いたいと思います。","respondent":"柏原企画調整課長","answer":"いただいたご意見につきましては検討させていただきながら。さまざまな方法は考えられますので、期間も考えた中で動くというのもありますので、検討させていただきたいと思います。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"賀詞交歓会でも品川区民憲章を毎年確認いたしますけれども、あれは「進んで区政に参加します」というふうに位置づけられているのですよね。説明会や区民同士、区と区民の意見交換、さまざまな場面をしっかりと位置づけていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"今、ホームページの中では、まだＰＤＦなのですね。ホームページ上で、また読み取れるテキストになるのかというところを確認させていただきたいのですけれど、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"我々としましてもこちらの長期基本計画は、さまざまな方に知っていただくことが大切なことでありますので、その手法については検討しています。形がどうなるかというのはあるのですが、なるべく多くの方に知っていただくような努力はしていきたいと考えています。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"どういう活用の仕方を考えられているのか、そして区民への周知方法、通常であるならば何か小冊子か何かつくるのですかね。何かしらの形で伝えるのだろうと思うのですけれども、その二つをお伺いします。","respondent":"柏原企画調整課長","answer":"それで、それに基づいた施策を、予算等も絡むところですが、１０年間の計画の中で進めていくということになります。お示しの仕方をどうするかというのはあるのですけれども、概要版についてはよりわかりやすく、広く伝わるような形でお示しできればと思ってあります。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"この長期基本計画に基づいた計画、それが実行という形に見えてくるのは、令和２年度の計画から反映されますよという形でよろしいでしょうか。というメッセージは、やはり区のほうから出向いていってすべき時期に来ているのではないかと思うのですが、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"委員のご指摘もございましたけれども、さまざまな数値的なところについては今、検討しています。なるべく多くの方に見ていただきたいとこちらも思っているところでありますので、手法も含めて研究させていただけばと思ってあります。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"この長期基本計画に基づく予算というのが２月初めにプレス発表されて、予算書が出てきて、それを見て初めて知るという形になるのでしょうか。今度の令和２年度の予算審議のときに、この計画に基づいた事業という形で出てくるのか尋ねました。","respondent":"柏原企画調整課長","answer":"それを今度は次の段階でいいますと、ブレークダウンするので、どういう形にするかはあれですけれど、実施計画的なものも検討しているところです。長期基本計画はこれで、考え方、方向性というところが出されて、今、最終的な区の決定ということで内容を検討…","id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"どういう事業をしていくかというのが、非常にメッセージ性として弱いなというのが、正直な思いです。３月には予算審議が入ってくるという中では、情報も早目に出していただきたいと、要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"つる副委員長","kind":"質問","question":"総合実施計画が３年ごとだと思うので、どういう表現になるのかあれですけれど、後から３年間のそうしたものが示されていくのか。要するに令和２年度の予算として示されて、３年間の総合実施計画というものが区民に示されていく、その辺のタイムラグを改めて説明を求めました。","respondent":"柏原企画調整課長","answer":"長期基本計画、この１０年間の考え方というのを、今回まとめていただきましたので、それに基づいて実施していきたいです。３年かどこかというところで区切りながら出していくので、そもそも１年遅れで出てくるとか、当然整合をとりながら打ち出しができればと考えています。","id":"exchange-028"},{"speaker":"つる副委員長","kind":"質問・要望","question":"総合実施計画があって、その総合実施計画についても令和２年度のやるべきことを含んだ３年間とか、双方調整しながらやっているという理解をしました。さらなる１０年後にはどういうふうにその辺を示していくかということも、検討課題として、まさに検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"いろいろな場面が出てくると思いますが、私は区の施策として、そこは柔軟に対応していってほしいと求めました。何が起こるかわからない、この１０年なのかなという気がしましたので、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"}]},{"id":"topic-03","title":"五反田公園他１４８箇所防犯カメラ設置工事請負契約","agenda":"五反田公園他１４８箇所防犯カメラ設置工事請負契約","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"そういった契約がこの中に含まれているのか、確認させていただきたいというのが１点。不安の声もいただいているので、そのあたりをわかるようでしたら、お話しほしいと求めました。","respondent":"立木経理課長","answer":"こちらの資料４ページの写真に関しましては、このとおりに設置されるかどうかということは、仕様の詳細の中で決まっていくことかと考えています。そちらの仕様で触れられる内容かと考えていますので、私のほうからお答えすることは難しいと考えています。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"防犯カメラ作動中といった周知のチラシとかは、契約の中に入っていないということなのかということと、カメラに映る範囲については、契約の中でここまで映りますといったことは示されないで、契約ということか尋ねました。","respondent":"立木経理課長","answer":"周囲の方への周知等に関しましては、恐らく工事説明の中でされるものかと思いますが、恐らく入ってなかろうかと考えています。設置場所もきちっと設計図のほうに入っているものと考えております。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"求めたいのは、現在のこの形だと、何かが起きたときの事後にこの防犯カメラは役に立つと思うのです。そういった、このシールなども、契約の中に示されているのかというところを知りたかったのですけれど。","respondent":"立木経理課長","answer":"防犯カメラが作動しているかどうかを周囲に知らしめて、それをもって防犯の向上ということに関しましては、所管のほうに伝えさせていただきたいと思います。","id":"exchange-033"},{"speaker":"小芝委員","kind":"確認","question":"確認ですけれども、今回の防犯カメラ設置工事をもって、区内全ての公園に防犯カメラが設置されるということでよろしいのか尋ねました。","respondent":"立木経理課長","answer":"詳細につきましては私どもではわからないのですが、何年かかけて防犯カメラを設置していくということは聞いております。一部工事の調整等が必要な部分は、これから検討するということは聞いております。","id":"exchange-034"},{"speaker":"小芝委員","kind":"質問・要望","question":"防犯カメラの設置を強化してほしいと求めましたし、公園によっては１カ所だけでなく、場合によっては増設されたほうがいいのかなと思います。意見とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"先ほどから１４９とおっしゃっていて、なぜ１４８と書いているのに、と誤解してしまったのです。補助金との関係の中で、設置をする決め手というのは何かあるのかどうか、いかがか尋ねました。","respondent":"立木経理課長、品川財政課長","answer":"もちろん予算がないと起工もできませんし、その財源の部分に関しましては、経理課のほうからのお答えは難しいところです。 補助のほうですけれども、東京都のほうで３分の１負担ということで、あとは区費になります。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"時期的なこととか、何か関係があるのですか。この時期とか関係なくいつでも、例えば区の事業としてまとまり次第、請求すれば補助金が下りるという感覚でよろしいか尋ねました。","respondent":"品川財政課長","answer":"基本的に制度上３分の１ということで、あとは東京都の予算の範囲内ということにはなるかと思います。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"では年間を通して請求できるということで、よろしいですか。どうぞと、それともこの時期にとか、そういう決まりはあるのか尋ねました。","respondent":"品川財政課長","answer":"補助金は基本的には年度当初、申請をしまして、そこでおりる、おりないというところがあると思いますけれど、申請して、それによって年度末で予算の範囲で補助金が支給される、そういう形になります。","id":"exchange-038"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認なので教えていただきたいのですけれど、公園によっては２台つくとか、そういう認識でいいのでしょうか。例えば安心・安全の防犯向上のためということでいうと、そういう要望が多いところからついていくのか、そこも教えてほしいと求めました。","respondent":"立木経理課長","answer":"１４９公園に対して台数が２３５台ということで、公園によりましては複数台設置されるというふうな内容になっているかと考えています。この順番がどうついたかにつきましては、所管のほうということになります。","id":"exchange-039"},{"speaker":"大倉委員","kind":"質問","question":"順番についてはわかりましたが、このとおり工事がされていくという認識でいいのですか。何か設置についての考え方というか、わかればと思ったのですけれど。","respondent":"立木経理課長","answer":"こちらは恐らく、区全体に散らばっているものでございまして、工事を施工する事業者のほうで、例えば近いところ同士をやっていくとか、そういった工程を所管課と打ち合わせした上で、施工されていくというふうに考えております。","id":"exchange-040"},{"speaker":"大倉委員","kind":"質問","question":"お話しいただいたとおり、効率のよい設置の形があるのかなと思うのと、一方、暗いところとか少し不安に思うところとか、住民の意見もあるのかなと思ったので伺いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問","question":"工事を発注するということなので、映像の管理というのが同時にどう扱われるのかということも、やはり伺わなければいけないと思うのですけれど。工事を発注するに当たって、映像の管理は大事なことだと思うので、ご説明いただけたらと思います。","respondent":"立木経理課長","answer":"工事の発注に当たりましては、そこのところも考えられた上で経理課のほうに、契約依頼が来ているというふうに考えてあります。映像管理に関しましては所管のほうにもしっかりとするように、改めて伝えます。","id":"exchange-042"},{"speaker":"中塚委員","kind":"意見","question":"建設委員会での議論にはなりますが、やはり映像となりますので、個人情報であったり、プライバシーの問題であったり、また犯罪の抑制という視点もありますし、警察との映像提供の関係など、さまざまルール化は当然必要だと思いますので、一つとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"つる副委員長","kind":"質問","question":"今、中塚委員からもありました、基本的に所管の建設委員会のほうで細かい部分は、３カ年の最終年度ということですけれど。３カ所というところもあるのかとか、こういうチェックというのでしょうか、やるのか尋ねました。","respondent":"立木経理課長","answer":"その仕様の中身が妥当かどうかというところはきちっと、所管と協議の上、内容の確認はさせていただいているところです。手続き上瑕疵がないものに関しましては、契約を順次をとらせていただくというようなスタンスで、やらせていただいております。","id":"exchange-044"},{"speaker":"つる副委員長","kind":"質問・要望","question":"たまたま近くの一民間の方がつけられているカメラに、犯人と思われる方の映像があり、可能性が高いというところで確認の照会があったり。あくまでも、要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"}]},{"id":"topic-04","title":"オリンピック・パラリンピック施設周辺道路遮熱性舗装工事（その２）請負契約","agenda":"オリンピック・パラリンピック施設周辺道路遮熱性舗装工事（その２）請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ここを遮熱性にしなければいけないということになって、都で補助金を１０分の１０出すからやってくださいという指示でやるのですか。予算のあり方です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"須貝委員","kind":"意見","question":"では、意見だけ。なかなか区民の理解が得られるような場所ではないと私は思うので、いかがかなという意見だけは言わせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]},{"id":"topic-05","title":"地方税の賦課及び徴収事務における特定個人情報保護評価の実施結果","agenda":"地方税の賦課及び徴収事務における特定個人情報保護評価の実施結果","exchanges":[{"speaker":"田中委員","kind":"意見","question":"０件ということで、この０件というのはちょっとと思いまして、周知に関してどうだったのか聞きたいのですけれど。どのように周知されたのか、お知らせほしいと求めました。","respondent":"伊東税務課長","answer":"４年前はどうだったのかという話になったとき、お一人で２件のご意見があったということはご報告させていただいたかと思います。２回目という、周知は前回同様、関心が少し薄かったのかなという気はしています。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"広報広聴課のほうに伺いたいのですけれど、一番最初のトップページにはパブリックコメント募集中のものが出てこないではないですか。区民の方がすぐに気づくようなホームページのつくり方にしてほしいと思うのですけれど、その辺、いかがか尋ねました。","respondent":"木村広報広聴課長","answer":"今、おっしゃるようにそこからいきなり、今やっているパブリックコメントがすぐに出ているというつくりにはなっていないところです。募集を開始するときにはお知らせとして出させていただいて、どういう形がよろしいかどうか、これからも議論をしていきたいと考えております。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の区民意見公募手続きにかかわらず、パブリックコメントをやる際には説明会を実施することを位置づけるべきだと、繰り返し求めてきました。区民への接近の仕方にあるという姿勢で取り組むことが、行政の姿ではないかと思うのですけれども、その点について伺いたいと思います。","respondent":"伊東税務課長","answer":"これに関して説明といいますか、説明もなかなか、説明ということなのかなと思っているところです。どういう周知方法が適切なのかというのは、その時点でもう一遍考えて、実施していこうと思っているところです。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"区民に意見を求める際には説明を尽くす、こういう姿勢であるべきだと思っていて、やはりとるべきではないと思います。行政はあるべきだし、改めて説明会を位置づけて、行政の説明責任を果たすという姿勢を強く要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"須貝委員","kind":"質問・要望","question":"「お問い合わせ／ご意見／ご要望／パブリックコメント」というふうに、きちんと明記されているのですから、広報紙で現に載せていて。実際にどうだったのかということはありますけれど、今後まだ続くわけですから、今のところではこれが精いっぱいな手法なのかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2156#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":33580,"voices":126}},{"id":"r02-20200121-14","meetingId":"r02-cm01","date":"2020年1月21日","dateIso":"2020-01-21","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"区組織と関連団体に関すること","agenda":"区組織と関連団体に関すること","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"国際友好協会とスポーツ協会それぞれについて伺いたいのですが、職員数のご説明がありましたが、１８人ということでよろしいのでしょうか。そういったＯＢの方の待遇面について、区は把握をしているのかいないのか、伺います。","respondent":"遠藤協働・国際担当課長、中元スポーツ推進課長","answer":"それから、区の幹部職員ですが、事務局長に１名おります。待遇面につきましては、区の再任用と同様の基準ということで運用していただいているところです。 区の係長級経験者が６名、それぞれの係に入ってあります。区の一般職員の経験のある者が４名で、区と全く関係がない方が４名という形になってあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"スポーツ協会のほうに関しては、区の職員のＯＢの方々の待遇面について把握しているのかということを伺ったので、そちらも後でお聞かせください。国際友好協会の活動費というのは、直営でやるのと違う点というのは一体どういう点が出てくるのかというのがわからなかったので、伺いたいと思います。","respondent":"遠藤協働・国際担当課長、中元スポーツ推進課長","answer":"それぞれ財団のほうでも直営事業というものも幾つかございまして、実際には財団の事業費の大体８０％弱ぐらいがこちらの助成金の額となっております。ある程度公共性は担保しながら、その辺うまく織りまぜてということで… それをもとにこちらも査定をする、それなりの対応をして、大体同程度のものを確保させていただいているところです。区のほうとよく協議をいたしまして、その年々によってやはりいろいろな変更事項等もありますので…","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"昭和６１年と違って、観光だけでも３,０００万人以上の人が現に日本に訪れて、その辺どうなのでしょうか。私、交流事業が縮小傾向にあるように見えるのですが、その辺についてどのようなご見解をお持ちか尋ねました。","respondent":"遠藤協働・国際担当課長","answer":"今後の５年間なりについてまず中身の確認、お子さん中心の、いわゆる民間活動に近いような形のものでの交流をするという形で進めているところです。事業としてはそちらの部分で継続して、大きい訪問団のような形のものは少しずつ縮小といいますか…","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"今、青少年、中学生とか高校生が行かれていると思うのですが、この方たちのその後というのは、やはりアンケートとか何かは調べているのでしょうか。そういう方たちと触れ合うチャンス、そちらに事業費を投入すべきだと思うのですが、その辺について再度説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"確かに友好協会でもずっと課題だということでは認識しておりまして、今、進めているところと伺っております。区も一緒に相談しながら、こちらのほうを発展させていくというか、進めていければと考えております。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"お聞きして、見直し等を含めて、これから考えていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"公益性が非常に強く求められるところ、労務的な監査だと思うのですけれども、そういったものをこの２つの法人に対して行ったことがあるのかどうか。行ったことがあるのであれば、どういう結果だったのか、わかる範囲で教えてほしいと求めました。","respondent":"中元スポーツ推進課長、遠藤協働・国際担当課長","answer":"今年度、スポーツ協会のほうは実施されているところでございまして、既にヒアリングは終了しているところです。現在、独自で社会保険労務士に月に２回程度… 社会保険労務士に実際に入っていただいて、規則の部分に不備等ございましたので、そこを今直していると聞いております。第三庁舎の４階にありますので、今のところ、そういう問題となる点はないのかと感じているところです。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"民間ですから、どういう採用をするというのは、少しチャンスを区民の方に与えるような形というのも今後必要になってくるのではないかと思うのです。２点、そういった力のある方、能力のある方の国際友好協会での活用と、職員の採用の部分について、ご意見があれば、教えてほしいと求めました。","respondent":"遠藤協働・国際担当課長","answer":"そういう部分について、友好協会でもボランティアが大事だという認識がありますし、ボランティアの活用ができるような形を考えていきたいと思います。いろいろ向こうのほうでの考えもあろうかと思いますので、このような話が出ていましたということで…","id":"exchange-007"},{"speaker":"あくつ委員","kind":"確認","question":"スポーツ協会のほうで、１０番にジュニアスポーツ教室運営および指導者養成委託というのがあるのですが、これはいわゆる再委託という形なのですかね。そこについて確認ができるのかどうか、説明を求めました。","respondent":"中元スポーツ推進課長","answer":"連盟のほうで対応が難しければ、そういう専門事業者の方から見積もりをとって、まず予算要求をします。どこに頼むかというところもきちんと職員同士の中で連絡をとり合ってありますので、お金の流れのところは把握をできる形になっているところです。","id":"exchange-008"},{"speaker":"芹澤委員","kind":"質問・要望","question":"なかなか倍率が厳しいものがあるというのが一つあると思うのですが、この事業の予算を拡大していくという方向性はどうお考えなのでしょうか。例えば、そういった大きなイベントにもぜひかけ橋になっていただきたいと思うのですが、そこら辺のご見解もあわせて説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"それから、ボランティア同士が集まって、自分たちで何か国際交流ができないかというところまでできればいいかというのは思っております。それにつきましても、まだ組織化できていない部分がありますので、その辺を含めて友好協会ときっちり話をして…","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"基本的なところで、理事長はどのような過程を経て決められているのかというのを説明を求めました。","respondent":"遠藤協働・国際担当課長、中元スポーツ推進課長","answer":"理事長の決め方ですが、理事会の中で決めているです。 スポーツ協会におきましても、理事会のほうにまずお名前の推薦がございまして、それを評議員会等で定款に基づいた手続をとりまして、承認していただいているところです。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"その理事会というものの中で、国際友好協会、そして、スポーツ協会ですが、それぞれの分野において、知見ないし経験を持った方たちが理事になっていらっしゃるのかと思いますけれども、そこのところはどうなのか説明を求めました。","respondent":"遠藤協働・国際担当課長、中元スポーツ推進課長","answer":"国際友好協会のほうでは、例えば、地域になじんでいる方、あるいは学校の理事長だとか、あるいは会社の相談役の方だとか、そういう方が満遍なく、国際交流に一定程度通じている方中心に就任されているです。 その中からの推薦ということでお名前が理事会のほうにある程度上がってまいりまして、メンバーが決まってくるです。会計のほうをやっていただく監事の方については…","id":"exchange-011"},{"speaker":"大沢委員","kind":"意見","question":"その中で理事長を決めていくということですけれども、組織なので、独立性、独自性を考えた場合に、区から助成金がかなり入っていらっしゃる。独立性、あるいは組織の色を出す部分について、区が特に気を使っていらっしゃることはありますかとの意見を述べました。","respondent":"遠藤協働・国際担当課長、中元スポーツ推進課長","answer":"いろいろ段階を経て、その方がふさわしいかという部分を皆さんでご審議いただいていると聞いております。理事長を誰にするかというときに、その辺で区のほうで一定程度、こういう方がふさわしいのではないかという形になろうかと思いま… どういう形で進めていったらいいかというところを、区としての事業の方向性とも、その辺のところは調整をしながら進めていっていただいているところです。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"今、お二人の課長からのご答弁にもありましたが、区のほうから一定程度の意見を申しつけているという。独自性を担保するという形式上の意味からすると、非常にこれは不自然な形に思うのですけれども、どのように思われますか尋ねました。","respondent":"中元スポーツ推進課長、遠藤協働・国際担当課長","answer":"もともと体育協会とレクリエーション協会という２つの団体であった時代から、今のところはどちらの形もきちんととりながら、区民のスポーツ文化の普及に努めているというところで進んでいけていると捉えているところです。 もともとは民間の組織だったものを財団化したですので、一定程度独自性みたいなものは必要かと考えています。区のほうでもいろいろな形で相談を受けたり、あるいは実際にかかわったりというところで…","id":"exchange-013"},{"speaker":"大沢委員","kind":"意見","question":"行政から指導、助成金をつぎ込んでということですので、一定程度は確かに必要だと思うのです。完全な意識でも形でも独自性が見えるような組織の形づくりというのが大事なのではないかと思うのですけれども、どのようにお思いになりますかとの意見を述べました。","respondent":"榎本総務部長","answer":"例えば、それは区としても公益財団法人としての成り立ちなり継続性なり信頼性なりを考えると、ある程度の枠というのは必要なのかと。その中で創意工夫をしてやってもらうということが大事なのかと感じております。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"どうしても助成金の関係と組織の独立性といった場合、そこのところでどうしても、どのようにお考えか尋ねました。","respondent":"榎本総務部長","answer":"今回の資料は、それぞれの団体は区議会の第２回定例会のときに事業計画と決算を全部出していますので、その中で全体像が見られるのかと考えています。各団体でそれぞれ独自の事業をやったり、新たな改革をやったりしていますので…","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"事業報告をしているわけですから、実際これはあったことなのですが、どのように思われますか。その辺についてどのようにお考えなのか、ご見解を説明を求めました。","respondent":"中元スポーツ推進課長","answer":"現状は本当に十分認識をしていますが、今後、そのようなスポーツができる施設をつくってほしいという予算要求のような形になりますでしょうか。そのようなことは心がけていきたいと考えているところです。","id":"exchange-016"}]},{"id":"topic-02","title":"旧国家公務員宿舎小山台住宅等解体工事の進捗状況","agenda":"旧国家公務員宿舎小山台住宅等解体工事の進捗状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"重複になるかもしれないのですけれども、国のほうから説明を受けているのは、今ご説明いただいた限りなのでしょうか。それから、区としてはどのような見通しを持たれているのか、そこら辺、もう少しわかっている限りで具体的にご説明願いたいと思います。","respondent":"柏原企画調整課長","answer":"見込みといいますか、できるだけ早期に、特に解体工事に入っていただけるようにということでの調整を今後かけていきたいです。対応をしなくてはいけませんので、今後、調整に入るというものです。","id":"exchange-017"},{"speaker":"おくの委員","kind":"質問・要望","question":"では、要望としましては、国から情報が入り次第、知らせてほしいと求めました。それから、令和２年１月中旬から下旬に地域・利用団体との意見交換会と書いてありますが、利用団体というのは何のことなのか尋ねました。","respondent":"柏原企画調整課長","answer":"それから、新しく拡張する部分についてはこういう考え方を持っていますというのを説明をするという段取りといいますか、話だと聞いてあります。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"モルタルに含有しているということですから、その辺、近隣住民の安全度というのはどの程度あるのか。近隣に話す時期もまた難しいかと思うのですが、その辺も対応していただきたいと思うのですが、どのような流れで行くのか尋ねました。","respondent":"柏原企画調整課長","answer":"ですので、住んでいた方々に何か影響があったかというところについては、国のほうの考えとしては、それはないという認識だろうです。近隣の方々への説明といいますか、今後の流れです。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"こういう建物に関して、こういうものでつくったという、おそらく図面、設計図書というのですか、そういうものが普通残っているわけですよね。各自治体をリードしているわけですから、現状、全然国のほうでは認識がなかったということなのですね。","respondent":"柏原企画調整課長","answer":"我々も把握できない部分ではありますけれども、ただ、あまり想定ができていない部分のアスベストだという話は聞いてあります。設計図書云々の話は、我々もわかりかねるところではあります。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"この検査自体なのですけれども、検査が始まった時期とか完了する時期についてというのは、区は聞いているのでしょうかというのがまず１点です。５番目のところの審議会で意見交換をやるというところは、どういうところというのを、名前を教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"現段階の考え方といたしましては、令和２年度には取得したいということで、区としては考えているところです。それから、細かいところは把握していないのですけれども、そういった形で周りの方々の意見を聞く場面をつくっていくというところで聞いてあります。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは令和３年、４年度からはそれぞれ延びるということでよろしいのか、伺います。これを先に行わなくてはいけない必要性というのはあるのか、そこら辺についても説明を求めました。","respondent":"柏原企画調整課長","answer":"令和３年度、４年度の部分につきましては、当初想定した予定よりはやはり後ろにスケジュールを倒さざるを得ないだろうです。なるべく早い段階で整備したいという思いがありますので、おくれないような形で進めるという方向で、区は認識しています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"共産党としても、本委員会で繰り返し求めてきたのですが、結局はそういうことは行われないまま来てしまいました。これは今回こういう予期せぬ事態が起こったわけですけれども、この時点でこれから修正していく意思があるのかというのも伺いたいと思います。","respondent":"柏原企画調整課長","answer":"これから進む事業の説明を丁寧にお話をさせていただきたいということで、決してやり方そのものが全て間違っていたという認識には立ってございません。このことに関しまして、どういった対応をするかというのをお話ができればという思いがございましたので…","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"西側になるわけですから、そうではないわけですから、少なくとも新年度予算に組んで取得するということは行わないよう求めたいと思います。住民が求めているような情報も含めた説明会の開催というのを行うべきだと思いますし、それを求めたいのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"そういったことに対しての何らかの説明会であるとか、区といたしましては、それをお願いしているといったところです。現段階で区が何らかの説明会ということになりますと、解体の話と東京都の公園の話ですので、そこは主体たる団体のところがやるべきです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"今すぐ真っ先に都有地を買って、その道路をまず半分だけ整備しておこうとか、それは必要なのですかということなのです。まだまだ尽くされていない説明がたくさんあるわけですから、品川区が施設をつくろうとしているわけですから、伺いたいと思います。","respondent":"柏原企画調整課長","answer":"こちらについても認識があるところですので、丁寧な説明、ご理解を得られるような形での今後の進め方というのも検討していきたいと思ってあります。考え方といたしましては、そういった点も含めて、土地の取得については検討していきたいというものです。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/988746?Template=document&Id=6082#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":29300,"voices":71}},{"id":"r02-20200122-18","meetingId":"r02-cm01","date":"2020年1月22日","dateIso":"2020-01-22","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"すみません、質問が違っていたらお許しください。そこら辺を詳しく、もしわかっていたら、すみません。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"あそこの中の２階にある食事の場所だと思います。あそこのスポーツセンターの食事どころについては、大会終了後にどうするのかというのはまた考えるところなのかなというふうに思っています。","id":"exchange-001"},{"speaker":"本多委員","kind":"確認","question":"その確認をしたいのと、大会時５,０００席で５００席を残すということなのですけれども、ちょっとその辺を説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その周りにぐるりと仮設の座席をつくって１万席になるです。サウスピッチの５００席ですが、これは既存のできているところが５００席で、５,０００席になるです。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"わかりました。何か品川区の役割が今までと変わるとか何か、そういったものも従来どおり東京都のほうで全額見ていくのか、管理とかコストについて説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらの施設なのですが、公園全体として指定管理で受託している事業者でございまして、その事業者が引き続きやるように聞いております。特に品川区で費用負担するだとか、そういった話は聞いたことはありません。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"大会終了後もやはりこの大会を通じて区民、都民、国民のホッケーを中心とするスポーツ全体の意識が高まる取り組みも品川区として常に意識を持って取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"文化交流という視点、そうした事業を伸ばしていくということが非常に重要かと考えておりますけれども、この大井ホッケー競技場を活用してそうしたイベントやライブなどの文化活動に利用するというお考えは今のところ出ているのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"公園全体を使ったイベントということで、文化イベント等も考えられるのかなと個人的には思うところです。いろいろクリアしなければいけない課題はあるかと思いますが、施設の一つとして考えられなくはないかなというふうに考えているところです。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問・要望","question":"品川区からも積極的に提言をしていっていただきたいと考えていますけれども、今後どのように品川区としてかかわり合っていくのか、現時点でおわかりになることをお知らせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらの施設は品川区にあるということで、今までも野球場等非常に区民の方がたくさん利用している状態です。そういう意味では、いろいろ話す機会もありますので、そういった中では話の中でそういうことを伝えていくということは可能かなと考えています。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"まさにこれはホッケー終了後、オリンピック終了後はぜひともホッケーの拠点になっていただきたいというのが一つです。それは課長、オリンピック・パラリンピック準備課としてはどういうふうにお考えになっているのかお聞かせほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"都内ではショートパイルで水をまく形の、ウォーターベースのピッチというのは初めてですので、それは優先されるものなのかなと考えています。連携できるときは連携して、うまく盛り上がっていくといいますか、水辺等で連携できるようなことは必要だなと考えています。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今日の資料にも記載があるのですけれども、青少年教育の場としても活用というのが書いてあります。何かしら競技大会にしてもそうですし、それはどういうふうに今後取り組んでいくのかどうか、最後にお知らせほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"せっかくこんなにすばらしい競技場が近くにありまして、小学校、中学校でホッケー体験をしております。これはぜひホッケー協会等と連携しながら、引き続きこれを続けていきたいなと考えているところです。","id":"exchange-008"},{"speaker":"つる委員","kind":"提案","question":"品川区からということは、先ほど筒井委員からあったように提言とか提案とか、そういった観点になってくるのかなと思います。ごめんなさい、委員長、確認なのですが、今日は大井ホッケー競技場だけ……との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"拠点であるからこそ、同じ区内にそういう、そういう可能性を今後品川区として模索していこうという案があれば教えていただきたい。大会時に７,４００席つくるその周りのことなのかなと思うのですけれども、どういうものが想定できるのか、わかれば説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"やはりちょっと厳しい部分もあるのかなと考えていますが、何かそういうご縁がありましたら積極的に協力していきたいと考えています。そこに大きな商業施設が入るだとか、食べ物屋が入るとか、そういったことは今のところはちょっと聞いたことがないです。","id":"exchange-010"},{"speaker":"つる委員","kind":"提案","question":"区としてもこういうのはどうでしょうかという提案があると思うのですが、何々するとか、そういう施設が正直八潮の周辺というのは少ないのかなと。あの周辺部にどこまでのどういうものを、そうしたものがどこまでできるのかなと思ったのですが、そのあたりをおわかりになれば説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"近くに、そういうのは個人的にもあったらいいかなと思いますので、それは東京都と話をするときにまたお願いをしてみたいなと思います。採算性のこととかを考えると、なかなか採算がとれないということもあると思いますので、何か可能性を考えていきたいかなと思っています。","id":"exchange-011"},{"speaker":"西村委員","kind":"質問","question":"そもそもなのですが、大井ホッケー競技場というネーミングがこのまま続くのかどうか、いろいろなスポーツを行う中で、ホッケー競技場という競技場の中でいろいろなスポーツが行われるのかどうか説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大井ホッケー競技場という名称なのですが、これは東京都の条例上この名前になっておりますので、このままでいくのかなというふうに認識しております。","id":"exchange-012"},{"speaker":"西村委員","kind":"質問","question":"地域の方々をどう巻き込んでいくか、何かそういったレガシー、お考えがあれば説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ホッケー関係者の方でも、また一つ、商店街のにぎわいの一つにつながっていくのかなと思います。そのあたりは商店の方とお話をしながら今後進めていくのかなと思います。","id":"exchange-013"},{"speaker":"小芝委員","kind":"質問","question":"やはり広く全体を俯瞰してオリンピック・パラリンピックのレガシーを考えていくべきだと私も思っております。文化のイベントのときもそうですけれども、そういうふうにやっていくのも一つの例ではないかなと思いますが、いかがお考えか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そのまま奥のほうに行って、ずっと散歩コースといいますか、ウォーキングコースとしても非常に有益かなと思います。広報紙等でご案内するだとか、そういった形で区民の皆様が親しめる施設にレガシーとしてなればいいかなと思っているところです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"資料について１点お伺いしたいのですが、「共通事項・その他（諸室の活用）」ということで書かれておりますけれども、もう少し具体的な説明などがあれば伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そういったいろいろなスポーツを楽しむといいますか、体験するイベントも考えられると思います。そういったことを複合的に楽しむようなイベント等を開くことが可能ではないかというふうに提言書といいますか、その中には載っているところです。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"基本的には先ほど挙げられたサッカー、ラクロス、アメフトなどが中心として利用できていくということになるのですかね。どういった競技が利用できるのかというところで、ほかにあれば伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そのたびに競技をされる方が線をマーキングしてピッチをつくるということをしていたように記憶しております。具体的にはその３種目はよく挙がっているところなのですが、子ども向けの体を動かすようなものなどにも使われるかなというふうに思っております。","id":"exchange-016"},{"speaker":"のだて委員","kind":"確認","question":"詳しくはわからないのですが、アメフトができるということだと、今子どもたちの間で、この間にワールドカップがあったので、ラグビーが注目を集めていると思うのですが、そこの確認をさせてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"練習程度といったらいいのでしょうか、子どもの体験ですとか、子どものラグビー教室でしたら可能かと思います。サッカーもそうなのですが、ロングパイルのほうが適切な感じがするので、本格的な公式戦を開くのはちょっと厳しいかなというふうに認識しております。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"パラアリーナの存続について、現在の状況を伺えればと思います。財団との交渉ですとか、そういったことをやられているのか伺います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"用途地域で博物館という決まりがございまして、なかなかその後は難しいというふうに依然として聞いております。今のところはやはり東京２０２０大会が終わった後はなくなるというふうな方向で聞いております。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"期間限定で、あるいは財団と交渉して区としても存続に向けて働きかけなどを行っていくというお考えなどがあるのか伺いたいと思います。あわせて、今回この大会を機に品川区においてスポーツ施設の整備をしていくお考えというのは、あるのかどうかというところも伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"用途変更の可能性ですが、こちらは東京都の管轄なのでちょっと私のほうでお答えするのはなかなか難しいところです。スポーツ推進課のほうでこれからスポーツ推進計画を立てていく予定になっておりますので、そこで総合的に判断していくことになろうかと考えています。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした要望が実際に出ている箇所について、早急に整備を進めていただきたいというふうに思うのですが、見通しを伺えればと思います。区内でのバリアフリーについて、どこまで進んでいるかというところも伺えればと思います。","respondent":"柏原企画調整課長","answer":"大分進んできているというところはあるのですが、まだお声が出ている部分であったりとか、それ以外のエリアというのもあります。それからあとどうしても区だけでは進められない部分、事業体がありますので、こういった機会を捉えながら進めていければという考え方です。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり、有形レガシーとして残していくべきものだと思うのですけれども、いかがでしょうかということです。どういった支援があるのかというところで、あるいは聴覚障害の方ですと手話とか、どういった観戦方法があるのかというところで伺いたいと思います。","respondent":"柏原企画調整課長、辻オリンピック・パラリンピック準備課長","answer":"こういったところをご紹介しながらその整備を進めていただきたいということで、これは都市計画の部門で積極的に進めております。引き続きこういった機会を捉えて積極的に進めていただきたいということで… ボランティアの中で、そういったことができる方も養成しているということは聞いております。まだまだそれが障害を持っている方には、そういったところは私どもでも情報収集しながら漏れのないように提供していけたらいいかなと思います。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"引き続きこの大会に向けて、最寄り駅ぐらいはぜひつけてほしいということで、事業者のほうにも強く働きかけをしていただきたいというふうに思います。最後にもしご答弁があれば伺えればと思います。","respondent":"柏原企画調整課長","answer":"お金のかかることですので、ちょっとそこはここで明確に言えませんけれども、区としては積極的に働きかけをしていきたいと考えています。","id":"exchange-022"},{"speaker":"新妻委員","kind":"質問・要望","question":"振興拠点ということで、品川区民がどのように気軽に使える場であるのかというところですね、そこのイメージをちょっと教えてほしいと求めました。そこら辺のところも教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"あれだけの広さですので、１時間で数万円かかるというふうに聞いております。例えば団体で体を動かすことをやるとか、個人でテニスのように二、三人で借りるという形ではないのかなというふうに認識しております。","id":"exchange-023"},{"speaker":"新妻委員","kind":"質問・要望","question":"健康づくりの中でもこのスポーツをしていくということは非常に大事だなと思います。協賛ですかね、そういう中での支援もぜひお考えをほしいと求めましたが、いかがか尋ねました。","respondent":"中元スポーツ推進課長","answer":"現状の場合をまずご説明申し上げますと、区が主催するマラソン大会をやる場合には、事前に優先で予約をさせていただけたりしているところがあります。今後も都の条例の中でこのホッケー競技場がその中に設置されまして…","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ東京都のほうに要望していただきたいのですが、バリアフリーについて当事者の方の視点が入っていないケースがまま見られるのですよね。その後のレガシーということも考えた視点で、その辺について今のところ、もし何か情報をつかんでいらっしゃることがあったらまず説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただ、車いす用の席等はかなり今までに比べれば広くとっているかなと、あとおトイレ等もわりと通りやすくなっているかなというような実感はあります。今後、後利用の際にもそういった当事者の方の意見というのは大切にしてほしいということは申し入れておきたいと思っています。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、一応品川区としてもその辺の確認していただきながら、今後も一緒に進めていってほしいと求めました。それは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"若林委員","kind":"確認","question":"先ほど、後利用の方向性が東京都のアドバイザリー会議の中での検討ということで、これが今後どういうふうに、どこでどのように、どんなスケジュールで最終的に固まっていくのかというのを確認させてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回ご説明させていただいたのはアドバイザリー会議での提言に近いものでございまして、計画というほどの書面になっているものではなくて。まずは東京２０２０大会の成功に向けて邁進しておりまして、その後のことはいろいろな状況を…","id":"exchange-027"},{"speaker":"若林委員","kind":"質問","question":"東京２０２０大会が終わってから本格的にもんだり、指定管理の約束事をちょっと変えないといけないねとか、そんなふうに進んでいくのかなと。１年はゆうに、それから指定管理者という主体者がかちっと決まった形でオープンにしていくというのは、そのぐらいのスケジュールなのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それが、おそらく令和２年度いっぱいはかかるのではないかなというふうに認識しております。今ある提言をもとにグランドデザインをつくっていくというような流れになるのではないかなというふうに認識しております。","id":"exchange-028"},{"speaker":"若林委員","kind":"意見","question":"親しみはあるのだけれども行けないとか、行っても公園しかないとか、どんな意識を区民は持たれているのかが何かわかればとの意見を述べました。","respondent":"中元スポーツ推進課長","answer":"やはりこちらの都の会場のほうも今まで野球場があったときには大田区も品川区も少年野球などで使われているというお話は聞いております。使われているというふうに、親しみはやはり距離的には近いですので持っていらっしゃるという感覚は課長としても持っております。","id":"exchange-029"},{"speaker":"若林委員","kind":"意見","question":"それからまだ２６号線が開通していない、これから開通してもっと利便性が上がるという交通状況の中で、なかなか行かない。これは先ほどご答弁がありましたので、多分かぶると思うので、そんなことをちょっと考えましたということで意見に留めますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"そうした関係で、国際交流とニュージーランドは強豪国ですから、国際標準の大会をぜひこの品川区の大井ホッケー競技場でやっていくと。それについては、そうした国際試合の誘致ということについてどのようにお考えになっているのかということを説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"始めた子が多いということで、そこはある程度の人数がそろって試合ができるぐらいになったら、そういった交流も楽しいかなと思います。そういった大会に来た人もまた品川区内で観光していただくとかいうことで、にぎわいの一つにできたらいいかなと思います。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"さらに品川区のにぎわいづくり、地域の活性化というふうにつなげていっていただけたらいいのかなと考えております。にぎわいづくりというふうに進めていっていただきたいと考えておりますが、その点、いかがお考えか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大井ふ頭中央海浜公園は品川区にある施設の中でもかなり大きくて、非常にいろいろなことが体験できるところと私は認識しております。そのあたりは東京都と連携しながら、さまざまな遊び方、これからも品川区のにぎわいの一つとなれればいいかというふうに思っております。","id":"exchange-032"}]},{"id":"topic-02","title":"東京２０２０オリンピック聖火リレーランナーおよびルートの決定","agenda":"東京２０２０オリンピック聖火リレーランナーおよびルートの決定","exchanges":[{"speaker":"小芝委員","kind":"確認","question":"まさに区民の皆さんが聖火リレーに大変関心を持っているわけです。そういう中で、確認をしたいのですけれども、セレブレーションの区の提供プログラムの中身を教えてもらってもよろしいか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ステージプログラムの区提供の部分ですが、ただいま検討中です。何か区を代表するようなといいますか、皆さんが楽しめるようなイベント、プログラムの内容で１５分を過ごしたいと考えています。","id":"exchange-033"},{"speaker":"小芝委員","kind":"質問・要望","question":"要望とします。一応ご意見をお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただ、こちらは１５分しかないので、出ていただく団体にも限りはあるかなと思います。私どもも伝わるようにご案内してまいりますが、ぜひアンテナを立てて手を挙げていただきたいと思っていますので、よろしくお願いします。","id":"exchange-034"},{"speaker":"筒井委員","kind":"確認","question":"聖火ランナーについて確認なのですけれども、品川区がこの方がいいのではないのかというご希望を出された方は結局決定したのですか。それで、いつのタイミングでお名前を公表されるのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その方が大田区を走るのか、品川区を走るのか、江東区を走るのかというのは今のところはわかっておりません。今のところは、私どもが要望した方が最終的に決まったかどうかということは、連絡がないところです。","id":"exchange-035"},{"speaker":"つる委員","kind":"質問","question":"地元警察にもあると思うのですけれども、その辺の安全対策とかボランティアの、沿道でまずそもそも観戦していいのですかということですね。今年の１月、正月の駅伝ではないのですが、どのレベルまでそういう観戦が聖火リレーについては自由にできるのか説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"箱根駅伝でもいたと思うのですけれども、そういうボランティア的な方は区が担うというふうな仕切りに一応なっております。暑い時期なので、暑さ対策は各自お水を持ってきていただいて、応援をしていただけたらなと考えています。","id":"exchange-036"},{"speaker":"つる委員","kind":"質問・要望","question":"１９６４年のときは１０月８日で時期も違うのですけれども、写真を見るとたぶん雨が降っていたのですかね。ここはセレブレーションのほうで待っているのかどうかわかりませんけれども、そういうあたりというのはどういうものがあるのか説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"３キャラクターもルート上はちょっと難しいかなというふうに今のところ思っております。そうは言っても品川区も少しＰＲしながら何かうまくできたらなと思いますが、安全を考えながらみんなが楽しめるようなリレーにしたいと考えています。","id":"exchange-037"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう中で、そんなところでけちがつかないような万全な体制というのでしょうか、区としても未然に防ぐというのでしょうか。もし何かあったらお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"きちんと前もってそういったことをアナウンスしながら、暑さ対策という意味では区もいろいろ準備をいたします。それだけではなくて、地域の方も一緒にご協力いただきながら暑さ対策等も考えて盛り上げていきたいと考えています。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"今つる委員からご質問あったので、ちょっと関連するので一緒に伺いたいのですが、あれは規制があるのは片側だけですよね。だから、どれくらいのときにそれが発表になるのかとか、そういうことだけでもなるべく早く教えていただけるようにお願いしてほしいのです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"東京都と早くそこの役割分担を決めて、早く皆様にお知らせをしたいと思っていますので、決まり次第またご連絡は差し上げたいと考えています。そういったことを協議して決めておりますので、またそれはご案内できるようになったらお知らせさせていただきたいと思います。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"ではとりあえず品川区のオリンピック・パラリンピック準備課に問い合わせてくださいというような感じでよろしいのでしょうか。３月までに事業計画を立てなければいけないというのが、結構それは気にされている方が多いと思うのですが、そういうことでよろしいか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私どものほうにご連絡いただきまして、お答えできるところはしますし、だめなところはまた調べたり等で何かレスポンスはします。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312568?Template=document&Id=6568#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":31907,"voices":99}},{"id":"r02-20200123-10","meetingId":"r02-cm01","date":"2020年1月23日","dateIso":"2020-01-23","committee":"議会運営委員会","time":"午後 １時００分～午後 １時５５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"会派変更届","agenda":"会派変更届","exchanges":[{"speaker":"大沢副委員長","kind":"意見","question":"確かに９名から８名に変わったということで、このような５月１４日の各派協議会でお願いした形で、以降の運営をお願いしたい。これはお願いでありますが、お願いを今発言させていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"円滑な運営ということで、今、大沢副委員長がおっしゃられたような形がいいのではないかと。第２会派である自民党の石田秀男委員長がやられていますけれども、そのままという形ですんなりと行くのが円滑ではないかと私どもは考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私ども自民党として、第２会派を務めさせていただいている中で、大沢副委員長からお話をいただきました。あくつ委員がおっしゃったとおり、５月のときにさかのぼって進めてほしいと求めましたので、その話を受けさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"意見","question":"今まで９名だった会派が８名になって、同数になる場合は、今まで多かったほうを第１会派とすると。その原則の考えは維持すべきではないかと思いますので、自・無が第１会派となり、自民が第２会派となるという原則がよろしいのではないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"やはり同等数ということで、双方で話し合いで済むならば、私は双方の考え方を尊重したいと思います。１月に入っている、ここでまたどうのこうの、双方のご意見を尊重したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"大沢副委員長","kind":"意見","question":"現状の、自民党を第１会派にしていただいてというお願いを再度すると同時に、これはご理解をしていただいたものとして御礼を申し上げたいと思います。よろしく取り計らいをお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"中塚委員","kind":"確認","question":"従来の原則を変えるものではないという点を確認したいのと、当事者同士が話し合いがついているもとでお願いをされているというわけですから、やはり改めて確認をしたいと思います。","respondent":"米田区議会事務局長","answer":"同数になったときの取り扱いですが、特に明文化されているものはございません。ただ、それまで多かった会派のほうが先の会派になるというのが前例としてあったということについては、この場で確認をさせていただければと思います。","id":"exchange-007"}]},{"id":"topic-02","title":"本会議最終日に付託する請願・陳情","agenda":"本会議最終日に付託する請願・陳情","exchanges":[{"speaker":"鈴木（真）委員","kind":"提案","question":"議会・委員会運営に関する申し合わせ確認事項の規定も見せてもらいましたが、締め切り日と確かに合わなくなってくるというのが日程的にわかりました。これは今お話のあった提案に合わせてやっていっていいと思うのですが、当然…","respondent":"米田区議会事務局長","answer":"最終日の６日前等々ということで、あともう１区、前日の正午までという区が１区あります。こちら、その区の事情に応じて定められているものだろうと考えています。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"私も質問しようと思ったのですが、その日にちを１日前倒しにするということは、運用上の中でそういったことも……。〔「不利益になるのか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"いや、不利益になるのではないですか。１日減らすということは、それだけ出せる日がやはり減るということですから、今回の変更は妥当ではないかという考えです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"いついつからこのようになりますという話で、数カ月単位で私は柔軟な対応、受け付けるということも加味してやるべきではないかと。どこで決めたのですか、この議運の中で柔軟な対応をするような、そういう期日を設けるのも私は大事なことではないかと思います。","respondent":"石田（秀）委員長、米田区議会事務局長","answer":"局長、もう一回特別委員会等への付託の話をして、できないとずっと宙ぶらりんになるということをもう一回説明してください。今の特別委員会等への付託のことをもう一回きちんと説明してください。 今の現行の対応、仮に前日のぎりぎりにご提出があった場合、その付託のために再度議会運営委員会を開くということも一つ可能性として出てきてしまう。先ほど来ありますように、この規定の変更がないと…","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問","question":"１日減るということは、陳情権の制限になることには変わりありませんのでという意味で、先ほど申し上げました。ですから、おっしゃることはよくわかりますので、妥当だという結論に達したということを申し上げた次第です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"どのような様子になるか、それは見てみないとわからないのですが、こういうことは例としてあったのですか。すみません、それだけ。","respondent":"米田区議会事務局長","answer":"現状といたしまして、議会運営委員会に間に合わずということはないですが、現状の規定ですと、そのおそれがあると。","id":"exchange-013"},{"speaker":"中塚委員","kind":"提案","question":"その上で、皆さんに提案なのですけれども、議会運営委員会の前日という部分ですが、前日正午とするのが合理的ではないのかと思ったのです。前日３時なのかは、皆さん、そういうのというのはいかがなものか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この日だけ１２時というと、あえて昼とせずに、前日で締め切っていいかと思います。事務局としてそのように対応してもらったらどうかと思うのですけれどもとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"提案","question":"さまざま思うと、私の提案は、最終本会議に限った話なのです。冒頭の本会議の規定は４日前ということで、それは変更する提案は全くなくて、皆さんの合意の中で進んでいけたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"須貝委員","kind":"意見","question":"私も、鈴木真澄委員がおっしゃったとおり、区民の立場として見た場合どうなのだということを考えると、夕刻、定時までは受け付けるという形のほうが、区民によりわかりやすいのではないかと思いますので、当面そういう形でやられたほうがいいのではないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味では、このルールを確認した上でも。要望を述べておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"趣旨としては理解しているので、反対と言うつもりはないです。ただ、その修正をご理解いただけたらということで、態度表明をさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"認知症サポーター養成講座ということで、区議会としてやろうというご提案で、よい取り組みだと思っているのですけれども、日程はいつぐらい……との意見を述べました。","respondent":"渡辺議長","answer":"１定を閉じる前、前後も含めて予算特別委員会の総括が終わった後でどこか設定しようという感じです。日程は限られるとは思いますが。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5342#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":17005,"voices":85}},{"id":"r02-20200218-10","meetingId":"r02-cm02","date":"2020年2月18日","dateIso":"2020-02-18","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"および(2)の２件を一括して議題に供します。 本件","agenda":"および(2)の２件を一括して議題に供します。 本件","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"前に説明を受けたかもしれないのですが、３日目、２月２１日の質問者で、藤原議員、芹澤議員、くにば議員とあるのですが、本来今まで午前中に３人一緒にやるというふうに運用されていたと思うのですが、今回は何か理由があって午前中２人ということにされたのか尋ねました。","respondent":"米田区議会事務局長","answer":"本来そのような形で３人ということなのですが、全体な質問者数等と後の議事日程の流れを見て、このような形で組ませていただいているものです。","id":"exchange-001"}]},{"id":"topic-02","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"議員数３１名中３０名が出席、最初に一般質問が３名行われました。先ほど今度区議会としても第２５号議案でしたか、説明もあると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のご報告で、ご自身も賛成されたということでありますが、ぜひ反対すべきだったと思います。１点伺いたいのですけれども、一般質問でも発言をしていただきたいと思っているのですが、その点だけお考えをお伺いできたらと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"日程は決まっていますので、その中で通告をしまして、それで今回３名ということ。最終的に私が質問しなかったのは、この現状やこれからの動きの中で賛成すべきと考えたからということであります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"ありがとうございました。いずれにしても区民生活が厳しくなっている中、保険料は引き下げるべきだと思いますので、改めて意見だけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"中塚委員","kind":"意見","question":"１点だけ、議会費当初予算なのですけれども、職員給与費が金額としても大きく減っている点をもう少しご説明いただけたらと思います。思いとしては、やはり事務局はとても大事な存在だと私は思っておりますので、どういう状況なのかご説明いただけたらと思いますとの意見を述べました。","respondent":"米田区議会事務局長","answer":"なかなか詳細につきましてはそこまでは見込めないということで、その１０月１日の現員現給の中で、その辺の縮減の部分もあろうかと思います。いずれにしましても、職員の基本的な給与・手当等については、実績に基づいてしっかり計上しているというつもりです。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど若干の例示がありましたけれども、もう少し詳しく教えていただければ。要するに我々の分も含むのか、職員の分も含むのか、その点も教えてほしいと求めました。","respondent":"米田区議会事務局長","answer":"地震等災害対策本部設置要綱等もありますので、議員の方々が災害時に区議会の中に詰めるというようなことも想定されるものです。議員の分、それからそれを支援する事務局の分ということで、新規に計上を認めてもらっているものです。","id":"exchange-007"},{"speaker":"渡部委員","kind":"提案","question":"１点よろしいでしょうか。もし議長、今日ちょうど議運だったものですからお話しさせていただければと思い、ご提案といいましょうか発言させていただきましたのでとの意見を述べました。","respondent":"渡辺議長","answer":"今のご発言のとおり、いただいた意見も踏まえて、最新の状況と、例えば行政機関あるいは他区の状況とか、まず情報収集に努めてまいりたいと思います。そして、共通な取組の必要性が生じた場合、それぞれの会議体の責任者と相談するということを改めて進めていきたいと思います。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"議長も今いらっしゃるので、ちょっとお話をしたいと思うのですが、どうでしょうか。もし今日ご意見を聞かせていただければ、皆様もありがたいと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"気持ちはわかるのですけれども、区として今できるだけの対応としているのではないかと私は判断しています。さらにここで議会の立場で一体何を要望するのか、何かやってくださいと要望するというのは非常に話としておかしな話で、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"中塚委員","kind":"意見","question":"どう対応していいのかというところを見極めることが大事だと思うので、日々刻々と変わっているので、まずは情報共有が大前提かなと思いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"須貝委員","kind":"提案","question":"品川区はホームページを見ても、やはり我々からもっと本来これは区民全体にかかわる、乳児から高齢者までかなり影響が大きい問題だと私は思います。そういうところに対して早急な対応策を明示してくれということを言うべきではないかと私は思いまして、今…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"意見","question":"しかし、なかなかこういう問題に対しての統一的な見解を素早く出さないとこれは意味のない話なのですが、議長にお任せしたいと思います。それしかちょっと言いようがないのでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5344#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":12369,"voices":49}},{"id":"r02-20200221-3","meetingId":"r02-c-budget","date":"2020年2月21日","dateIso":"2020-02-21","committee":"予算特別委員会","time":"午後 ２時０５分～午後 ２時１２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"新妻副委員長","kind":"意見","question":"鈴木真澄委員長のもと、令和２年度のこの予算が滞りなく審議されますように取り組んでまいります。どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/273075?Template=document&Id=1106#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1987,"voices":17}},{"id":"r02-20200221-10","meetingId":"r02-cm02","date":"2020年2月21日","dateIso":"2020-02-21","committee":"議会運営委員会","time":"午前 ９時００分～午前 ９時０５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"いろいろ延期やさまざま手を打っている中で、少なくとも議場に入る前や委員会室に入る前に手の消毒やそういうものを置くなど、そういったものというのは検討いただけないか尋ねました。","respondent":"米田区議会事務局長","answer":"今お話のありましたもの、区の職員の対応の例に準じて、ご要請のありましたものについては、極力手配をさせていただきつつ、また必要な情報提供等については行わせていただければと思います。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5346#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1874,"voices":14}},{"id":"r02-20200225-6","meetingId":"r02-cm02","date":"2020年2月25日","dateIso":"2020-02-25","committee":"区民委員会","time":"午前１０時００分～午前１１時４７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"令和２年陳情第１号 品川区立中小企業センター警備業務の改善に関する陳情","agenda":"令和２年陳情第１号 品川区立中小企業センター警備業務の改善に関する陳情","exchanges":[{"speaker":"くにば委員","kind":"提案","question":"細かくこの施設でどのような業務を行いますということを全てその契約に盛り込んでやっているのかどうかという部分は１つ伺いたいのです。実際にその働いている中で提案をしていたのだと思うのですけれども、これはこのようにしたほうがいいということで判断なさったのですからとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"湯澤委員","kind":"質問","question":"陳情者の方、先ほどのご説明だと、２１時３０分に貸し出しが終わってということですよね。５年間防犯上の事故はなかったということで、あと2)のところで、区のほうでは把握をされているのかという２点についてお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"それはするのが当たり前ですという考え方もあれば、違ういろいろな効率的な実施の方法でありますとか、区としては申し上げる中身ではありません。ある方はやはり警備業務というのは多少時間の余裕を持って対応しなければいけないというお考えであれば…","id":"exchange-002"},{"speaker":"湯澤委員","kind":"意見","question":"それに関してはやはり夜の２２時から翌７時までは、もしあれでしたら取り込んでいただいて、今後も事故がないようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"もう一人が７時から１４時と１４時から２２時という中で、７時から２２時というと、要は１５時間ですよね。その１人の方の時間帯がすごく長いかなと単純に感じたのですけれども、働き方の規則の中ではどういったものなのかと教えてもらいたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"朝から夜までの時間帯で、どうしても限られた人数で効率的に回していくですので、通しの方も途中で、当然労働基準法に定める範囲の休憩、休息のほうは入れさせていただいているというふうに警備会社のほうからは伺っております。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、この方は平成３１年３月３１日までいらっしゃったわけですね。そこを確認したいです。","respondent":"山崎商業・ものづくり課長","answer":"警備業務の区としての委託先につきましては、令和元年度、今年度から新しい警備会社に切り替わっております。それから平成３０年度、昨年度につきましては、警備員７名体制のうち１名のみ替わられて、６名が新会社で雇用を継続されているというような状況です。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"いろいろ業務がこうだとか、遅刻があるというようなことを言っているのか、これいつの時期のことを言っているんですか。それともずっと連続しているのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"４つ、５つというトータルの質問数からすると、そのようなところです。","id":"exchange-006"},{"speaker":"藤原委員","kind":"確認","question":"これ事実関係はどうなっているのだと確認をしてくださっているから、そのような答弁をしてくださっていると私は思うのです。やはりこの辺だけの確認というのが、私は一番この2)、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"それで、今の警備の方々に７時までに来ることになっていますねと。それは個々に備えて３０分前だとか、５分前だとかというような、通常の私どもの業務と同様ですというようなことでお話をさせていただいたです。","id":"exchange-007"},{"speaker":"藤原委員","kind":"確認","question":"では確認します。2)ですけれども、現場責任者が朝の遅刻常習者なのに放置されてきたという文章が出ていますけれども、これは放置されていないということですね。","respondent":"山崎商業・ものづくり課長","answer":"そうした事実はなしということで確認をしています。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"１点、今の答弁等からバックしてしまうのですけれども、戻ってしまいますが、そもそも平成３１年３月３１日に、もとの警備会社から違う会社に変えた理由は教えていただけますか。","respondent":"山崎商業・ものづくり課長","answer":"これは区の委託内容に変更がなく、３年間を限度として、同一受託者と契約することが可としますということになっています。そこの従事されている方が新会社のほうに雇用継続を基本的にはしていただきましたけれども、その時点でおやめになられたというようなことです。","id":"exchange-009"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"1)番に書かれているような業務改善を求めるいろいろな案というものは、あのような改善というものはされていたのでしょうか。そこを確認させてください。","respondent":"山崎商業・ものづくり課長","answer":"それぞれの７名の警備員の方々のチームがありまして、効果的に実施していくためのご意見などは、そのリーダーの方などに上げられてという流れでやりとりをされていたというようには伺っています。","id":"exchange-010"},{"speaker":"こんの副委員長","kind":"意見","question":"ですので、その点をぜひまた対応をできる範囲でお願いしたいなと考えていますので、一定の対応はされてきたのかなというふうに判断をいたします。意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"湯澤委員","kind":"質問・要望","question":"理事者からも陳情内容については改善が図られたという説明があったので、不採択でお願いしたいと思います。十分に耳を傾けていただいて、警備会社と適切な業務委託をして、さらなる防犯に努めていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"松澤委員","kind":"意見","question":"令和元年３月３１日以降も継続して皆さんしっかりとやられているというお話が出ていますので、問題はないのではないかと思います。副委員長よりお話がありましたけれども、やはり区と区民の信頼という形で、しっかり窓口対応していただけたらと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"こんの副委員長","kind":"意見","question":"結論としては不採択ということでお願いしたいと思います。今後もこうした改善をできる限り進めていただきながら、これからも防犯、安全に万全を期してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"おくの委員","kind":"意見","question":"改善を図ることや、誠実に対応しというところの趣旨が非常に理解できるというところが、この中の趣旨で私は明らかになったと思います。細かいところまでは縛れない点なり、十分に行き届かない点があると思うので、趣旨採択ということでいきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。行政としては受けとめるという姿勢は真摯に受けとめていただいて、区民の安心・安全のためにこれからも尽力していただきたいと願っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"くにば委員","kind":"質問","question":"現場責任者の方ですから、どういった形でやれば、それこそ１時間前に来ないと準備がきちんとできない方もいらっしゃると。質問を聞いて、これは５回、１０回とこの方の話を聞いていたら切りがないです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"}]},{"id":"topic-02","title":"令和２年陳情第１４号 こみぷら八潮にシャワーブースと入浴施設の整備を求める陳情","agenda":"令和２年陳情第１４号 こみぷら八潮にシャワーブースと入浴施設の整備を求める陳情","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"だから、少しずつ設けていっておかしくはないのではないでしょうか。ですから、やはり公衆浴場が１つぐらいはあって、この陳情をきっかけに真面目に考えてあげてもいいのではないかと私は非常に素朴に思いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"湯澤委員","kind":"質問・要望","question":"何点かお聞きしたいのですけれども、区内ではそういった事例というものがどのぐらい起きているのか、年間で。苦労というのは当時どのような対応をされていて、どのような苦労があったのかということがわかれば、教えてほしいと求めました。","respondent":"古巻文化観光課長","answer":"３つほど質問いただいていますけれども、お答えができるものとできないものがありますが、基本的にはないというふうに認識をしております。銭湯、少しご苦労なさったのかなというようには認識をしておりますが…","id":"exchange-019"},{"speaker":"湯澤委員","kind":"意見","question":"入浴中に死亡してしまうというところで、こみぷら八潮内に公衆浴場を整備するのであれば、もう少ししっかりとした議論が必要なのかなと思います。ただ、だったらうちもどうなどという話にも発展していくのかなどというところから…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問・要望","question":"これは要望というのですか、思いというのですか、銭湯をつくってほしいなという要望です。要望というか、意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"おくの委員","kind":"意見","question":"わざわざ陳情まで出してくださったわけですし、１個ぐらいは、あれだけの規模の人口のあるところに１個ぐらいはつくってもいいのではないかと。１つのスポーツ施設とか、それだけではなく、施設のもう一つの新しい形態だという形でつくれるのではないかと私は思いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"こんの副委員長","kind":"確認","question":"いろいろな方々がスポーツを楽しまれている学校にはシャワーがついておりましたでしょうかというところをまず確認、こみぷらも、そこを改めて確認と。ここもスポーツができるけれども、たしかシャワーなどというものはなかったと思いますが、その辺確認をまずさせてください。","respondent":"古巻文化観光課長","answer":"学校なのですけれども、これはもともとこみゅにてぃぷらざ八潮は学校だったので、同じ設備というようにお考えいただいて差し支えないと思います。ゆうゆうプラザになれば、そういった形ではご利用いただけているケースもあるかなと考えています。","id":"exchange-023"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"要望は理解はできると思いますけれども、では区全体でスポーツ施設も、全体的な課題としても考えていかなければいけないのかなと思います。１つのお部屋がスポーツ施設になっている、現時点でどのようにお考えなのか、その辺をちょっと確認させてほしいと求めました。","respondent":"古巻文化観光課長","answer":"そのようなスポーツ施設についてはシャワーブース等はあるのかなというふうには認識しておりますけれども、そういった使い方をされている部屋もあり。そういったものについては設置をしていないということが現状の区の施設整備の考え方になりますので…","id":"exchange-024"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"地域全体として考えていくというところは、もっと地域の、そうした考えている方たちのご意見も伺いながらということが必要かなと思います。単純にここにないからポンとここへつくってという要望だけだと、なかなか全体のバランスから見ても、それは難しいのかなというようには考えられます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問・要望","question":"やはり八潮の中に１カ所はどうしても、こみゅにてぃぷらざ八潮というのは八潮の中でも大事な施設ですから、ここの中に１つシャワーであるとか。今回こちらの課の中ではご対応なさっているというか、実際に試算なさっているのか、その詳細の部分等ももう１点伺いたいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問","question":"そもそもつくれるかどうかということを検討しないとわからないという部分があるのでしたら、区のほうが、話が進みやすいのかなと思う部分はあります。果たしてそんなに難しいのかどうかということは私はわからない部分なのですが、そのような部分がないのか、もう１回伺いたいです。","respondent":"古巻文化観光課長","answer":"現状では文化観光課からというようなことは考えておりませんし、そういったことで八潮地区、そういった議論が出てくるのかなと思っています。さまざまな意見をいただきながら、全体を区の企画部門でしっかり議論していくところなのかなと思います。","id":"exchange-027"},{"speaker":"湯澤委員","kind":"質問・要望","question":"理事者からのご説明をもとに議論をしたとおり、本件は不採択という考えになりました。先ほど課長からご説明もありましたように、浴室の整備に対して八潮地区だけにかかわらず、しっかりとしたバランスで対応してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"いろいろ皆さんから質問、ここに早急にシャワーブースが必要かと考えると、これはまだ要らない話ではないかと思います。しかし、いずれは大きな観点でこのような入浴施設なども考えていただければと願っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"おくの委員","kind":"質問","question":"結論を出すで、採択でお願いします。理由としては、シャワーブースなどもつけるような方向で、もう一度見直すぐらいの観点で考えていったほうがいいのではないかというようなことです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"結論を出すで、不採択で、理由はこの委員会の質問、答弁の結果です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"くにば委員","kind":"意見","question":"結論を出すで、採択でお願いします。やはり八潮地区の特殊性ということもあるのですが、どうしても必要であろうかなという地域に、今回は採択という形でお願いしたいですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]},{"id":"topic-03","title":"専決処分の報告について（報告第２号）","agenda":"専決処分の報告について（報告第２号）","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"先ほどのところで質問すればよかったのですけれども、例えば報告第１号のほうは、運転者の住所も名前も出ているではないですか。これどうしてかということを教えていただきたいのと、今の報告第２号なのですけれども、どうしてなのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"当たり前かもしれないけれども、これはシュレッダーにかけるなどして、管理を大切にしなければいけないということですよね。改めてお伺いします。","respondent":"川島地域活動課長","answer":"今、委員おっしゃるとおり、議員の皆様には審議していただくためにこのような形で個人情報も載せたものをお出ししていますが、取り扱いについては厳重にしていただきたいです。","id":"exchange-034"},{"speaker":"湯澤委員","kind":"質問","question":"かもめ橋公衆便所のほうの和解の件なのですけれども、こちらのほうは今、また同じようなことが起きないようにということで、どのような対策をされたかということを教えていただけますか。","respondent":"川島地域活動課長","answer":"こちらのほう、手すりの設置、それからスロープの交換工事等も終わっておりまして、現在ちょうど、今日、明日ぐらいで便器の洋式化工事もされているところというふうに聞いてあります。","id":"exchange-035"}]},{"id":"topic-04","title":"今定例会の一般質問にかかわる所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","agenda":"今定例会の一般質問にかかわる所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"そのあたりはもう３月３１日までのイベントは全て中止にするという表明を行っておりますので、その手前の段階で３月３１日までスポーツだとか、それぞれで対象になりそうな３月末までのイベントを説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"くにば委員","kind":"質問","question":"委員長もおっしゃっていたとおり、イベントが中止かどうかということは、もちろん区の情報公開のタイミングを待たなければ、中止するかどうか言えないと思うので、区としての対応を聞いてから、また質問等あれば、そのタイミングでの委員会でまた伺います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2858#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":33016,"voices":89}},{"id":"r02-20200225-7","meetingId":"r02-cm02","date":"2020年2月25日","dateIso":"2020-02-25","committee":"厚生委員会","time":"午前１０時００分～午後 ５時３４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を134件整理しています。","topics":[{"id":"topic-01","title":"第１６号議案、品川区社会福祉基金条例の一部を改正する条例","agenda":"第１６号議案、品川区社会福祉基金条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"具体的にどんな使い方をしてほしいのかというご希望などは聞かれているのかということを１点お聞かせほしいと求めました。この間、これがどういうふうに決められていくのかということについても２点目にお聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"窓口にお見えになったときに、福祉の関係で３,０００万円というお金を使ってもらいたいということで、まずはお話をいただいたところです。こういったものに一番多く使われていますということで、こういった基金の使われ方についてもご説明をさせていただいたところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"何というのですか、その確認した遺族ではない遺族ということになるかなというふうな思いがしたのですけれども、使われるときは必ず遺族の代表の方に確認をされてから使われているということで確認させていただいていいか尋ねました。","respondent":"大串福祉計画課長","answer":"そうなったときに、全てのご親族に確認できるかというと、これはなかなか難しいです。やはり１４億円、こちらのほうとしては、すぐに使わせていただいたという経緯です。","id":"exchange-002"},{"speaker":"あべ委員","kind":"意見","question":"その意思が見える形に、総合支援施設はあるのかもしれないのですが、ちょっと見た記憶がないのですね。使う方にも、ある程度寄附文化ということにも貢献できると思うのですけれども、そうした表示みたいなものはどうされましたかとの意見を述べました。","respondent":"大串福祉計画課長","answer":"総合支援施設も表示はさせていただいています。これも上大崎の例をもとに申し上げますと、やはり遺言執行人の方という方に来ていただいたです。","id":"exchange-003"}]},{"id":"topic-02","title":"第１７号議案、品川区立在宅サービスセンター条例の一部を改正する条例","agenda":"第１７号議案、品川区立在宅サービスセンター条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成３０年度に条例が審査されたときがあるのですけれども、今回初めて共生型サービスということで導入されるということでいいのでしょうか。それから、平成３０年度からそういうふうに条例でもされたものではありますけれども、どこで検討されたのかということについても説明を求めました。","respondent":"松山障害者福祉課長","answer":"ほかの在宅サービスセンターが実施する際には、またこのように別表に対して追記するということになろうかと考えています。４点目につきましては、このような検討の場というのは、ご提案があって初めて障害者福祉課、あと高齢者福祉課と一緒に検討してきたものです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"両方経験している方というのはおおよそ品川総合福祉センターの中ではどれぐらいの方が経験されているのか、わかったら教えてほしいと求めました。こういうふうなことがあったら４月から受け入れていくということになると思うのですが、そこら辺のところも教えてほしいと求めました。","respondent":"寺嶋高齢者福祉課長、松山障害者福祉課長","answer":"そのまま６５歳になっても同じ事業所のサービスが利用できるというところが一つの狙いとしてこのサービスが始まったというふうに認識しています。そこを切れ目のない、まさに共生型という形でこの事業を位置づけていると… そのときのサービスセンターの全体の様子にもかかわってくるかなと考えていますが、そういった方を想定しているというふうに聞いております。受け入れ準備につきましては…","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、６５歳前からこの共生型サービスということであれば、事業所としては介護と障害者と両方にそれぞれ請求するという形になるのでしょうか。今までと、ですから、そういう形で受けられるということになるのでしょうかというのを説明を求めました。","respondent":"松山障害者福祉課長","answer":"６５歳以上はどうなるかというところにつきましては、どういうふうに課題を解決していくかということになろうかと考えています。そういった面でも東京都との協議が必要になってあります。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっとそこら辺は課題なのかなと思うのですが、そこら辺の仕組みを教えてほしいと求めました。障害の方も生活介護の方もドア・トゥー・ドアという形で送迎が受けられるようになるのかどうか、その点についても説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"これも選択制になっておりまして、ご本人が送迎を希望する場合は送迎、希望しない場合は自分で実際にいらっしゃっているという方もおります。ご本人が高齢か高齢でないか、希望されるかどうか、このあたりで決めていくものです。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと今のやりとりの中でわからなかったのですが、利用料金は６５歳以上になっても変わらないということですか、変わるということですか。ごめんなさい、報酬のほうは何か共生型になって利用料は変わるのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"それで６５歳以上になると、まず介護保険に移行するので、報酬は介護保険のほうの報酬になるです。ただ、介護保険に含まれていないもの等については、先ほど障害者福祉課長が言ったように個々の判断が出てくる部分があるという内容です。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"現在６５歳以下の方が利用を始められて、どういうふうにお声がけというか、どういう方が利用されるのか説明を求めました。","respondent":"松山障害者福祉課長","answer":"近々のところにつきましては、こういうサービスを実施いたしますというようなご案内はするということを聞いております。具体的にマッチングというのが可能なのかというところにつきましは、丁寧に進めていきたいと考えています。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"一、二名ということは、広がりで数名の方が使われるということなのでしょうか。それは基本的には近隣の方と、あとは例えば品川総合福祉センターあたりでどうでしょうと声をかけるようなイメージなのか尋ねました。","respondent":"松山障害者福祉課長","answer":"もちろん１日の中で一、二名ですけれども、やはり品川総合福祉センターを中心にお声がけをするような形をとってまいります。","id":"exchange-010"},{"speaker":"若林委員","kind":"質問・要望","question":"今後これをよい事業であれば品川区においてもどんどん採用等、法人においても積極的にぜひ進めていただきたいと思う事業の一つです。これの交流についてはどんな形を法人のほうで考えておられるのか、また区の考え方とかがあれば説明を求めました。","respondent":"松山障害者福祉課長、寺嶋高齢者福祉課長","answer":"具体的に、その方と相談しながら詰めていくというようなお話を聞いておりますので、一律こういったプログラムを行うということは聞いておりません。お一人の方のご意向に合わせながら進めていくというのは聞いております。 実はもう１点ございまして、認知症カフェという意味ですけれども、委員ご指摘のとおり交流をすごく重んじた制度だという構築になっております。したがいまして…","id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"次の１年のサービスをどう拡充していくか、そこは指定管理者ですかね、それ以外で評価をしっかりしていくという考え方はいかがか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"令和２年４月１日にスタートなので、まず１年間ですから、通常よりもしっかりやっていくものであろうという認識で。は最初の１カ所なので、指定管理のモニタリングの中でしっかり見ていきたいというふうに思っております。","id":"exchange-012"},{"speaker":"若林委員","kind":"意見","question":"どういう言い方、障害の所管なのか、またはまた別のということになるのか。例えば、問い合わせする場合にどちらに聞いたらいいのか、そういう点を含めて、ちょっとその考え方を説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"障害者福祉課というふうに分かれておりますので、むしろ我々のほうの連携が問われるところであるというところは重々認識しています。今回サービスの詳細をご説明させていただいているのが障害者福祉課長であるというところからおわかりいただけるように…","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都が指定するに当たり、それ以外に都が指定するに当たっての条件というものがあるのか、あったら教えていただきたいです。そういうところでは、共生型サービスを提供するに当たっての職員研修みたいなものはないのか、その点についても説明を求めました。","respondent":"松山障害者福祉課長","answer":"やはり品川区の実情というのも東京都にお話をした上で今回指定がおりたという形になっております。あるいは品川区で在宅介護支援センターに障害者の計画相談支援事業所を併設したという件も東京都にご説明を差し上げて。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"設備も整って身近なところで体制が整えられるということであれば、障害者にとってはサービスの拡大になるということだと思います。６５歳になったときに負担が増えることがないようにということもお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区と連絡調整し、客観的かつ公平な仕組みというのはどういう仕組みになっているのかというところについてお聞かせほしいと求めました。何人くらい受けられているのかということについてもお聞かせいただけたらと思います。","respondent":"寺嶋高齢者福祉課長","answer":"ちょっと今手元に資料がないので数字のほうをお答えできないのですけれども、後ほどお答えしますので、ちょっと保留させてください。申しわけございません。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この大井認知症高齢者グループホームの場合は、何人待機者がいるみたいなものが常にあると、そういうふうな状況なのでしょうか。多分１回入ってしまうと、そういうときに、誰が見ても当然だというようなことでの決まりというのは特にないということで考えていいのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"特に平成３０年度が９５％という稼働率、通常は限りなく１００％に近いもので、これ以上落ちるというふうには考えてはおりません。この黒字をどう使うかというのは経営法人の判断ではありますが、しっかりとした処遇についての対応もできているというふうに我々は認識しています。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"例えば家賃が多分６万５,０００円で光熱費が２万円という形になっているのかなと思うのですが、そこら辺のところは、区としてはいかがでしょうか。それはまた、ここに総括シートがなければ確認していただいて、ちょっとお願いできたらと思います。","respondent":"寺嶋高齢者福祉課長","answer":"１点、待機者の把握につきましては、数字で待機者何人という形では実際には把握ができていません。大変失礼いたしました。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"特に第２３号のグループホームについては既に４年間の実績があって、簡易な形で、選定委員会で選定というのもそうだろうなというふうに思います。このメンバーに関する、この選定委員を誰にするかということの根拠となる規定というのは品川区の場合どういう形になっているのか尋ねました。","respondent":"大串福祉計画課長","answer":"選定委員の人選といいますか、こちらにつきましては要綱で、福祉部長を委員長としてといったところで、委員についても要綱に決め方が規定されております。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"あるいはそれぞれの選定事業にかかわる企業の団体、それからむしろ職員がメインだけれども、そこに公募委員や学識経験者が一部入っている。いつまでも職員だけの選定委員会でいいのかというのは、これは客観的に見ても疑問があるのですけれども、ここについてはどのようにお考えか尋ねました。","respondent":"大串福祉計画課長","answer":"あるいは公平性といったところで難しいところもあるのかなというのは、こちらのほうとしても認識をしております。その辺についても今検討しています。","id":"exchange-020"},{"speaker":"あべ委員","kind":"意見","question":"問題意識がないと言われたらもう少し突っ込もうかと思ったのですけれども、今まさに次年度に向けて見直しを図っていらっしゃるということですので大いに期待しておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２事業者を比較してなぜ福栄会が選ばれたのかがわからないから、わかるような資料と説明をしてほしいということで要望をしておいたのですけれども。点数だけでもぜひ教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"こういった形で委員会審査の中でご提出する資料のあり方についても、あわせて検討させていただければというふうに考えているところです。２事業者といった中で、先般のときにも報告させていただき、今回議決といったところで皆様方にもご審議をお願いしています。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ですから、その点はなぜ最終的な点数さえも出せないのか、ちょっとお聞かせほしいと求めました。それで、最終の合計点だけでも出せないのか、出せないのであれば、なぜ出せないのかについてお聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"外部の方の選定委員会における参画であるとか、あるいは点数の公表等といったところも含めて検討させていただければというふうに思っております。全体的なお話になるかというふうに思いますので、今回の点数についてはちょっと公表は控えさせていただきたいと考えています。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"法人概要、公募要項それから事業提案書が委員会資料として出されて、これだけ議会が決める責任があるということだと思うのですね。指定管理者の制度が始まった１５年前からずっと言い続けているのですけれども、そういう状況が出てきているというふうなことだと思うのですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回の審議の中でも最後の点数さえも公表されないということで、ちょっとそれは指摘をしておきたいと思います。今後、他区と同様に議会に判断できる資料提出を強く求めておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"あべ委員","kind":"意見","question":"賛成をいたします。ただ、次年度に向けて見直すということで、次年度の早い時期からそれが運用できるように期待していますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"}]},{"id":"topic-03","title":"第２５号議案、東京都後期高齢者医療広域連合規約の変更","agenda":"第２５号議案、東京都後期高齢者医療広域連合規約の変更","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８０万円の人は平成３０年度に４,３００円だったのが、令和元年度は８,６００円になり、令和２年度は１万３,２００円になっているのですよね。これ以上すべきではないと思うのですけれども、なぜ所得割を下げて、その点についてお聞かせほしいと求めました。","respondent":"池田国保医療年金課長","answer":"そこから(4)の厚生労働省が行いました所得係数、１.６１という推計値が出たところで、それから医療給付費の数字をもとにして算定したものです。ご説明させていただいたところではありますけれども、１００円ほどですけれども…","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だって３倍、それから１０倍、本当にすごいではないですか。そういうふうなことでの値上げになってしまっているわけですから、月１４万円の方がまた３倍になり、これは強く求めておきたいと思います。","respondent":"池田国保医療年金課長","answer":"５割軽減、２割軽減をあわせますと、およそ１６％の方が均等割の軽減の対象ということになってあります。均等割の軽減については、およそですけれども、全体の５６％、半分以上の方が軽減の対象にはなっているという状況です。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５割軽減と２割軽減のそれぞれの割合はわからないでしょうか。２.４％、３％に見えないような、その点どうか尋ねました。","respondent":"池田国保医療年金課長","answer":"これは説明のということでご理解いただければと思います。下から三つ目、マイナス７００円ということで、４５０万円の方はマイナス１,３００円ということでの例示がされているところです。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"公的年金が３５０万円、４５０万円という方というのは、それほどいらっしゃらないのではないかなと思うのですけれども、品川区で言えば、何人、何％ぐらいの方が軽減になるのかということについてお聞かせほしいと求めました。","respondent":"池田国保医療年金課長","answer":"今回の中間層の軽減ということでの数だと思いますけれども、私どものほうでは品川区内で何人の方がということまでは把握はしていないところです。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"広域連合ということで、例えば品川区の人口対比で当てはめていけば、おおよそがわかったりということがあるのではないかと思うのですよね。説明にしても、品川の区民に当てはめてどうなのか、区民の姿が見えるような形での資料づくりに努めていただきたいとお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"引き続き値下げこそすべきだというのが共産党の主張です。ただし、今回のこの保険料を決めるに当たっての議案は軽減措置としてのものですので賛成ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]},{"id":"topic-04","title":"第２７号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第２７号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０ページのところで、納付金それから賦課総額、これが品川の場合幾らなのか、それから法定外繰入というのが４％分ということでいいのか、その法定外繰入の４％分というのが１０億円ということになるのか、まずそれを教えてほしいと求めました。","respondent":"池田国保医療年金課長","answer":"こちらは、１２１億１,０００万円ほどが令和２年度の納付金額という形になっているところです。それプラス納付金のところに、健康事業のところで…。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"去年、どう変化したのか、そういう資料というのはどこかで見ればわかるものというのはあるのでしょうか。私はそういう資料も審査するに当たってきちんと出していただきたいと思うのですけれども、その点についてもお願いしたいと思います。","respondent":"池田国保医療年金課長","answer":"それにつきましては、今回ご提示できなかったことは大変申しわけないと考えています。今年２月１日現在では、令和２年度の見込みとしましては、７万１,６２５人ということを見込んでいるところです。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで言えば、聞かれたらせめて数字がぱっと出てくるような形にしておいていただきたいなと思います。そうでないと、国保の条例の審査の前提の数字だと思いますので、そこら辺のところはぜひお願いしたいと思うのですが、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"委員のお申し出につきましては、来年度の改正のときにはきちんと基礎資料として出せるように努めていきたいと思います。失礼いたしました。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０ページのところには書かれているのですけれども、保険料未収見込額というのがとりあえず４％分ということで考えていいのでしょうか。そうすると、４％分というのが法定外繰入金の１０億円ということで考えていいのでしょうかということを説明を求めました。","respondent":"池田国保医療年金課長","answer":"４％分は繰入金という形になってまいります。別なものでございまして、私どものほうでは、口座引き落としとかの口座の割合とか収納率の関係とかでの特別交付金をもらっているところです。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうのも全部含めた形でも特別交付金という形になるのでしょうか。その交付金というのは、今回は幾らということで計算されているのか、その内訳もわかったら説明を求めました。","respondent":"池田国保医療年金課長","answer":"予算計上している分については１０億３,０００万円ということでやっておりまして、今度補正ということで７億７,０００万円ということになりますけれども、当初の平成３１年度の一般会計からの繰入金は１０億３,０００万円ということでやっているところです。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっとすごく複雑でわかりにくいと思うのですけれども、では１０億３,０００万円の中身は４％の未収額としても、本来保険料は１００％であるべきところを９６％というふうなことでやった、その法定外と、それから特別交付金とか、あわさった額がその繰入金の額と考えていいのか尋ねました。","respondent":"池田国保医療年金課長","answer":"それから平成３０年度の部分につきましては、平成２９年度から３０年度にかけて広域化になりまして、あわせますと３億３,０００万円となっているところです。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"もうちょっとわかるような形での説明をお願いしたいなと思うのですけれども、保険料算定に当たっての収納率というものがあるのでしょうか。そこら辺のところが品川区としてあるのか、あるのであれば、それぞれ幾らなのかということについても説明を求めました。","respondent":"池田国保医療年金課長","answer":"こちらについては１００％収納ということでの計算をさせていただいてあります。私どもの国民健康保険のほうでやっております収納率の委員会のほうでは、現年については９５％目標ということでやらせていただいているところです。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これは平成３０年のときの資料では、６年間で７９億円を東京都が出していくということでありまして、平成３０年は１４億円出しているのですよね。７９億円まではまだまだ東京都は出せる財政力があると思うのですけれども、その点についても説明を求めました。","respondent":"池田国保医療年金課長","answer":"こちらについては保険料の急激な増加を国の支援だけでカバーしきれないところもあったということで、都の独自の財政支援ということで計画したものですが、都からの独自の財政支援のほうは出さなくてもいいだろうということで。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もっと国費を入れて、１兆円ぐらい国費を入れて値下げこそすべきだというのがずっと知事会でも出されていたと思うのですよね。そこら辺のところというのは、そういうところでは２３区としても東京都に求めるということはなかったのか尋ねました。","respondent":"池田国保医療年金課長","answer":"保険料の著しい増加にならないようにということで課長会等を通じまして申し出のほうはさせていただいているところです。こちらの都の分についても、申し出のほうはさせていただいているところです。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"東京都に区長会なり、課長会なりが、７９億円出すと言ったのだから出してくださいというふうなことを申し入れても、東京都が拒否をしたと、そういう形になっているのか尋ねました。","respondent":"池田国保医療年金課長","answer":"最終的に国から３０億円というお金が来ることで、賄えるということでご回答をいただいた上での保険料算定という形になっているところです。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は最も区民にお知らせする立場というところで、そういう姿勢ではなくて、やはり引き下げに努力をしていただきたいというふうに思います。とりあえず以上です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"世帯の頭数でかかるものですから、子どもの分をせめてなくそうということを求めてきたのですけれども、ここがすごく大幅に上がってしまっている。なぜこれだけ大幅に介護分が上がったのか、国は上げたのかを伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"１.５１％から１.９９％に上がった理由ですけれども、まずは一つとしましては、介護に必要な予算を多く使うことになったということがあります。平成３０年度から変更になっているところで、今回１.９９％という高い数字になったとご理解いただければと思います。","id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"平成３０年度の１.５１％、令和元年度も１.５１％、介護納付金分の所得割ですね。そうすると、それで、その期間が終わったから今回はこれだけ値上がったというふうに考えていいということか尋ねました。","respondent":"池田国保医療年金課長","answer":"介護保険の保険料につきましては、２０２０年本格実施ということでの保険料の仕組みができるかと思われます。その時点で私どものほうで国から提示されている金額として計算したときに、今その過渡期でございまして、上がっているです。","id":"exchange-045"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"７万３,０２２世帯ということだったのですが、それで見込みとしては７万１,６２５人ということでしたけれども、値下がる世帯もあるのですよね。ですから、４０代未満は介護保険はかからない、わかれば教えていただきたい。","respondent":"池田国保医療年金課長","answer":"令和２年度の平均見込み被保険者として、先ほど７万１,６２５人とお話をさせていただきました。介護保険の対象の方ですので、実際には賦課限度額が２万円ほど上がりますので、４万６,０００人が該当するというふうにはお答えできないところです。","id":"exchange-046"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"３億３,０００万円しか使わなかったという言い方でいいのか、８億６,０００万円ほどが使われなかったと思うのですけれども、これはなぜなのですか。３億３,０００万円しか使わないという、その法定外繰入の仕組みはなぜなのかというのを伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"こちらのほうですけれども、保険料の収納率が私どものほう、平成３０年度は９２％いってあります。医療給付費につきましては、実際に決算をやったときに繰入金が当初予算に比べますとかなり減った３億３,０００万円というふうな形になったです。","id":"exchange-047"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１１億９,１００万円積んだわけですから、それを使おうということで積んだものが使われなかったわけですから、２億円でできますよね。１０億円ほど法定外で見積もっていたと思うのですが、この使い方、考え方を伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"そういった意味で、品川区独自でこういったことをやるかということになりますと、品川区独自では今のところ一切考えていないです。それと、繰入金を減らせたというのが大きな理由ですので、今後多くのこういった繰入金を減らすというところはなかなか難しいという状況です。","id":"exchange-048"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"若い世代を応援してほしいという声でしたけれども、やはり子ども１人産むと、今回も６００円ですけれども上がりました。そして差し押さえ、この数を知りたいのですが、お願いします。","respondent":"池田国保医療年金課長","answer":"滞納率につきましては、平成３０年度末ということでの滞納世帯につきましては、１４.１４％です。ちなみに、平成２９年度末は１４.２１％というところで数字が出ているところです。","id":"exchange-049"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"厳しい差し押さえがたくさんあって、そのときと比べると本当に減っていると思うのですけれども、それでも収納率は２３区で１位の９２％ですね。考え方を変えたり、やり方を変えたり、何か変化があったのかというのを伺いたいのですが。","respondent":"池田国保医療年金課長","answer":"収納率が９２％ということは、１００人の方のうち８人が保険料をお支払いいただいていない方ということで、多くの方はお支払いいただいているです。たまたま皆さんに納付意欲を持っていただけたということで、こんな数字になっているというふうにご理解いただければと思います。","id":"exchange-050"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"本当にこの高い保険料をみんな一生懸命払われているということだと思いますが、本当にこれ以上値上がるようでは、それこそ払えない。ぜひ下げる方向で、区独自でやっていただきたいと再度要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと中期的な考え方というのを見せていただけないでしょうか。どこかで考え方を変えるところというのはあるのか尋ねました。","respondent":"池田国保医療年金課長","answer":"１人当たりの医療費が今増えているところでございまして、医療費について適正化を図るということがまず一つの目標になっているところです。そういったことで、保健料の上昇というところを少しでも押さえていきたいというふうに思っているところです。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問","question":"ジェネリックでも、保健指導でも、費用対効果としてちゃんとプラスの効果は出ているのですか。引き下げのための努力と成果というのを数字で出していかないと、やる側としてもなかなか響かないのではないかなと思うのですがいかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"今後の中身の部分で、これを今後また私ども、また都もしくは国民健康保険連合会等もあります。そういったところでどういうふうにやっていくかというのを検討していくようなことになりますし、都、もう少し長い目で見ていただければと思います。","id":"exchange-053"},{"speaker":"あべ委員","kind":"意見","question":"何をやったら、どれだけの効果があるのかということをきちんと検証しながら進めていくということが必要かなと思いますので、最後は意見で終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"西村委員","kind":"意見","question":"賛成です。区民の方にとってもなかなかわかりづらいものと思いますので、ご案内の仕方を工夫していただきながらお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"渡部委員","kind":"意見","question":"広域化して２０区が同じやり方をしている中で、高いか安いかとか、お金だという議論は、ここではなくて都でやってほしいなと思います。では７万幾らというのがどういう方といったら、下、どーんと分かれるわけですよとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"共済健保よりもどの保険料よも高いのが国保料ということで、全国知事会も一貫してこの国保料の引き下げをということで求めているものです。６市がやるというふうなことで聞いていますけれども、品川区独自にできるものですから、ぜひこういう方向でも踏み出してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"あべ委員","kind":"意見","question":"国保の仕組みというのは、確かに広域化はしましたけれども、自治体として独自の考え方が反映できないという制度ではないと考えています。やはり現実的な着地点、それから可能な負担というものはどこにあるかというのはふだんの研究課題としてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"}]},{"id":"topic-05","title":"令和２年請願第１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、令和２年陳情第１３号…","agenda":"令和２年請願第１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、令和２年陳情第１３号…","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"八潮の人口は１万２,０００人ぐらいだと思うのですけれども、今高齢化率は何％なのか教えてほしいと求めました。区民の公平性という観点からもシルバーセンターをつくって利用できるようにすべきではないかと思うのですけれども、その点ではいかがか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"今現存している施設のバランス、こういったものを考えますと、決して不足している状況にはないというふうに思っております。ぜひこちらをご活用いただければというふうに考えているところです。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"昔は敬老会館というのですかね、それなので、やはりシルバーセンターとしてこの地域にあるべきだと考えるべきなのではないかと思うのです。特に八潮は団地としてできたので銭湯もないわけですから、今までの陳情の中でも公衆浴場というところからも求められておりましたけれども。","respondent":"宮尾高齢者地域支援課長","answer":"シルバーセンターの入浴と公衆浴場というのはまた別の課題であるというふうに認識をしております。基本的には週２回で、生きがいづくり、こういった施設目的を達成するために備えつけてある設備だというふうに認識をしています。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"シルバーセンターのお風呂というのが八潮地域にはなくて、では海を越えてこちらに来るというふうなことは日常的になかなかできるものではないと思いますので、私はやはり公平性という観点からも八潮団地の中にシルバーセンターをぜひつくるべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"品川区は今、シルバーセンターを多世代交流支援施設に変えていっていると思うのですけれども、今後、多世代交流支援施設ではなくて、高齢者のみを対象としたシルバーセンターを増やしていくという考え方はあるのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"今現在では、あくまでも今現在ではという言い方にはなってしまいますが、現在のところでは、特に新たに箇所数を増やす具体的なプランというか、予定というのは持ち合わせてはおりません。","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問・要望","question":"やはり今後もし何かをつくるとすると、いわゆる昔型のといったらいいのですか、シルバーセンターというよりは。そこはぜひお考えいただきたいとは思っているのですけれども、その辺はこの地域にどのような需要というのをお考えなのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"八潮地域は、まさに高齢化が高い地区だということは我々も重々認識をしております。ひいては健康寿命を延ばしていただきたい、このようなこともいろいろ組み合わせて推進していくことが大切であるというふうに認識をしています。","id":"exchange-063"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今八潮の高齢化率が３４.２％ということでしたけれども、先ほどもあったように、区内一の高齢化のまちになったと陳情にも書いています。シルバーセンターをつくってほしいという陳情は、この間も２回ほど出されていたかと思うのですけれども、八潮の地域がこうした陳情にある要望。","respondent":"宮尾高齢者地域支援課長","answer":"今検討されて、今現存するものをどうやってしっかりと活用していくか、まずはそこをしっかり考えていく必要があると考えています。八潮地区にお住まいの皆さんにご満足いただけるような、そういった施策を展開してまいりたいというふうに考えております。","id":"exchange-064"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"連携は当然されているのでしょうか。今言っているような、そうしたところからもシルバーセンターというものを考えていっていただきたいなというふうに思うのですが、いかがか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"今都市計画課のほうが中心で進めている計画につきましては、私どものほうも適宜情報共有等はさせていただいているところです。既存のものをしっかりと活用していただいて、その中でどんどん交流を深めていく場としてご活用いただければというふうに思っております。","id":"exchange-065"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"ではなくて、地域に格差はあるべきではないと思うので、ぜひつくるべきだと思うのです。地域に格差はあるべきではないと思うのですけれども、いかがか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"繰り返しになりますが、現時点で八潮地区にシルバーセンターを新たにつくるという考えは現状ではございません。で、またいろいろな手段で、あらゆる手段でいろいろな場を使いながら健康寿命の推進に向けてさまざまな施策を展開してまいりたいと考えています。","id":"exchange-066"},{"speaker":"西村委員","kind":"意見","question":"課長の答弁で一定の理解を示しました。あらゆる手段で引き続き使いやすいものに取り組んでいただくことをお願いさせていただき、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、そこで地域の方々がいろいろな声を上げていただいていると思いますので、そこはよく聞いて進めていただきたい。何かそのような施設が２０年後に向けてできるようなことがあるのであれば、ゆうゆうプラザですね、今回この件に関しては不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択です。八潮の将来像に向けての検討会ということで要望等をさせていただいて、今日の課長の答弁でもその方向性を確認できたという理由です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"結論を出すで、採択でお願いしたいと思います。さまざま楽しむことができないというのは、公平性の観点からも改善が必要だと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"あべ委員","kind":"質問","question":"４,０００人、全体の中で品川区の高齢者人口の中では大体何十分の一ぐらいになるのでしょうかね、３０分の１ぐらいですか。そうすると、やはりシルバーセンターが１３カ所あるといっても、八潮の中に全てがあるというような人口ではないのかなというふうには感じております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"}]},{"id":"topic-06","title":"令和２年請願第１号、国に対し「柔軟仕上げ剤などに含まれる香料の成分表示などを求める意見書」の提出を求める請願","agenda":"令和２年請願第１号、国に対し「柔軟仕上げ剤などに含まれる香料の成分表示などを求める意見書」の提出を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どんどん広がっているという状況なので、その数もどんどん増えてくるのではないかなというふうな問題意識を持ったところです。この化学物質過敏症、どのような認識を持っていらっしゃるか、その点についてお聞かせほしいと求めました。","respondent":"鈴木生活衛生課長","answer":"先ほどご説明いたしましたように、危険物質だとか有害物質に関しては法に指定がありまして、それに基づいて規制や指導を行っているところです。しかし、区民の方からの相談件数等は、年に二、三件とはいえ続いておりますので…","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"可能性のある人が２１０万人、それが１２年経った２０１２年には、私はかなりの人数になってくるのではないかなというふうな思いをしているのです。そういうところでの連携をしながら、こういう実態をつかむ必要もあるのではないかと思うのですが、その点ではいかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"ご指摘のような保育園、小中学校といったそれぞれの施設ごとの状況というのは、一元的に現在では把握はできておりません。区としてもちょっとどこまで強制力とまでは言いませんが、協力を依頼できるかというのはちょっと検討の必要があるというふうに考えております。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも、やはりそれに対しては何らかの形での対応というのが求められているのではないかと思うのですけれども、その点ではいかがでしょうか。アレルギーを避けるためにも、表示というのは必要なのではないかなと思うのですけれども、その点についてもお聞かせほしいと求めました。","respondent":"鈴木生活衛生課長","answer":"対応が必要ではないかですが、さっき申し上げたように、法改正対象品目にするところまでは踏み込めないというのが現状だというふうに聞いております。この法での対象品目に指定と表示ですので、アレルゲンに関しては…","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"理解されるとああそれなのかもしれないなというところにつながっていく方もたくさんいらっしゃるのではないかと思うのですね。啓発というか、そういうのも必要なのではないかなと思うのですが、そういう点についてはいかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"根拠が正確に把握できていないので、公の周知の中でそういうことがあるというのは、ちょっと言い切るのは難しいかというふうに考えております。香りに関する注意喚起、自分が大丈夫で使う場合にも、周りへの配慮というようなことは必要かというふうには考えております。","id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひそういう形で配慮を促すような啓発というのですかね、そういうことをしていただきたいと、求めていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"あべ委員","kind":"質問","question":"給食当番の制服といったらいいのですか、あれを洗ってきて、香りのついたものはやめましょうみたいなことに至ったという話も聞いております。そういったところからちょっと考えてみてはいかがかと思いますが、どうか尋ねました。","respondent":"鈴木生活衛生課長","answer":"所管ではありませんので、この後何が対応できるというのは、ちょっと私から今お答えができません。それぞれの所管と意見交換してみないと、ここでできる、できないというお答えは控えします。","id":"exchange-077"},{"speaker":"西村委員","kind":"意見","question":"結論を出すで、不採択でお願いをいたします。法の規制がない中ではありますが、区民の声を聞いていただきながら情報提供を引き続きお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"渡部委員","kind":"質問","question":"課長からの答弁で根拠が何もないというものに対して、では私たちが何かということはできないと思うのです。消費者センターでしょうか、またそういうものが入った際には、意見書は出さないでいいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"若林委員","kind":"意見","question":"科学的な根拠、知見がない中での意見書というのは、ちょっと無理かと思います。ただ、国民生活センター、区の消費者センターのパイプがあるというところで、しっかりと今後の対応をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回の請願は、意見書の提出を求めるものです。さらにこれから大きな問題になってくるのではないかなというふうに思いますので、ぜひ相談窓口の設置も必要なのではないかと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"あべ委員","kind":"質問・要望","question":"ですから、ぜひ掘り起こしをして、可能な範囲で自治体としてまずは対応していただきたいと考えています。まだなかなかその声が見えてこない中で、品川区として、あるいは区議会としてそれを区民に上げる段階にはまだないのかなというふうに感じております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"}]},{"id":"topic-07","title":"令和２年陳情第２号、「羽田新ルート」に伴う騒音関連問題に関する陳情","agenda":"令和２年陳情第２号、「羽田新ルート」に伴う騒音関連問題に関する陳情","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"というか区と言わず、地域の人たちが温かいまちづくりというのでしょうか、声かけをして。その確認です。","respondent":"松山障害者福祉課長","answer":"視覚障害者が安全、安心に外出できるように配慮していくとともに、視覚障害者福祉協会と検討するというところで処理経過を示したものです。２点目につきましては、どこまでこの協会の方とお話をされて、これが出されたのかという経緯は存じ上げません。","id":"exchange-083"},{"speaker":"渡部委員","kind":"質問・要望","question":"今回この陳情で１番がいきなり羽田の問題から出てきて、運用そのものの撤回を求める決議は私たちも上げませんで、冒頭確認をさせていただきました。結論を出して、不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"まずは当事者の方たちのご意見も伺いながら、そうした騒音や外出の心配というところでの話し合いというのは具体的にされたのでしょうか。それは今どうされているのか伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"繰り返しになりますけれども、羽田に特化したことではございませんで、毎年のように視覚障害者福祉協会とは、視覚障害者の方の生活面での生活のしづらさといったものをお伺いして、一緒に考えていくという姿勢は区としても変わるものではございません。","id":"exchange-085"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この飛行確認がされた後、視覚障害者の方が新聞記事で述べているのですが、私たちは全ての音を感じ取りながら真剣に歩いている。そういったところへの対応というのは、どなたにでもそういう声があれば対応していただける時間数を増やしていただけるということでいいか尋ねました。","respondent":"松山障害者福祉課長","answer":"同行援護の支援の充実のところについてのご質問です。お一人お一人の状況あるいは周囲の状況等もそれぞれ加味しながら相談員のほうにご相談いただければと考えています。","id":"exchange-086"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"視覚障害者福祉協会の皆さんにお話を伺ったときに、そしてそれにしっかりと区も強く要望していただいて、充実してもらいたい。その後、２０１７年の請願審査以降、そうした視覚障害者の移動を支えるそうしたハード面というのはどのように求めてきたのかを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"設置に当たってはどうしても優先的なところがあって、そうした形で区としてはこれまでも設置については求めてきてあります。当然ながら具体的にここの信号が聞きづらいとか、それは国には当然伝えますが、区としても警察のほうに区としてしっかり伝えていくという考えです。","id":"exchange-087"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そこの広がりというのですか、やはり視覚障害者の方を見つけても、やはりちょっとなかなか広がっていない部分もあるのかなというふうに感じるのです。合理的配慮や障害者理解というのが、２０１７年の請願以降はどのような広がりを感じられているかどうかという感触を伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"そちらに置かせていただくのをお願いしたり、あとは今年度ですけれども、今年は医師会のほうにお願いをしております。何か配布物等は視覚障害者関連の団体からは来ているのですけれども、十分に話し合いを持って検討していきたいと考えています。","id":"exchange-088"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"出られなくなるようなことがないような支援を、飛ばないのが一番いいのですけれども、そういうところでの支援をぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"あべ委員","kind":"質問・要望","question":"追加でどういった支援が必要かということはぜひ率直なところを意見交換して、できるだけそこは実現していただきたいなというふうに思います。何か今後意見交換ですとか、視覚障害の方々に対してそういうお話をされる予定というのはありますか。","respondent":"松山障害者福祉課長","answer":"まだ日程調整等をしておりませんので、また具体的に改めて意見交換する場を設けていきたいと考えています。技術の進歩とともにいろいろな生活用具が開発されておりますので、それもあわせて研究をしていきたいと考えています。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、そのときに視覚障害者の声というのも聞かれているでしょうかというのをお聞きしたいのですね。私は視覚障害者の声を聞かれているのでしょうかということと、それを国に届けていただきたいと思うのですけれども、その点について説明を求めました。","respondent":"鈴木都市計画課長","answer":"こうした声を今私大分要約してご説明しましたが、電話が主でしたけれども、聞き取ったものを職員はしっかり届ける形で記録として残しています。先ほど障害者福祉課長のほうでもご説明させていただきましたが、それは先ほどご説明したようにしっかり国のほうに届けていきたいです。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点で言えば、国策なのだから区域に入らなくても防音装置をつけろとかというふうなことも国に求めてきたわけではないですか。音響信号だったり、そういう点字ブロックだったり、そういう点では区としてはいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"そうした設置については警視庁のほうに訴えかけをしてきたわけですけれども、警視庁のほうからなかなか優先順位がという話もございました。あるいは直接区としても警察のほうには、これは団体の方の声をしっかりお聞きした上でですけれども、しっかり届けていきたいです。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私たちは今からでも新ルート計画はストップさせたいというふうに思っております。ただ、そういう形で多くの人たちが被害をこうむるということが起こっているわけですから、そこのところの対応をぜひお願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。課長のご答弁でありましたように、環境整備とともにご不安をくみ取りながら引き続き真摯なご対応をお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"若林委員","kind":"質問・要望","question":"２０１７年の請願のとき以降のご対応については今日確認をさせていただいて、しっかり拡充を図っている中で。ぜひ一緒に聞いたほうが、そういったセッティングの仕方も工夫していただいて、引き続き一生懸命取り組んでいただきたいなというふうに要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実機飛行が行われて、いよいよ本当に実際の被害がどういうふうに起こって来るのかというふうなことを区民が経験するという状況になりました。その対応もぜひ強力に求めていきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"あべ委員","kind":"提案","question":"１番のほうは特に私は異論がございません。ただ、ちょっとこのご提案されている方法よりもう少し方法があるのかなというふうに感じておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"あべ委員","kind":"質問","question":"あるいは何か２人がかりでおろすタイプですかね、ここは実際に避難ができる避難経路としていくのか、その目安を教えてほしいと求めました。その階段を使って避難をするという避難経路については、そのように現場では掲示されているというふうに考えてよろしいのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"現時点では１名の方が利用されておりますので、その１名に対応できるようにということで考えております。今後、複数名になってきますので、またそれに対応できるように利用者の受け入れに合わせて避難ができるような体制を整えていきたいと考えています。","id":"exchange-098"},{"speaker":"あべ委員","kind":"質問","question":"あれは大人用なのですか。あれは大人用だとどのように使うのか教えていただけますか。","respondent":"築山障害者施策推進担当課長","answer":"選定に当たっては先ほど説明しましたように、介助のしやすさとかベッドの作動というところで考えました。１３０cm程度ありますので、ちょっと横になってもらう、あとは個々の障害特性等に合わせたやり方等での対応ということを考えております。","id":"exchange-099"},{"speaker":"あべ委員","kind":"質問","question":"いろいろ意見も言わせていただいたのですけれども、やはり対外的に顔になる立場の方というのが必要なのではないかなと思います。組織として動いていく、やはり責任のある窓口の方が必要なのではないかと思いますけれども、そこの議論というのは進んでいますか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"先ほどの統括責任者という件ですけれども、また次回の指定管理のあり方について、現在内部のほうで検討をしておりますので、また公募等も含めて検討をしているところですので、その際に考えたいと考えています。","id":"exchange-100"},{"speaker":"あべ委員","kind":"質問","question":"今の公募というのは、つまりは、今の事業者以外の方を入れるということを前提にこの組織の今後を考えていらっしゃるということなのでしょうか。２年半になってしまうのかしら、この３年間きっちり一緒につくっていく気持ちが薄いのではないですかと感じたのですけれども、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"公募を検討している理由なのですけれども、現在は障害児者総合支援施設の建物管理を区が実施しております。次回の公募に当たっては、建物管理も含めた一体的な管理運営ができるところを念頭にした公募というふうに考えているところです。","id":"exchange-101"},{"speaker":"あべ委員","kind":"意見","question":"そこのところをぜひ誤解のないようにお願いしたいのですけれども、いろいろな障害福祉のあり方を品川に根づかせようという理想を持ってスタートさせたところですので、その思いをしっかりと活かす形で公募につなげてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、お話を伺っても本当に一生懸命されているというふうに思っていますし、ぜひ一緒に充実をさせていくという立場でしてほしいと求めました。それから具体的なところでもお伺いしたいのですけれども、スプリンクラー、さらにキッチンとかもＩＨですよね。","respondent":"築山障害者施策推進担当課長","answer":"あくまで建物の管理運営体制をどうしていくかというところの検討の一つとして公募の実施も検討の一つの中に含めて考えているですので。基本的には年２回以上と決められておりますけれども、管理運営上必要な回数は今後も実施していきたいと考えています。","id":"exchange-103"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、地下１階の厨房とカフェレストランのところはＩＨではなくてガスが使用されているのかという確認だけさせてほしいと求めました。資格者がすぐに駆けつけて、これは施設管理の課長から伺ったのですけれども、その点はちょっと確認をお願いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"それから非常用エレベーターなのですけれども、避難のときですが、鍵がありまして、鍵を使えば動かすことができるものになっております。ただ、そういう資格を持った消防隊員が救助の際に使うということを考えております。","id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"では、基本的には階段を使って避難するというやり方だということでしょうか。それから現状で事業者とか利用者から改善してほしいという、実際に使われている方から声が上がっているのかということを説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"必要な設備等については設置をしています。ただ今後そういう声が上がれば、先ほどご説明もしたのですけれども、合理的配慮はしていきたいというふうに思っております。","id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"働かれている方ですとかが、そういうところではちょっとそういう紙面どおりにはいかないのではないかなというふうな思いがしているところです。統括防火管理者は、一応品川区の係長と決められているということで確認させていただいていいか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"ですので、そこは合理的配慮というところで個々の状況に応じた対応が必要になってくるものだという考えでおります。それから統括防火責任者につきましては、現在、障害児者総合支援施設担当主査、係長級の者が担っております。","id":"exchange-106"},{"speaker":"渡部委員","kind":"質問・要望","question":"２年半後にどういう形になるかというのはちょっと置いといて、確認だけすると、僕は問題ないと思う。確認は４件の陳情を通して法的に何か問題があるようなものなのかどうか、一つ確認したいのは、何かあったときに。","respondent":"築山障害者施策推進担当課長","answer":"それから避難等に当たりましては４事業者、それから委託事業者も含めて連携をして対応しています。いざというときに協力体制をとれるようにということで、日常の連携のほうも継続して行っていきたいと考えています。","id":"exchange-107"},{"speaker":"あべ委員","kind":"確認","question":"すみません、一つ聞き落としました。経路図は既に掲出されているということで、避難経路についての利用者等に対する説明というのも既になされているかどうかだけ確認させてください。","respondent":"築山障害者施策推進担当課長","answer":"実施しております。","id":"exchange-108"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いをいたします。引き続き声を聞いていただきながら、見直しが必要なところは見直していただいて、配慮をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-109"},{"speaker":"若林委員","kind":"質問","question":"本日結論を出すで、不採択で結構です。内容について説明をお聞きすることができましたのでという理由です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-110"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出すということで、趣旨採択でお願いしたいと思います。ただ、単純構造ではないというところからもあると思うのですけれども、不安に対してはそういうときこそ丁寧な説明をしていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"あべ委員","kind":"確認","question":"先ほど確認させていただいたように、そして説明もされているということで、この陳情の趣旨自体は既に満たされていると判断をさせていただきました。陳情者にはその点を指摘していただいて、整備をするきっかけになったことはむしろ感謝したほうがいいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"結論を出すで、不採択でお願いしたいと思います。現場から特に改善してほしいという声は出されていないということですし、このことは当たらないというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-113"},{"speaker":"あべ委員","kind":"提案","question":"それで、不採択でお願いいたします。今後とも現場の声を聞きながら、具体的に声が出てくるのを待つだけではなくて、職員の方も含めてさまざまな改善提案に応じてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"本日も確認をさせていただきまして、品川区が施設管理の責任を負うとして係長が配置され、統括防火責任者となっているということです。責任者を曖昧にしているとの指摘は当たらないと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"あべ委員","kind":"質問・要望","question":"前回議論したこととかなりかぶるところではあります。ただ、それから対外的に誰が窓口になっているかわかりにくいという部分、ここは改善をしていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いしたいと思います。この陳情にある避難経路図は既に掲出されているということですので、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-117"},{"speaker":"あべ委員","kind":"確認","question":"先ほど確認させていただいたように、重ねて採択をする必要はないかなというふうに思っております。ただ、これをご指摘いただいたことについてはやはり感謝しなければいけないと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-118"}]},{"id":"topic-08","title":"令和２年陳情第４号、ドア・トゥー・ドアの施設送迎の実施を求める陳情","agenda":"令和２年陳情第４号、ドア・トゥー・ドアの施設送迎の実施を求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者でできない理由というのは何かあるのでしょうか。そういう仕組み上の高齢者との違いというのもあわせて教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"送迎に添乗員が１人乗った場合、そこはどの事業所も安全性の確保という観点からドライバーにだけ任せることはできないというご希望が非常にあります。そういうものを考えながら安全性も確保しながら同乗させているケースがございまして、非常に個別性が高いものですから…","id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう対応を国の制度としてもっとやるべきなのかなという思いがするのですが、そういう方向というのは出されていたりはしないのでしょうか。当事者からはすごくドア・トゥー・ドアでやっていただきたいという、そういう要望というのはすごく強いと思うのですよね。","respondent":"松山障害者福祉課長","answer":"送迎の報酬についても国のほうできちんと規定されておりますので、特に報酬といった問題でもないと認識しております。全体を一気に解決できるということではなく、できるところから実施していくということで、現場で対応をしていくというものです。","id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここで言われているのは生活介護というふうなことなのですけれども、生活介護の送迎がどうやったらできるかというところで、その点いかがでしょうか。他の自治体も同じような状況で、ドア・トゥー・ドアはできないという状況になっているのか、その点もわかったら説明を求めました。","respondent":"松山障害者福祉課長","answer":"課題としては認識しておりますが、具体的にどうやったらできるかというのがなかなかすぐに現場のほうからも上がってはきておりません。現状としては現場の中で安全に円滑に送迎を実施して、なかなかそこまでの、まだ議論までは全く到達はしていないです。","id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは当事者それから家族の方にとっては切実な要望だと思いますので、現実から出発すると無理だということになってしまうと思うのですけれども、これを実現するためには何をどうすればできるのかというふうなところでの検討にぜひ入っていただきたいということで要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-122"},{"speaker":"あべ委員","kind":"質問・要望","question":"ご家族の方にとっては、やはりこれができないとなかなか難しいことというのがあるので、方向性としてはぜひ目指していただきたいと思うのです。少しでもやるためにはどんな工夫があり得るかというような形での投げかけをしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"生活介護の送迎状況につきましては、今後も生活介護の事業所の団体とかもありますので、その中で具体的に話をしていければと考えています。","id":"exchange-123"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。現場のご苦労もかいま見られましたので、不採択でお願いしますが、引き続き区民の声を聞いていただけますようお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-124"},{"speaker":"渡部委員","kind":"質問・要望","question":"やはり当然話し合って決めているのだけれども、少しでも社会に接してもらって、まちに出てもらってというのもある一方で考え方かもしれないのですよ。ですから、やはり当事者同士さまざまな話し合いというのは引き続きやっていただきたいという中で、この件については不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出すで、不採択で結構です。ポイント送迎の中でもその日の体調によって今日はどうしてもちょっとそこまで行けないのだけれどもという、寄り添ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-126"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本日結論を出すということで、採択でお願いしたいと思います。ぜひどうしたら実現できるかというところで検討をしていただいて、実現に向けて取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-127"},{"speaker":"あべ委員","kind":"意見","question":"本日結論を出すということで、趣旨採択でお願いしたいと考えています。ただ、方向性としてはいろいろな工夫を重ねていって少しずつ充実させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-128"}]},{"id":"topic-09","title":"令和２年陳情第５号、移動支援サービス従事者研修の適正な事業者への委託を求める陳情","agenda":"令和２年陳情第５号、移動支援サービス従事者研修の適正な事業者への委託を求める陳情","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"今のご説明ですと、この３月に行われるのは法人の自主事業として行われて、新年度からは区がいずれかの事業者に委託して行うことを考えているということで、その委託先というのは都の指定事業者ということになっていることをお考えですよねとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"委員お話しのとおり、東京都の指定をとった事業所として今私どもが認知しておりますのは品川総合福祉センターですので、品川総合福祉センターのほうに補助を出して研修をしていただくです。","id":"exchange-129"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"５名というのはすごく少ない人数のように思うのですが、何か７０人とかかなりたくさんの人数の応募があって、あったら説明を求めました。","respondent":"松山障害者福祉課長","answer":"来年度につきましては、周知を工夫しまして、多くの人数に参加していただければと考えています。２点目の補助金の額ですけれども、４０万円を想定しております。","id":"exchange-130"},{"speaker":"渡部委員","kind":"意見","question":"今後はそのところでしっかりやっていくという話が僕はあったと思うので、何か二次審議みたいな感じになっている内容で、何が言いたいのかわからない。不採択ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-131"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"結論を出すということで、趣旨採択でお願いしたいと思います。先ほど皆さんも言われているように、区の姿勢は明確だということで、今回もさらに確認をさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-132"},{"speaker":"あべ委員","kind":"意見","question":"結論を出すということで、不採択でお願いいたします。この陳情者もこの書面の中でご理解いただいているにもかかわらず、これが出てきているという、ちょっと不思議な感じがしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-133"}]},{"id":"topic-10","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"せお議員から医療的ケア児への対応についての質問があったと思うのですけれども、どこら辺までこの委員会で聞けるのか、施設の中だけでも構いません。その場合に、歩けるケア児とそうでないケア児、あるいは知的におくれのないケア児、それぞれについて状況がわかれば教えていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-134"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3556#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":105442,"voices":361}}]);
